                    next = setmetatable(obj,self)
                    if next.init then next:init() end
                    node[key] = next
                end
                return next
            end
        else
            function mt:__call(...)
                local obj = {}
                for i = 1, #names do
                    local v = select(i,...)
                    local c,ii = checks[i](v)
                    if not c then 
                       reporterr(i,name,tns[i],v,ii) 
                    end
                    obj[names[i]] = v
                end
                local r = setmetatable(obj,self)
                if r.init then r:init() end
                return r
            end
        end
        function class:__tostring()
