    local s = self[1]
    for i = 2,N do
        s = fn(i,s,self[i],...)
    end
    return s
end
function List:reduceor(init,fn,...)
    if type(fn) ~= "function" then
        fn = selector(fn)
    end
    local N = #self
    if N == 0 then
      return init
    end
    local s = self[1]
    for i = 2,N do
        s = fn(s,self[i],...)
    end
    return s
end

function List:existsi(fn,...)
    if type(fn) ~= "function" then
        fn = selectori(fn)
    end
    for i,v in ipairs(self) do
        if fn(i,v,...) then
            return true
        end
    end
    return false
end
function List:exists(fn,...)
    if type(fn) ~= "function" then
        fn = selector(fn)
    end
    for i,v in ipairs(self) do
        if fn(v,...) then
            return true
        end
    end
    return false
end

function List:alli(fn,...)
    if type(fn) ~= "function" then
        fn = selectori(fn)
    end
    for i,v in ipairs(self) do
        if not fn(i,v,...) then
            return false
        end
    end
    return true
end
function List:all(fn,...)
    if type(fn) ~= "function" then
        fn = selector(fn)
    end
    for i,v in ipairs(self) do
        if not fn(v,...) then
            return false
        end
    end
    return true
end

package.loaded["terralist"] = List

end)

