module('let.source', function(require, ...)
-- The source vocabulary: positions and tokens. It references nothing.
return function(context)
    context:Define [[
module Source {
    Span  = (string file, number line, number column)
    Range = (Span start, Span stop)
    Token = (string kind, string spelling, string? value, Span span)
}
    ]]
end

end)

-- let/semantic.lua
module('let.semantic', function(require, ...)
-- The semantic vocabulary: the choices every other layer names.
--
-- This layer sits below Syntax and below Belt and references nothing above it. It owns the
-- shared choices (capability, purity, phase because Chain names them), the operators, and the
-- type word. `Type.Word` names a template by *number* rather than by `Chain.Template`, so that
-- Semantic never references Chain; that asymmetry is what keeps the layers acyclic.
--
-- `Copy` is deliberately absent: it is derived from the type (a method, not a constructor), and
-- `Access` is absent because a call-site use of a place is *syntax* (Syntax.Expr.Move/Borrow).
return function(context)
    context:Define [[
module Semantic {
    Capability = Read | Mut | Own | OwnMut
    Purity     = Pure | Ordered
    Phase      = Runtime | Construction

    UnaryOp    = Negate | Not | BitNot
    BinaryOp   = Add | Subtract | Multiply | Divide | Remainder
               | Equal | NotEqual | Less | LessEqual | Greater | GreaterEqual
               | BitAnd | BitOr | BitXor | ShiftLeft | ShiftRight
               | And | Or
    Conversion = ToFloat | ToInt | ToU8 | ToU32 | ToF32 | ToCString | ToText | TextSize | IsNull

    Field      = (string? name, Type type, boolean mutable)
    Type       = Int | U8 | U32 | Float | Float32 | Bool | Unit | Text | Effect
               | CString | CPointer
               | Named(string name)
               | Aggregate(Field* fields, string? name)
               | Sum(Type* alternatives)
               | Arrow(Type from, Type to)
               | Do(Type result)
               | TypeWord
               | Word(number template, number prefix)
}
    ]]

    local S = context.Semantic

    -- §11.2: "Conversions are their own choice ... because `ToFloat` and friends are DICTIONARY
    -- words, not operators." So each is a one-stage word, and this table IS its declaration: the
    -- type it reads and the type it produces. It lives in `Semantic` because it is the shared
    -- meaning of a name, and both `Resolve` (which builds the word) and `Contract` (which types it)
    -- must agree about it.
    --
    -- `ToText` is deliberately absent. A `Text` has a known length and no terminator guarantee,
    -- while a `CString` is terminated and borrowed, so going the other way needs a length that the
    -- source does not have -- which is a representation question and not a table entry.
    S.conversions = {
        ToInt = { from = S.Float, to = S.Int },
        ToFloat = { from = S.Int, to = S.Float },
        ToU8 = { from = S.Int, to = S.U8 },
        ToU32 = { from = S.Int, to = S.U32 },
        ToF32 = { from = S.Float, to = S.Float32 },
        ToCString = { from = S.Text, to = S.CString },
        TextSize = { from = S.Text, to = S.Int },
        IsNull = { from = S.CPointer, to = S.Bool },
    }

    -- What an integer literal DENOTES, which is not what it is spelled as: `0x10`, `0b10000` and
    -- `16` are one value, and label identity depends on that -- two labels collide by VALUE,
    -- numerically equal spellings such as 1 and 0x1". It lives here because the belt carries only
    -- the SPELLING (`Belt.IntegerLiteral(string spelling)`), so the conversion is needed below
    -- Syntax as well as inside it, and two copies of a base conversion is two chances to disagree
    -- about underscores.
    -- §S38: one owner of a literal's value, and this is the float half of it. Underscores are the
    -- spelling's business (`1_0.5` is one number), so they go before the conversion.
    function S.float_value(spelling) return tonumber((spelling:gsub('_', ''))) end

    function S.integer_value(spelling)
        local digits = spelling:gsub('_', '')
        if digits:match('^0[xX]') then return tonumber(digits:sub(3), 16) end
        if digits:match('^0[bB]') then return tonumber(digits:sub(3), 2) end
        return tonumber(digits)
    end


    -- **Copy is derived, never stored** (DESIGN §2.5). A type answers whether it is Copy, and the
    -- rules are §11.3 (primitive), §2.5 (a record, and its `mut` members), §11.5 (a sum) and
    -- §12.4 (the two foreign views, which are Copy). A record with a `mut` member is *not* Copy
    -- even when every member is, because interior mutability is observable state -- which is what
    -- makes `{ let x mut = 1 }` the first non-Copy value this compiler can build.
    --
    -- `word` is deliberately `false`: whether a word is Copy depends on the packet its template
    -- produces, which is a fact about a template and not about the type word. That needs the
    -- interface as a lookup, and it arrives with the first word-valued member.
    local COPYABLE = {}
    for _, name in ipairs{'Int', 'U8', 'U32', 'Float', 'Float32', 'Bool', 'Unit', 'Text',
                         'CString', 'CPointer'} do
        COPYABLE[S[name]] = true
    end

    -- §12.2 says Contract "checks rather than infers", and a check needs EQUALITY. Scalars are
    -- unique classes so identity is right for them; everything structural compares by structure; a
    -- `Named` type is interned so identity is right for it too. This is the same shape as `copyable`
    -- -- a derived property as a method -- and it exists for the same reason: a type is a WORD, so
    -- two occurrences of one type word are one type, and `==` on two tables says they are not.
    function S.Type:equals(other) return self == other end

    function S.Aggregate:equals(other)
        if not S.Aggregate:isclassof(other) or #self.fields ~= #other.fields then return false end
        for index, field in ipairs(self.fields) do
            local peer = other.fields[index]
            if field.mutable ~= peer.mutable or field.name ~= peer.name then return false end
            if not field.type:equals(peer.type) then return false end
        end
        return true
    end

    -- §3.5's construction rule, as a derived method: which alternative does this type select?
    -- Returns the index AND how many alternatives matched, because "none" and "more than one" are
    -- different errors -- one says the value is not a member, the other says the sum cannot say
    -- which member it is -- and a caller that only got nil could not tell them apart.
    --
    -- It is derived rather than chosen: the alternative is the one whose type the value ALREADY has,
    -- so there is nothing to coerce. Two alternatives of one type make a sum no value can inhabit
    -- implicitly, which is honest rather than a limitation to work around.
    -- Nominal means identified by name -- that is the whole content of §S3's nominality, and it is
    -- why interning was never the real rule: two `Named('Handle')` values ARE one type because they
    -- name one type, not because a table happened to hand back the same object.
    function S.Named:equals(other)
        return S.Named:isclassof(other) and self.name == other.name
    end

    function S.Sum:alternative(type_)
        local found, count = nil, 0
        for index, alternative in ipairs(self.alternatives) do
            if alternative:equals(type_) then
                found, count = index - 1, count + 1
            end
        end
        return found, count
    end

    function S.Sum:equals(other)
        if not S.Sum:isclassof(other) or #self.alternatives ~= #other.alternatives then return false end
        for index, alternative in ipairs(self.alternatives) do
            if not alternative:equals(other.alternatives[index]) then return false end
        end
        return true
    end

    function S.Arrow:equals(other)
        return S.Arrow:isclassof(other) and self.from:equals(other.from) and self.to:equals(other.to)
    end

    function S.Do:equals(other)
        return S.Do:isclassof(other) and self.result:equals(other.result)
    end

    -- §S3's nominality is a NUMBER and a PREFIX, so two mentions of one word are ONE type -- and
    -- `Word` is the member of this closed set that never got an `equals`. `S.Type:equals` is
    -- identity, which is right for a scalar (one instance) and for an interned `Named`, so
    -- `let f : square = square` compared two equal-valued `Word(1, 0)`s, called them different
    -- types, and refused a program in which the annotation and the value disagreed about nothing.
    -- A rule that has to hold for every member of a set is a rule about the SET: the tell for a
    -- missing member is a comparison that succeeds on values and fails on types.
    function S.Word:equals(other)
        return S.Word:isclassof(other) and self.template == other.template
            and self.prefix == other.prefix
    end

    -- §11.3's scalar type words, BY NAME. This is a semantic fact -- the name of a type word -- and it
    -- lives here because two layers need the same answer: `Resolve` to make a type name an expression
    -- (§2.4) and `Contract` to know that `s.Int` names the `Int` alternative (§S54). Two copies of a
    -- name table is two chances to disagree about which names are type words.
    S.primitive = {
        Int = S.Int, U8 = S.U8, U32 = S.U32, Float = S.Float, Float32 = S.Float32,
        Bool = S.Bool, Unit = S.Unit, Text = S.Text,
        CString = S.CString, CPointer = S.CPointer,
    }

    function S.Type:copyable() return COPYABLE[self] or false end

    -- §3.7: a `mut` member is INTERIOR MUTABILITY -- the value is writable through a binding whatever
    -- the binding's own mutability says -- so writability is a property of the TYPE rather than of the
    -- name that holds it. Derived beside `copyable` for the same reason: nothing declares it twice. It
    -- is recursive, because `r.inner.x` reaches a `mut` member through a record that is not itself
    -- mutable: what has to be addressable is the storage the path STARTS in, so one `mut` step
    -- anywhere below it is enough.
    function S.Type:interior_mutability() return false end

    function S.Aggregate:interior_mutability()
        for _, field in ipairs(self.fields) do
            if field.mutable or field.type:interior_mutability() then return true end
        end
        return false
    end

    function S.Sum:interior_mutability()
        for _, alternative in ipairs(self.alternatives) do
            if alternative:interior_mutability() then return true end
        end
        return false
    end

    function S.Aggregate:copyable()
        for _, field in ipairs(self.fields) do
            if field.mutable or not field.type:copyable() then return false end
        end
        return true
    end

    function S.Sum:copyable()
        for _, alternative in ipairs(self.alternatives) do
            if not alternative:copyable() then return false end
        end
        return true
    end
end

end)

-- let/dict.lua
module('let.dict', function(require, ...)
-- The dictionary vocabulary: a construction word's source form.
--
-- A dictionary entry *is* a chain (Chain.Template), carrying a phase and a purity. This module
-- exists only for the entries whose terminal is a form: the construction words with bespoke
-- syntax, `if`, `while` and `switch` (spec §12.3). Their behaviour lives in Lower.
return function(context)
    context:Define [[
module Dict {
    Form = (string name, Slot* slots)
    Slot = Expression | Region
}
    ]]
end

end)

-- let/chain.lua
module('let.chain', function(require, ...)
-- The chain vocabulary: the one construct.
--
-- A template interleaves prelude *groups* and *stages*. `Group(at, preludes)` marks the preludes
-- that run before stage `at` and names their definitions: a group is not just "here", it says
-- *which* preludes, because the preludes are declarations with their own ids and the group is what
-- orders them.
--
-- `Residual(template, prefix)` names the record after `prefix` stable stages. `prefix <=
-- transient_from`, because a `mut` stage cannot be stored and a chain is transient from its first
-- one (spec §5.3, DESIGN §2.2).
--
-- `Terminal` is Data, Do, or a Form. The first two make the chain a value word or a type word; the
-- third makes it a construction word, whose operations the compiler executes.
return function(context)
    context:Define [[
module Chain {
    Terminal = Data | Do | Form(Dict.Form form) | Host(string symbol)
             | Convert(Semantic.Conversion kind)
    Capture  = (number binder, string name, Semantic.Capability mode)

    Item     = Group(number at, number* preludes)
             | Stage(number index, Semantic.Capability capability,
                     Semantic.Type type, number binder)

    Template = (string name, Item* items, number stages, number transient_from,
                Terminal terminal, Semantic.Type? result, Capture* captures,
                Semantic.Phase phase, Semantic.Purity purity)
    Residual = (Template template, number prefix)
}
    ]]

    local Chain = context.Chain

    -- §2.2: `R(t,k) = captures + stage values 0…k-1 + prelude bindings of groups 0…k`. The layout is a
    -- fact about the TEMPLATE, so it is asked OF the template, and it lives here rather than in a phase
    -- because two phases need it for two different questions -- `Lower` for what a name's slot holds,
    -- `Contract` for what a value's type is -- and the members are this vocabulary's fields.
    function Chain.Template:members(k)
        local members = {}
        for _, capture in ipairs(self.captures or {}) do
            members[#members + 1] = capture.binder
        end
        for _, item in ipairs(self.items) do
            if Chain.Group:isclassof(item) then
                if item.at <= k then
                    for _, id in ipairs(item.preludes) do members[#members + 1] = id end
                end
            elseif item.index < k then
                members[#members + 1] = item.binder
            end
        end
        return members
    end
end

end)

-- let/syntax.lua
module('let.syntax', function(require, ...)
-- The surface vocabulary: what the source says.
--
-- Two things here are deliberate. `TypeExpr` has no application form: `List with Int` is `with`
-- (spec §3.1, "a type application is not a distinct form"), so `Ref` carries only a name.
-- Conversions are their own choice -- `Conversion` -- rather than sharing a sum with `Negate`,
-- because `ToFloat` and friends are dictionary words, not operators.
return function(context)
    context:Define [[
module Syntax {
    UnaryOp    = Negate | Not | BitNot
    BinaryOp   = Add | Subtract | Multiply | Divide | Remainder
               | Equal | NotEqual | Less | LessEqual | Greater | GreaterEqual
               | And | Or | BitAnd | BitOr | BitXor | ShiftLeft | ShiftRight
    Conversion = ToFloat | ToInt | ToU8 | ToU32 | ToF32 | ToCString | ToText | TextSize | IsNull

    TypeExpr  = Ref(string name)
              | Record(TypeField* fields)
              | Tuple(TypeExpr* elements)
              | Arrow(TypeExpr from, TypeExpr to)
              | Sum(TypeExpr left, TypeExpr right)
              | Do(TypeExpr result)
              attributes (Source.Span span)
    TypeField = (string name, boolean mutable, TypeExpr type, Source.Span span)

    Program   = (Chain file)
    Binding   = (string name, boolean mutable, TypeExpr? constraint, Chain value,
                 Source.Span span, Source.Range name_range)
    Chain     = (Item* items, Terminal? terminal, Source.Span span)
    StageSpec = (string name, Semantic.Capability capability, TypeExpr? constraint,
                 Source.Span span, Source.Range name_range)
    Item      = Stage(StageSpec stage)
              | Prelude(Binding binding)
              | Extern(string name, boolean pure, string? symbol, StageSpec* parameters,
                       TypeExpr? result, Source.Span span, Source.Range name_range)
              | Host(string name, string? destroys, string? borrows, Source.Span span,
                     Source.Range name_range)
    Terminal  = Data(Expr value) | Body(Stmt* statements, TypeExpr? result)
              attributes (Source.Span span)

    Expr      = Name(string name) | Integer(string spelling) | Float(string spelling)
              | Boolean(boolean value) | Text(string value) | Unit
              | Unary(UnaryOp operator, Expr operand)
              | Binary(BinaryOp operator, Expr left, Expr right)
              | Convert(Conversion kind, Expr value)
              | Specialize(Expr word, Expr argument)
              | Invoke(Expr word, Expr* arguments)
              | Word(Chain chain)
              | NamedAggregate(Binding* members)
              | PositionalAggregate(Chain* elements)
              | Project(Expr base, string name, Source.Range member_range)
              | Index(Expr base, Expr index)
              | Move(Expr place) | Borrow(Expr place)
              | TypeSum(TypeExpr left, TypeExpr right)
              attributes (Source.Span span)

    Stmt      = Local(Binding binding) | Assign(Expr place, Expr value)
              | Return(Expr? value) | Discard(Expr value)
              | If(Expr condition, Stmt* yes, Stmt* no)
              | While(Expr condition, Stmt* body)
              | Break | Continue
              | Switch(Expr subject, Case* cases, Stmt* otherwise)
              attributes (Source.Span span)
    Label     = Shape(TypeExpr type) | Constant(Expr value)
    Case      = (Label* labels, string? binds, Stmt* body, Source.Span span)
}
    ]]
end

end)

-- let/belt.lua
module('let.belt', function(require, ...)
-- The representation vocabulary.
--
-- Belt owns representation only. It has no `Word`, `Arrow`, `Do`, `TypeWord`, `Address`, `Borrow`
-- or `Callable`: the first four are *type words* and live in Semantic, the next two are reference
-- apparatus and are a lowering fact, and a uniform callable is a vtable (DESIGN §S2, §S5). What it
-- keeps is the one representation the ownership model needs -- `Cell`, the storage a captured
-- place lives in -- and `Op = Pure | Ordered`, so "pure folds, ordered schedules" is dispatch.
return function(context)
    -- A sum's fields are its TAG and its PAYLOADS: field `0` is the tag, and field `1+K` is
    -- alternative `K`'s payload (§3.5, §S59). Both are KNOWN offsets, so every field read of a sum
    -- is a pure `LoadField`, exactly like a record's. The read that would NOT be pure is one that
    -- names an alternative without having tested the tag -- and the language has no such read,
    -- because a payload is reached by the arm that matched it. There is nothing left to trap.
    context:Define [[
module Belt {
    Ref       = (number distance, number output)

    PureOp    = IntegerLiteral(string spelling) | FloatLiteral(string spelling)
              | BooleanLiteral(boolean value) | UnitLiteral | TextLiteral(string value)
              | TextOf(Ref pointer, Ref size)
              | Unary(Semantic.UnaryOp operator, Ref operand)
              | Binary(Semantic.BinaryOp operator, Ref left, Ref right)
              | Convert(Semantic.Conversion kind, Ref value)
              | Construct(Ref* fields)
              | InjectSum(number index, Ref payload)
              | LoadField(Ref record, number field)
              | FieldAddress(Ref cell, number field)
              | PureHostCall(string symbol, Ref* arguments)
    OrderedOp = CheckedBinary(Semantic.BinaryOp operator, Ref effect, Ref left, Ref right)
              | CallFunction(number target, Ref effect, Ref* arguments)
              | HostCall(string symbol, Ref effect, Ref* arguments)
              | Allocate(Ref effect, Ref initial)
              | Load(Ref effect, Ref cell) | Store(Ref effect, Ref cell, Ref value)
              | StoreField(Ref record, number field, Ref value)
              | Move(Ref effect, Ref value) | Destroy(Ref effect, Ref value, string destructor)
    Op        = Pure(PureOp operation) | Ordered(OrderedOp operation)

    Field       = (string? name, Type type, boolean mutable)
    Type        = Int | U8 | U32 | Float | Float32 | Bool | Unit | Text | Effect
                | CString | CPointer
                | Named(string name) | Aggregate(Field* fields) | Sum(Type* alternatives)
                | Cell(Type contents)
    Instruction = (Op operation, Type* results, Source.Span? span)
    Parameter   = (Type type, Semantic.Capability capability)
    Signature   = (Parameter* parameters, Type* results)
    Edge        = (number target, Ref* arguments)
    Exit        = Return(Ref* values)
                | Jump(Edge edge)
                | Branch(Ref condition, Edge yes, Edge no)
                | TailCall(number target, Ref effect, Ref* arguments)
                | Trap(Ref effect, string reason)
    Block       = (Parameter* parameters, Instruction* instructions, Exit exit)
    Function    = (string name, Signature signature, Block* blocks, boolean exported)
    Program     = (string name, Chain.Template* templates, Function* functions)
}
    ]]

    -- §3.5's injection is derived by comparing the value's type with the sum's alternatives, and
    -- `Lower` compares BELT types -- the semantic side has its own `equals` because the two are
    -- separate vocabularies (§10). Scalars are unique classes so identity is right; aggregates, sums
    -- and cells compare structurally; a named type is a name.
    local B = context.Belt
    function B.Type:equals(other) return self == other end
    -- §S49: this side MIRRORS the semantic equality, because `Lower` compares belt types and
    -- `Belt.Sum:alternative` is where it matters. A host type is nominal (§S44), so two `B.Named`
    -- values name one type exactly when their names are equal -- and this was missing here while
    -- `Semantic.Named:equals` had said so since §S44, which made every sum with a host alternative
    -- unable to inject or to discriminate. Nothing reached it until a binder had to look one up.
    function B.Named:equals(other)
        return B.Named:isclassof(other) and self.name == other.name
    end
    function B.Aggregate:equals(other)
        if not B.Aggregate:isclassof(other) or #self.fields ~= #other.fields then return false end
        for index, field in ipairs(self.fields) do
            local peer = other.fields[index]
            if field.mutable ~= peer.mutable or field.name ~= peer.name then return false end
            if not field.type:equals(peer.type) then return false end
        end
        return true
    end
    function B.Sum:equals(other)
        if not B.Sum:isclassof(other) or #self.alternatives ~= #other.alternatives then return false end
        for index, alternative in ipairs(self.alternatives) do
            if not alternative:equals(other.alternatives[index]) then return false end
        end
        return true
    end
    function B.Cell:equals(other)
        return B.Cell:isclassof(other) and self.contents:equals(other.contents)
    end

    -- Which alternative of a sum this type selects, and how many matched. The same rule as
    -- `Semantic.Sum:alternative`, on the side of the mapping that `Lower` works in.
    function B.Sum:alternative(type_)
        local found, count = nil, 0
        for index, alternative in ipairs(self.alternatives) do
            if alternative:equals(type_) then found, count = index - 1, count + 1 end
        end
        return found, count
    end
end

end)

-- let/judge.lua
module('let.judge', function(require, ...)
-- What the analyses produce: definitions, initializers, terminals, statements, interfaces.
--
-- A `Binder` is a *reference* to a declaration; a `Definition` **is** the declaration. Resolve
-- produces definitions plus a resolved `Initializer` per declaration, Contract fills one
-- `Interface` per definition, and a value binding is not a special case -- a data terminal with no
-- stages *is* a value, so its interface is a zero-stage data word (spec §11.1, DESIGN §S20).
--
-- **A declaration carries its own payload.** A stage has a declared type, a value has an
-- initializer, a word has a template and a terminal, and nothing else does; three optional fields
-- on `Definition` would be a product with variant-specific axes, which is the smell this design
-- removes. So the alternative carries the field, and `Definition` stays flat.
--
-- `Initializer` is why a resolution is not a side table: a name use is re-shaped into
-- `Reference(id)`, so no phase re-runs lexical scoping or keys a fact by node identity. And
-- `Terminal`/`Stmt` are the *closed* set of what a word's body can be -- which is what makes them a
-- vocabulary rather than a clone of the syntax tree.
--
-- NOTE: `asdl.lua` has no comment syntax inside a `Define`, so nothing here may contain `--`.
return function(context)
    local J
    context:Define [[
module Judge {
    Binder      = Lexical(number id) | Entry(Chain.Template template)
    Declaration = Value(Initializer value, boolean mutable, Semantic.Type? declared)
                | Word(Chain.Template word, Terminal? terminal)
                | Type(Semantic.Type denotes)
                | Host(string? destroys, number? borrows)
                | Namespace
                | Bound(Semantic.Type declared)
    Definition  = (number id, string name, Declaration declaration, Binder? scope,
                   Source.Span span, Source.Range name_range)
    Resolved    = (Definition* definitions, Initializer? namespace, Chain.Capture* captures)

    Initializer = Literal(Syntax.Expr value)
                | Reference(number definition, Source.Span span)
                | Apply(Initializer callee, Initializer argument, Source.Span span)
                | Invoke(Initializer callee, Initializer* arguments, Source.Span span)
                | Unary(Semantic.UnaryOp operator, Initializer operand, Source.Span span)
                | Binary(Semantic.BinaryOp operator, Initializer left, Initializer right,
                         Source.Span span)
                | Aggregate(Member* members, Source.Span span)
                | Move(Initializer place, Source.Span span)
                | Project(Initializer base, string name, Source.Span span)
                | Index(Initializer base, number offset, Source.Span span)
                   | Element(Initializer base, Initializer index, Source.Span span)
    Member      = (string? name, Initializer value, boolean mutable)

    Terminal    = Data(Initializer value) | Body(Stmt* statements)
    Stmt        = Local(number definition)
                | Return(Initializer? value, Source.Span span)
                | Discard(Initializer value, Source.Span span)
                | If(Initializer condition, Stmt* yes, Stmt* no, Source.Span span)
                | While(Initializer condition, Stmt* body, Source.Span span)
                | Break(Source.Span span) | Continue(Source.Span span)
                | Assign(Initializer place, Initializer value, Source.Span span)
                | Switch(Initializer subject, Case* cases, Stmt* otherwise, Source.Span span)
    Label       = Shape(Semantic.Type denotes, number? alternative) | Constant(Initializer value)
    Case        = (Label* labels, number? binds, Stmt* body, Source.Span span)

    Parameter   = (string name, Semantic.Capability capability, Semantic.Type type)
    Interface   = (Parameter* stages, Semantic.Type result,
                   Chain.Terminal terminal, boolean borrowed)
    Typed       = (number definition, Interface interface)
    Program     = (Definition* definitions, Initializer? namespace,
                   Semantic.Type? namespace_type, Typed* typed)

    State       = Initialized | Moved

    Answer      = Known(Atom atom) | Runtime(Belt.Type type)
    Atom        = Int(number value) | Bool(boolean value) | Unit | Text(string value)
                | Bundle(Atom* fields)
    Fate        = Immediate | Materialized | Dropped
}
    ]]

    local J = context.Judge
    local J = context.Judge
    -- The walk below is STRUCTURAL, over `Chain.Template`'s items as well as over judge nodes, so it
    -- needs the layer that owns a stage -- and it asks whether a declared type is a WORD, which is a
    -- choice `Semantic` owns.
    local Chain, Semantic = context.Chain, context.Semantic
    -- `Answer` is a LATTICE (DESIGN §5.3), so it has a join method rather than a caller that
    -- switches on it. `Runtime` is the top and absorbs; two constants agree only if they are the
    -- same VALUE, and that is why the comparison is structural rather than by object identity --
    -- two producers that fold to the same constant agree, whichever of them produced it.
    --
    -- The fallback type is passed in rather than carried, because `Known` does not name a belt
    -- type, and a join that could not produce `Runtime` would not be a lattice.
    local function same_atom(a, b)
        if J.Int:isclassof(a) then return J.Int:isclassof(b) and a.value == b.value end
        if J.Bool:isclassof(a) then return J.Bool:isclassof(b) and a.value == b.value end
        if J.Unit:isclassof(a) then return J.Unit:isclassof(b) end
        if J.Text:isclassof(a) then return J.Text:isclassof(b) and a.value == b.value end
        if J.Bundle:isclassof(a) then
            if not J.Bundle:isclassof(b) or #a.fields ~= #b.fields then return false end
            for i = 1, #a.fields do
                if not same_atom(a.fields[i], b.fields[i]) then return false end
            end
            return true
        end
        return false
    end
    J.same_atom = same_atom

    -- §1.1's arrow spine, read off the DECLARATION rather than off a type: which word does this value
    -- denote, and how many stages does it already hold. It lives HERE because TWO layers ask it and
    -- the answer must be one answer -- `Resolve` turns a name in type position into the type of the
    -- value it denotes (§S99), and `Lower` selects the callee of an application (`word_of`, §S92).
    -- Two copies of this walk is exactly the defect this design keeps finding, and it is why
    -- `let f : add2` -- a PARTIAL application's name used as a type -- was `UnknownType` while
    -- `add2 with 3` lowered: the walk knew a word name and a plain alias, and stopped at an `Apply`.
    --
    -- It is STRUCTURAL, so it needs no types and can run before `Contract` does: a word name is at
    -- prefix 0; a value binding is a second name for its value; a capture is a second name for
    -- somebody else's storage (§3.2), which is the same step; a `move` names what it moved; a word
    -- reached through a record is the member the record holds (§2.6); a stage whose declared type is
    -- a WORD names that word (§S99, and the nominal type is what makes the callee knowable without a
    -- vtable); and an application is one prefix further along.
    --
    -- `lookup` maps a definition id to its DECLARATION, because the layers keep that table in
    -- different shapes -- Resolve's `by_id` holds the definition and the others hold the declaration
    -- -- so the question is asked through the one thing both can answer.
    local function stage_count(word)
        local count = 0
        for _, item in ipairs(word.items) do
            if Chain.Stage:isclassof(item) then count = count + 1 end
        end
        return count
    end

    function J.word_of(lookup, initializer)
        local function walk(node, hops)
            if hops > 8 or not node then return nil end
            if J.Reference:isclassof(node) then
                local declaration = lookup(node.definition)
                if J.Word:isclassof(declaration) then return node.definition, 0 end
                -- A value binding, and a capture is one -- its declaration is a `Value` holding a
                -- reference to the storage it captures -- so following it is the difference between
                -- typing the frame and typing its answer.
                if J.Value:isclassof(declaration) then return walk(declaration.value, hops + 1) end
                -- A stage whose declared type is a word: `Contract` reads the callee off the TYPE and
                -- this reads it off the declaration, which is the same answer.
                if J.Bound:isclassof(declaration) and declaration.declared
                        and Semantic.Word:isclassof(declaration.declared) then
                    return declaration.declared.template, declaration.declared.prefix
                end
                return nil
            end
            if J.Move:isclassof(node) then return walk(node.place, hops + 1) end
            if J.Project:isclassof(node) then
                -- A word reached THROUGH a record: an imported file's namespace IS one, and §2.6 makes
                -- the projection the only way to reach a word inside it (`other.twice`).
                if not J.Reference:isclassof(node.base) then return nil end
                local declaration = lookup(node.base.definition)
                while declaration and J.Value:isclassof(declaration)
                        and J.Reference:isclassof(declaration.value) and hops < 8 do
                    declaration = lookup(declaration.value.definition)
                    hops = hops + 1
                end
                if declaration and J.Value:isclassof(declaration)
                        and J.Aggregate:isclassof(declaration.value) then
                    for _, member in ipairs(declaration.value.members) do
                        if member.name == node.name and J.Reference:isclassof(member.value) then
                            return walk(member.value, hops + 1)
                        end
                    end
                end
                return nil
            end
            if not J.Apply:isclassof(node) then return nil end
            local template, prefix = walk(node.callee, hops + 1)
            if not template then return nil end
            local declaration = lookup(template)
            local word = declaration and declaration.word
            if not word then return nil end
            if prefix + 1 < stage_count(word) then return template, prefix + 1 end
            -- The application SATURATES the word, so what it denotes is the word's own RESULT -- and
            -- that is a word exactly when the terminal yields one (§S3): a data terminal's result is
            -- the type of its value, and a `do` or host terminal DECLARES it, so the declaration
            -- already says. `Pair with 5` above is the first case and `do : square` is the second.
            if prefix + 1 > stage_count(word) then return nil end
            local result
            local terminal = declaration.terminal
            if terminal and J.Data:isclassof(terminal) then
                local inner, at = walk(terminal.value, hops + 1)
                if inner then result = Semantic.Word(inner, at) end
            else
                result = word.result
            end
            if result and Semantic.Word:isclassof(result) then
                return result.template, result.prefix
            end
            return nil
        end
        return walk(initializer, 0)
    end

    function J.Answer:join(other, type) return J.Runtime(type) end
    function J.Runtime:join(other, type) return self end
    function J.Known:join(other, type)
        if J.Known:isclassof(other) and same_atom(self.atom, other.atom) then return self end
        return J.Runtime(type)
    end
end

end)

-- let/report.lua
module('let.report', function(require, ...)
-- The diagnostic vocabulary: one sum, three constructors.
--
-- `Reject` is the program's fault, `Missing` is a mechanism the compiler lacks, `Bug` is a broken
-- invariant. They are never conflated in a message string, because they are never a string: a
-- node returns one of these and *its parent* decides the policy (DESIGN §7, §13).
--
-- `MissingWhy` is the gap inventory. The count is the number of alternatives, every gap site
-- names its constructor, and a new gap cannot be added silently -- it is a visible alternative
-- that every dispatcher must handle. That is what replaces a hand-maintained GAPS.md.
return function(context)
    context:Define [[
module Report {
    RejectWhy  = UninitializedPlace | PartiallyInitialized | OwnershipDiverges | NeedsMove
               | IndexOutOfRange | UnstatedResult
               | ConflictingBorrow | BorrowedEscapes | BorrowOfTemporary
               | Oversaturated | Undersaturated | NotExecutable
               | DuplicateBinding | UnknownName | UseBeforeInitializer
               | ReadOnlyDestination | UnknownType | MismatchedType
               | MissingModule | ImportPath | ImportCycle
               | InvalidConversion | InvalidCaseLabel
               | Syntax(string detail)
    MissingWhy = ModuleState
    BugWhy     = UnresolvedWordValue | MissingProgramBuilder | NoLowering(string form)
               | UncarriedProducer | AnalysisExhausted | UnaddressableDestination

    Diagnostic = Reject(RejectWhy why, Source.Span span)
               | Missing(MissingWhy why, Source.Span span)
               | Bug(BugWhy why, Source.Span span)
}
    ]]

    -- The builders and predicates a machine uses. They live here so that no site spells a
    -- diagnostic itself, and so that "is this a Reject?" is asked in one place.
    local R = context.Report
    function R.reject(why, span) return R.Reject(why, span) end
    function R.missing(why, span) return R.Missing(why, span) end
    function R.bug(why, span) return R.Bug(why, span) end
    function R.Diagnostic:is_reject() return R.Reject:isclassof(self) end
    function R.Diagnostic:is_missing() return R.Missing:isclassof(self) end
    function R.Diagnostic:is_bug() return R.Bug:isclassof(self) end
    -- The gap inventory, as a value rather than a document: one entry per Missing reason.
    R.missing_reasons = { 'ModuleState' }
end


end)

-- let/c.lua
module('let.c', function(require, ...)
-- The C output vocabulary. Output only: no Let ownership, specialization, or binding-time domain.
--
-- `C.Expr.Comma` exists for exactly one reason: §3.6's trapping division has to be written
-- INLINE. There is no helper function, because a helper would be a second implementation of a
-- Let operator in C, and a trap is a property of the operation rather than of a runtime the
-- program links. `(abort(), 0)` is what lets a void expression stand where a value is wanted.
return function(context)
    context:Define [[
module C {
    Type = Void | Bool | I64 | F64 | F32 | U64 | U8 | U32 | Size | CString
         | Pointer(Type pointee) | Named(string name)
    Expr = Integer(number hi, number lo) | Float(number value) | Boolean(boolean value) | String(string value)
         | Name(string name) | Unary(string operator, Expr operand)
         | Binary(string operator, Expr left, Expr right)
         | Cast(Type type, Expr value) | Call(Expr callee, Expr* arguments)
         | Field(Expr base, string name) | Index(Expr base, Expr index)
         | Compound(Type type, Expr* fields)
         | Conditional(Expr condition, Expr yes, Expr no)
         | Comma(Expr* values)
         | Init(Type type, Designator* fields)
    Parameter = (Type type, string name)
    Designator = (string name, Expr value)
    Case = (Expr? value, Stmt* body)
    Stmt = Declare(Type type, string name, Expr? initial)
         | Assign(Expr place, Expr value) | Evaluate(Expr value)
         | Block(Stmt* statements) | If(Expr condition, Stmt yes, Stmt? no)
         | While(Expr condition, Stmt body)
         | Label(string name) | Goto(string name) | Return(Expr? value)
         | Switch(Expr value, Case* cases) | Break
    Declaration = Function(string name, boolean external, boolean exported, Type result, Parameter* parameters, Stmt? body)
                | Struct(string name, Parameter* fields)
                | Union(string name, Parameter* fields)
                | Raw(string code)
                | Global(Type type, string name)
    Unit = (string* includes, Declaration* declarations)
}
    ]]
end

end)

-- let/context.lua
module('let.context', function(require, ...)
-- The context record: the only mutable state of a transition (DESIGN §8).
--
-- A **node** is a containment level. It owns `out` -- the draft IR it is building -- and reaches
-- its ambient tables *through* `parent`. A **region** is a control position inside one transition:
-- it shares the node's `out`, and it creates its own `state` on entry (DESIGN §7.3).
--
-- Contexts are constructed, never cloned. There is no `clone` and no allowlist of shared fields,
-- because the split is structural: `parent` and `out` are the two things a child may share, and
-- everything else is a fresh `state` table it made itself. A forgotten field is therefore a nil
-- error rather than a fact silently shared by every region.
--
-- The exit vocabulary is a convention, not a method: every machine method has the shape
--
--     machine:run(in, k_ok, k_diag)
--
-- and calls `k_ok(C, value)` or `k_diag(C, diagnostic)` by tail call. A node never decides whether
-- its own diagnostic is fatal -- that is the parent's wiring, so the policy is decided once per
-- parent instead of at every site.
local Context = {}
Context.__index = Context

local function make(parent, ambient)
    return setmetatable({ parent = parent, ambient = ambient or {}, out = {}, state = {} }, Context)
end

-- The root: it holds the ambient every transition below it can reach.
-- The root: it holds the ambient every transition below it can reach.
--
-- `modules` is §6's "loaded units by name": a unit is loaded ONCE, so two `import`s of one file share
-- one `Syntax.Program` -- which matters because that file's resolution must be one resolution, and
-- two of them could disagree. It is compiler-scoped rather than unit-scoped for exactly that reason.
function Context.compiler(vocabulary, options)
    return make(nil, { vocabulary = vocabulary, options = options or {}, reports = {}, modules = {} })
end

-- A nested node. It gets its own `out`, because containment is lifetime: this is the draft *this*
-- transition owns, and a child must not write into its parent's.
function Context:child(ambient)
    return make(self, ambient)
end

-- A region. Same `out`, own `state`, and `parent` is the node it belongs to, so ambient reads walk
-- the containment chain exactly as they do for a node.
function Context:region(state)
    return setmetatable({ parent = self, ambient = {}, out = self.out, state = state or {} }, Context)
end

-- Ambient is read in one direction: up. This is the whole of "reached through the parent".
function Context:find(name)
    local at = self
    while at do
        local value = at.ambient[name]
        if value ~= nil then return value end
        at = at.parent
    end
end

function Context:get(name)
    local value = self:find(name)
    if value == nil then error('no ambient ' .. name, 2) end
    return value
end

return Context

end)

-- let/lex.lua
module('let.lex', function(require, ...)
-- Text -> Source.Token list (spec §2.1, §2.2).
--
-- Whitespace is insignificant, so the lexer emits no separator token: a top-level binding ends
-- where the next `let` begins, which the parser decides. `#` starts a comment to end of line.
--
-- Spans carry file, line and column, because a diagnostic is a value with a position (DESIGN §13)
-- and the position must be the one the reader sees.
return function(V)
    local Source, L = V.Source, V.List

    -- `do` and `end` are Lua keywords, so the table keys are bracketed.
    local KEYWORDS = { ['let'] = 'let', ['mut'] = 'mut', ['own'] = 'own', ['move'] = 'move',
                      ['return'] = 'return', ['if'] = 'if', ['else'] = 'else', ['while'] = 'while',
                      ['break'] = 'break', ['continue'] = 'continue',
                      ['do'] = 'do', ['end'] = 'end',
                      -- §3.4's word operators, and `switch`/`case`, which are forms rather than
                      -- expressions but are still reserved.
                      ['and'] = 'and', ['or'] = 'or', ['not'] = 'not',
                      ['switch'] = 'switch', ['case'] = 'case', ['as'] = 'as',
                      -- A foreign word is declared, not registered (§3.6): `extern` introduces it.
                      ['extern'] = 'extern', ['pure'] = 'pure', ['host'] = 'host',
                      ['borrows'] = 'borrows', ['with'] = 'with' }

    -- §3.4's operator tokens. The two-character forms are tried FIRST, and that is not an
    -- optimisation: `<` and `<=` differ only by the next character, so a lexer that preferred the
    -- shorter match would never produce `<=` at all.
    local OPERATORS = {
        ['=='] = '==', ['!='] = '!=', ['<='] = '<=', ['>='] = '>=',
        ['<<'] = '<<', ['>>'] = '>>', ['->'] = '->',
        ['+'] = '+', ['-'] = '-', ['*'] = '*', ['/'] = '/', ['%'] = '%',
        ['<'] = '<', ['>'] = '>', ['&'] = '&', ['|'] = '|', ['^'] = '^', ['~'] = '~',
    }
    local PUNCT = {
        ['='] = '=', [';'] = ';', [':'] = ':', [','] = ',',
        ['('] = '(', [')'] = ')', ['{'] = '{', ['}'] = '}',
        ['.'] = '.', ['['] = '[', [']'] = ']',
    }

    return function(text, file)
        local tokens = L()
        local i, line, col, n = 1, 1, 1, #text

        local function push(kind, spelling, value, span)
            tokens:insert(Source.Token(kind, spelling, value, span))
        end

        while i <= n do
            local c = text:sub(i, i)
            if c == '\n' then
                i, line, col = i + 1, line + 1, 1
            elseif c:match('%s') then
                i, col = i + 1, col + 1
            elseif c == '#' then
                while i <= n and text:sub(i, i) ~= '\n' do i = i + 1 end
            else
                local span = Source.Span(file, line, col)
                local two, one = text:sub(i, i + 1), text:sub(i, i)
                if OPERATORS[two] then
                    push(OPERATORS[two], two, nil, span)
                    i, col = i + 2, col + 2
                elseif OPERATORS[one] then
                    push(OPERATORS[one], one, nil, span)
                    i, col = i + 1, col + 1
                elseif c == '"' then
                    -- §11.3: Text is an immutable MODULE-LIFETIME literal, so a string literal is
                    -- a value with static storage and not a view. The escapes are the ones that
                    -- change the meaning of the bytes; the token's `value` slot carries the
                    -- unescaped text, which is what makes the spelling and the value separable --
                    -- and that separation is what makes two labels collide by VALUE rather than by
                    local scan, value = i + 1, {}
                    while true do
                        local ch = text:sub(scan, scan)
                        if ch == '' then
                            error(('%s:%d:%d: unterminated text'):format(file, line, col), 0)
                        end
                        if ch == '"' then break end
                        if ch == '\\' then
                            local escape = text:sub(scan + 1, scan + 1)
                            local unescaped = ({ n = '\n', t = '\t', r = '\r', ['0'] = '\0' })[escape]
                            if not unescaped and escape ~= '\\' and escape ~= '"' then
                                error(('%s:%d:%d: unknown escape \\%s'):format(file, line, col, escape), 0)
                            end
                            value[#value + 1] = unescaped or escape
                            scan = scan + 2
                        else
                            value[#value + 1] = ch
                            scan = scan + 1
                        end
                    end
                    local spelling = text:sub(i, scan)
                    push('text', spelling, table.concat(value), span)
                    i, col = scan + 1, col + #spelling
                else
                    local name = text:match('^[A-Za-z_][A-Za-z0-9_]*', i)
                    -- §2.2's integer literals. Hex and binary are matched before decimal, because
                    -- `0x10` begins with a digit and a decimal-first match would take the zero.
                    -- §11.3's `Float`. A float is matched BEFORE the decimal integer, or `1.5` would be
                    -- the integer `1` and then a projection. A leading digit is required: `.` is the
                    -- postfix projection, so `.5` is not a literal in this language -- which is a
                    -- choice, and the one that keeps `a.b` unambiguous.
                    local float = text:match('^%d[%d_]*%.[%d_]*[eE][+-]?%d+', i)
                        or text:match('^%d[%d_]*%.[%d_]*', i)
                        or text:match('^%d[%d_]*[eE][+-]?%d+', i)
                    local int = text:match('^0[xX][%x_]+', i) or text:match('^0[bB][01_]+', i)
                        or text:match('^%d[%d_]*', i)
                    if name then
                        push(KEYWORDS[name] or 'name', name, name, span)
                        i, col = i + #name, col + #name
                    elseif float then
                        push('float', float, float:gsub('_', ''), span)
                        i, col = i + #float, col + #float
                    elseif int then
                        push('int', int, int:gsub('_', ''), span)
                        i, col = i + #int, col + #int
                    elseif PUNCT[c] then
                        push(PUNCT[c], c, nil, span)
                        i, col = i + 1, col + 1
                    else
                        error(('%s:%d:%d: unexpected character %q'):format(file, line, col, c), 0)
                    end
                end
            end
        end
        push('eof', '', nil, Source.Span(file, line, col))
        return tokens
    end
end

end)

-- let/parse.lua
module('let.parse', function(require, ...)
-- Tokens -> Syntax.Program (spec §3.1).
--
-- A program **is** a binding chain (spec §2.6): its items are the top-level bindings and its
-- terminal, if written, replaces the namespace. So the program and a binding value are parsed by
-- the same rule, and a chain item is the same in both positions:
--
--     let NAME [own] [mut] [: type]        a stage -- an unsatisfied input
--     let NAME [mut] [: type] = <chain>    a prelude -- a completed binding
--
-- The split is decided by the `=` alone, and that is not a convenience: spec §3.1 gives a stage no
-- terminal to read a type from, so a stage **must** declare its type word, and its absence is an
-- error rather than an inference.
--
-- **Items are greedy; expressions are not.** Items are consumed while the next token can begin one
-- (`let`, `extern`, `host`), and the first token that cannot begins the terminal -- so the boundary
-- between two ITEMS needs no separator, because the keywords delimit themselves.
--
-- An APPLICATION, by contrast, is the keyword `with` and never adjacency (§S88). Two expressions in a
-- row are a mistake the parser reports, which is what lets a parenthesized expression AFTER `with` be
-- a group (`sum with (square with 3)`) -- unreachable while a word followed by `(` was an invocation.
-- And `;` means exactly one thing now: an item's value is an expression and so is a written terminal,
-- so THAT boundary needs a separator. `f(x); g(y)` is not why it exists.
return function(V)
    local Syntax, Source, Semantic, L = V.Syntax, V.Source, V.Semantic, V.List

    return function(tokens, file, text)
        local at = 1
        local function peek() return tokens[at] end
        local function kind() local t = tokens[at]; return t and t.kind end
        local function what()
            local t = tokens[at]
            return t and (t.spelling ~= '' and t.spelling or t.kind) or 'EOF'
        end
        local function locate(t) return t and ('%s:%d:%d'):format(file, t.span.line, t.span.column) or file end
        local function take(want)
            local t = tokens[at]
            if not t or t.kind ~= want then
                error(('%s: expected %s, found %s'):format(locate(t), want, what()), 0)
            end
            at = at + 1
            return t
        end
        local function accept(want)
            if kind() == want then local t = tokens[at]; at = at + 1; return t end
        end
        -- §12.0 makes `true` and `false` lexical NAMES rather than keywords, so every place that
        -- needs to know whether a name IS a Bool literal asks here. One owner, because a place that
        -- forgets is a place that reads `true` as a type name or as a dictionary word.
        local function is_boolean(spelling)
            return spelling == 'true' or spelling == 'false'
        end
        -- §3.4's assignment needs a lookahead, and this is why: a name can begin an expression, so
        -- `let n = 0` followed by `n = 1` would read that `n` as the start of a second expression and
        -- then choke on the `=`. A name followed by `=` therefore begins a STATEMENT.
        --
        -- `let y = x` followed by `y` is the other side of the same coin: two expressions in a row,
        -- which is a mistake (§S88) rather than an application -- so `let y = x; y` still needs its
        -- `;`, and the reason is that an item's value and a written TERMINAL are both expressions.
        -- None of this is about how application is spelled.
        -- Whether an expression could begin here -- which is what the parser has to know in two
        -- places: to report two expressions in a row (§S88), and to see an assignment's `=`.
        --
        -- A name normally continues one -- `f x` is a single application -- except when it is the
        -- destination of §3.4's assignment, and that is not a one-token question: `n = 1` is easy,
        -- but `r.x = 1` has its `=` past the suffixes. So the lookahead IS the postfix grammar, run
        -- forward without consuming: a name, then any sequence of `.name` and `[...]`, then `=`.
        -- Anything else means the name is an argument, as before.
        local function assignment_ahead()
            if kind() ~= 'name' then return false end
            local ahead = at + 1
            while true do
                local token = tokens[ahead]
                if not token then return false end
                if token.kind == '.' then
                    if not (tokens[ahead + 1] and tokens[ahead + 1].kind == 'name') then return false end
                    ahead = ahead + 2
                elseif token.kind == '[' then
                    local depth, scan = 1, ahead + 1
                    while depth > 0 do
                        local inner = tokens[scan]
                        if not inner then return false end
                        if inner.kind == '[' then depth = depth + 1
                        elseif inner.kind == ']' then depth = depth - 1 end
                        scan = scan + 1
                    end
                    ahead = scan
                else
                    return token.kind == '='
                end
            end
        end

        -- §3.4's `specialization_atom`: "literal | NAME { postfix_suffix } | aggregate_literal".
        -- So the tokens that continue an expression are exactly the ones that can BEGIN one as an
        -- argument -- and leaving one out inverts the grammar silently: `f "x"` stopped being an
        -- application the moment Text literals existed, and the file parser then read the `"x"` as
        -- its own terminal and failed on the next `let`.
        -- §11.2's `TypeExpr`, all six alternatives. `->` is the loosest and right-nested -- §11.1
        -- reads a word's type as "unary right-nested arrows" -- and `|` sits inside it, so
        -- `A -> B | C` is `A -> (B | C)`. A record's fields are `name : T` with an optional `mut`,
        -- which is §3.7's interior mutability in a TYPE; a tuple's members have no names at all,
        -- because §3.3 gives a positional element no declaration to be named by.
        -- The three levels are mutually recursive -- a record's field is a type and a record IS a
        -- type -- so they are declared together and assigned in order.
        local parse_type, parse_type_sum, parse_type_atom

        parse_type = function()
            local from = parse_type_sum()
            if accept('->') then return Syntax.Arrow(from, parse_type(), from.span) end
            return from
        end

        parse_type_sum = function()
            local left = parse_type_atom()
            while accept('|') do left = Syntax.Sum(left, parse_type_atom(), left.span) end
            return left
        end

        parse_type_atom = function()
            local t = peek()
            if t.kind == 'name' then
                at = at + 1
                return Syntax.Ref(t.spelling, t.span)
            end
            if t.kind == '{' then
                at = at + 1
                local fields = L()
                if not accept('}') then
                    repeat
                        -- `name mut : T`, the same order a STAGE uses (`x own : Int`), because
                        -- §3.7's mutability is a qualifier on the declaration and not on the type.
                        local name = take('name')
                        local mutable = accept('mut') ~= nil
                        take(':')
                        fields:insert(Syntax.TypeField(name.spelling, mutable, parse_type(),
                            name.span))
                    until not accept(',')
                    take('}')
                end
                return Syntax.Record(fields, t.span)
            end
            -- §11.2's `Do(TypeExpr result)`: the type of a chain whose terminal is a body. In TYPE
            -- position `do` cannot begin anything else, so it needs no lookahead.
            if t.kind == 'do' then
                at = at + 1
                return Syntax.Do(parse_type(), t.span)
            end
            if t.kind == '(' then
                at = at + 1
                local elements = L{parse_type()}
                while accept(',') do elements:insert(parse_type()) end
                take(')')
                return Syntax.Tuple(elements, t.span)
            end
            error(('%s: expected a type, found %s'):format(locate(t), what()), 0)
        end

        local function parse_annotation()
            if accept(':') then return parse_type() end
            return nil
        end

        -- A primary is a literal or a name. `true` and `false` are lexical names, not keywords.
        -- Forward declaration: an aggregate's members are chain items, which are parsed below.
        -- Forward declarations, because the grammar is a cycle: an aggregate's members are chain
        -- items, an index is an expression and an expression may be an index, and `(` groups an
        -- expression inside a primary. Every one of them is declared before the first use rather
        -- than being left to resolve as a global -- which is a silent nil call, not an error.
        local parse_aggregate, parse_postfix, separate, parse_if, parse_while, parse_switch, parse_expr

        local function parse_primary()
            local t = peek()
            if t.kind == 'int' then
                at = at + 1
                return Syntax.Integer(t.spelling, t.span)
            end
            if t.kind == 'float' then
                at = at + 1
                return Syntax.Float(t.spelling, t.span)
            end
            -- §11.3's Text literal. The token's VALUE is the unescaped text, so the spelling of an
            -- escape never reaches the judgment -- which is why `Syntax.Text` carries the value and
            -- not the source text.
            if t.kind == 'text' then
                at = at + 1
                return Syntax.Text(t.value, t.span)
            end
            if t.kind == 'name' and is_boolean(t.spelling) then
                at = at + 1
                return Syntax.Boolean(t.spelling == 'true', t.span)
            end
            if t.kind == 'name' then
                at = at + 1
                return Syntax.Name(t.spelling, t.span)
            end
            -- §1.4's call-site form: `move place` transfers ownership. It is a prefix on a place,
            -- so it sits with the primaries rather than with the application.
            if t.kind == 'move' then
                at = at + 1
                return Syntax.Move(parse_postfix(), t.span)
            end
            -- §3.4's `primary` includes prefix parentheses. `(` is ALSO the invocation suffix, and
            -- the two never collide: an invocation is parsed by `parse_postfix` on a value it
            -- already has, while grouping is reached only where a primary can begin.
            if t.kind == '(' then
                at = at + 1
                local inner = parse_expr()
                take(')')
                return inner
            end
            if t.kind == '{' then
                at = at + 1
                return parse_aggregate(t)
            end
            error(('%s: expected an expression, found %s'):format(locate(t), what()), 0)
        end

        -- `with` is application, ONE argument at a time and left-associated, so `f with a with b` is
        -- the chain adjacency used to mean. A prefix operator binds tighter than `with` -- `f with -x`
        -- is one argument and not a negative application -- which is why the argument is parsed by
        -- `parse_operator` and not by `parse_postfix`: the latter would refuse the `-`.
        -- Forward declaration: an item's value is a chain, and a chain's item is an item.
        local parse_chain

        -- §3.4's tightest level: `.` and `[]` are postfix, so a place is one expression and binds
        -- tighter than the `with` that supplies stages.
        -- §3.4's postfix suffix: `.`, `[]` and invocation. They bind tighter than everything, so
        -- a place is one expression and `f(x).y[0]` is a place too.
        parse_postfix = function()
            local value = parse_primary()
            while true do
                if accept('.') then
                    local name = take('name')
                    value = Syntax.Project(value, name.spelling,
                        Source.Range(name.span, name.span), value.span)
                elseif accept('[') then
                    local index = parse_expr()
                    take(']')
                    value = Syntax.Index(value, index, value.span)
                elseif accept('(') then
                    -- §1.2's invocation. It saturates transiently, and `f()` -- no arguments at
                    -- all -- is the one thing `with` cannot write: it runs the word's
                    -- terminal without supplying a stage.
                    local arguments = L()
                    if not accept(')') then
                        arguments:insert(parse_expr())
                        while accept(',') do arguments:insert(parse_expr()) end
                        take(')')
                    end
                    value = Syntax.Invoke(value, arguments, value.span)
                else
                    return value
                end
            end
        end

        -- §3.4's precedence, taken from the spec's own table and written as DATA rather than as a
        -- chain of twelve functions. Each level is `{ associativity, { token = operator } }`, the
        -- levels run loosest to tightest, and a non-associative level stops after one operator --
        -- so `a < b < c` is a parse error rather than a silent `(a < b) < c`.
        local LEVELS = {
            { 'left', { ['or'] = Syntax.Or } },
            { 'left', { ['and'] = Syntax.And } },
            { 'none', { ['=='] = Syntax.Equal, ['!='] = Syntax.NotEqual } },
            { 'none', { ['<'] = Syntax.Less, ['<='] = Syntax.LessEqual,
                        ['>'] = Syntax.Greater, ['>='] = Syntax.GreaterEqual } },
            { 'left', { ['|'] = Syntax.BitOr } },
            { 'left', { ['^'] = Syntax.BitXor } },
            { 'left', { ['&'] = Syntax.BitAnd } },
            { 'left', { ['<<'] = Syntax.ShiftLeft, ['>>'] = Syntax.ShiftRight } },
            { 'left', { ['+'] = Syntax.Add, ['-'] = Syntax.Subtract } },
            { 'left', { ['*'] = Syntax.Multiply, ['/'] = Syntax.Divide, ['%'] = Syntax.Remainder } },
        }
        local PREFIX = { ['not'] = Syntax.Not, ['-'] = Syntax.Negate, ['~'] = Syntax.BitNot }

        local parse_prefix, parse_specialization

        local function parse_level(level)
            if level > #LEVELS then return parse_prefix() end
            local associativity, operators = LEVELS[level][1], LEVELS[level][2]
            local value = parse_level(level + 1)
            while true do
                local operator = operators[kind()]
                if not operator then return value end
                at = at + 1
                local right = parse_level(level + 1)
                value = Syntax.Binary(operator, value, right, value.span)
                if associativity == 'none' then return value end
            end
        end

        -- Level 3 is PREFIX, and it binds tighter than every operator but looser than `with` -- so
        -- `f with x + 1` is `(f with x) + 1`, and a prefix operator is an ARGUMENT rather than part
        -- of the application: `f with -1` applies `f` to a negative literal. Adjacency could not
        -- write that -- `f -1` had to be the subtraction -- which is another way of saying that an
        -- application with no spelling makes the grammar guess.
        parse_prefix = function()
            local operator = PREFIX[kind()]
            if not operator then return parse_specialization() end
            local t = peek()
            at = at + 1
            return Syntax.Unary(operator, parse_prefix(), t.span)
        end

        -- Prefix operators and postfix suffixes, with NO application: the thing `with` takes.
        parse_operator = function()
            local operator = PREFIX[kind()]
            if not operator then return parse_postfix() end
            local t = peek()
            at = at + 1
            return Syntax.Unary(operator, parse_operator(), t.span)
        end

        -- Two adjacent expressions WERE an application and are now a mistake, so this is where the
        -- parser says so. It is the predicate the old greediness used -- §S40's `starts_expression`,
        -- which had to be taught `{` and `text` -- kept for the one job it can still do: telling a
        -- writer what they meant. A name that is an assignment TARGET is not one of these (`x = 1` is
        -- a statement), which is why the lookahead matters.
        local function continues_an_expression()
            if kind() == 'int' or kind() == 'text' or kind() == '{' then return true end
            if kind() ~= 'name' then return false end
            return not assignment_ahead()
        end

        parse_specialization = function()
            local value = parse_operator()
            while accept('with') do
                value = Syntax.Specialize(value, parse_operator(), value.span)
            end
            if continues_an_expression() then
                error(('%s: two adjacent expressions. An application is `with` (`f with a`), and a '
                    .. 'chain\'s TERMINAL is separated from the items before it by `;`')
                    :format(locate(peek())), 0)
            end
            return value
        end

        parse_expr = function() return parse_level(1) end

        -- §11.2's `Item.Extern`, and §3.6's reason for it: the host's vocabulary is DECLARED in
        -- source rather than registered by an embedding. The declaration is the whole contract --
        -- stages, their capabilities and types, the result, and purity -- because that is what the
        -- compiler holds a host to. The optional quoted symbol is the C name when it differs from
        -- the Let name, which is `Extern.symbol` and not a second name.
        local function parse_extern()
            local kw = take('extern')
            local pure = accept('pure') ~= nil
            local name = take('name')
            local name_range = Source.Range(name.span, name.span)
            local symbol
            if kind() == 'text' then symbol = take('text').value end
            take('(')
            local parameters = L()
            if not accept(')') then
                repeat
                    local spec = take('name')
                    local own = accept('own') ~= nil
                    local mutable = accept('mut') ~= nil
                    local constraint = parse_annotation()
                    if not constraint then
                        error(("%s: a host stage must declare its type: %s")
                            :format(locate(kw), spec.spelling), 0)
                    end
                    local capability = own and (mutable and Semantic.OwnMut or Semantic.Own)
                                               or (mutable and Semantic.Mut or Semantic.Read)
                    parameters:insert(Syntax.StageSpec(spec.spelling, capability, constraint,
                        spec.span, Source.Range(spec.span, spec.span)))
                until not accept(',')
                take(')')
            end
            local result
            if accept(':') then result = parse_type() end
            return Syntax.Extern(name.spelling, pure, symbol, parameters, result, kw.span, name_range)
        end

        -- §3.6: "a view is a SEPARATELY DECLARED HOST TYPE", and §3.6 makes the declaration the
        -- whole contract. So `host Handle close` declares a type whose values the host owns and
        -- which `close` destroys. The destructor is optional: a host type with none is one whose
        -- values Let holds and never releases, which is exactly §3.6's "foreign" row.
        local function parse_host()
            local kw = take('host')
            local name = take('name')
            local name_range = Source.Range(name.span, name.span)
            -- §3.6: "a host type may declare that it borrows argument i", which is what makes a value
            -- of it a BORROWED type -- and §3.1 rule 4 propagates that structurally. The index is a
            -- declared fact and never inferred, and it is carried as a SPELLING because §S38 makes
            -- `Semantic.integer_value` the one owner of an integer's value.
            local borrows
            if accept('borrows') then
                local index = take('int')
                borrows = index.spelling
            end
            local destroys
            if kind() == 'name' then destroys = take('name').spelling end
            return Syntax.Host(name.spelling, destroys, borrows, kw.span, name_range)
        end

        local function parse_item()
            local kw = take('let')
            local name = take('name')
            local own = accept('own') ~= nil
            local mutable = accept('mut') ~= nil
            local constraint = parse_annotation()
            local name_range = Source.Range(name.span, name.span)

            if kind() == '=' then
                if own then
                    error(("%s: an initialized binding cannot carry `own`"):format(locate(kw)), 0)
                end
                at = at + 1
                return Syntax.Prelude(Syntax.Binding(name.spelling, mutable, constraint,
                    parse_chain(), kw.span, name_range))
            end

            if not constraint then
                error(("%s: a stage must declare its type: %s"):format(locate(kw), name.spelling), 0)
            end
            local capability = own and (mutable and Semantic.OwnMut or Semantic.Own)
                                       or (mutable and Semantic.Mut or Semantic.Read)
            return Syntax.Stage(Syntax.StageSpec(name.spelling, capability, constraint,
                kw.span, name_range))
        end

        -- A statement list. It ends where the enclosing form resumes, so the terminators are the
        -- keywords that continue one: `end` closes it, `else` is the next arm of an `if`, and
        -- `case` is the next arm of a `switch`. A form that is not here is not silently skipped --
        -- it is a parse error, and the forms the compiler cannot lower yet are named by Lower.
        local function parse_statements()
            local statements = L()
            while true do
                separate()
                local t = peek()
                if t.kind == 'end' or t.kind == 'else' or t.kind == 'case' or t.kind == 'eof' then
                    return statements
                end
                if t.kind == 'let' then
                    local kw = take('let')
                    local name = take('name')
                    local mutable = accept('mut') ~= nil
                    local constraint = parse_annotation()
                    take('=')
                    statements:insert(Syntax.Local(Syntax.Binding(name.spelling, mutable,
                        constraint, parse_chain(), kw.span, Source.Range(name.span, name.span)),
                        kw.span))
                elseif t.kind == 'return' then
                    at = at + 1
                    local value
                    if not (kind() == ';' or kind() == 'end' or kind() == 'eof') then
                        value = parse_expr()
                    end
                    statements:insert(Syntax.Return(value, t.span))
                elseif t.kind == 'if' then
                    statements:insert(parse_if())
                elseif t.kind == 'while' then
                    statements:insert(parse_while())
                elseif t.kind == 'switch' then
                    statements:insert(parse_switch())
                elseif t.kind == 'break' or t.kind == 'continue' then
                    at = at + 1
                    statements:insert(t.kind == 'break' and Syntax.Break(t.span)
                        or Syntax.Continue(t.span))
                else
                    -- A bare `=` after an expression is §3.4's assignment, and nothing else in
                    -- the grammar puts one there: `let` consumes its own. So one token of
                    -- lookahead is the whole decision, and no place-vs-value check is needed
                    -- here -- whether the left side IS a place is Resolve's question.
                    local place = parse_expr()
                    if kind() == '=' then
                        at = at + 1
                        statements:insert(Syntax.Assign(place, parse_expr(), t.span))
                    else
                        statements:insert(Syntax.Discard(place, t.span))
                    end
                end
            end
        end

        -- §3.2: `if`/`else if`/`else` is ONE chain closed by one `end`, so the arms are folded into
        -- a single `If` whose else arm holds the next condition. `else if` is therefore a nesting
        -- in the tree and a chain in the source, which is what the grammar says.
        parse_if = function()
            local kw = take('if')
            local arms = {}
            arms[1] = { condition = parse_expr() }
            take('do')
            arms[1].body = parse_statements()
            while kind() == 'else' do
                at = at + 1
                if kind() == 'if' then
                    at = at + 1
                    local arm = { condition = parse_expr() }
                    take('do')
                    arm.body = parse_statements()
                    arms[#arms + 1] = arm
                else
                    arms[#arms + 1] = { body = parse_statements() }
                    break
                end
            end
            take('end')
            -- Folded inward-out, so `else if` becomes the `no` list of the arm before it and the
            -- whole chain is ONE statement. The `no` slot holds a list, so the nested `If` is the
            -- single statement in it -- which is what makes the tree uniform. A bare `else` replaces
            -- the fold's tail with its own body rather than nesting under another condition.
            local otherwise = L{}
            for i = #arms, 1, -1 do
                local arm = arms[i]
                if arm.condition then
                    otherwise = L{Syntax.If(arm.condition, arm.body, otherwise, kw.span)}
                else
                    otherwise = arm.body
                end
            end
            return otherwise[1]
        end

        -- §12.0: the subject is evaluated EXACTLY ONCE, arms are `case` label lists, and one `end`
        -- closes the whole form. There is no fallthrough, so an arm's body simply ends. A `switch`
        -- is not a loop, which is why `break` inside an arm belongs to the enclosing `while`.
        parse_switch = function()
            local kw = take('switch')
            local subject = parse_expr()
            take('do')
            local cases = L()
            while kind() == 'case' do
                local t = take('case')
                -- §S60: a label names what the arm matches, and the label SAYS which kind it is:
                -- a SHAPE (a type, which the arm may then bind) or a CONSTANT (a value compared
                -- against the subject). A type is tried FIRST, because a structural shape has no
                -- expression spelling at all -- `{ x : Int }` is a type and nothing else -- and the
                -- position is restored on failure the way §S27 restores it for an ambiguous `{`.
                --
                --     A Bool literal is a NAME lexically, so the guard below is what keeps
                --     `case true` from being read as a type named `true`.
                local function parse_label()
                    local token = peek()
                    if token.kind == 'name' and is_boolean(token.spelling) then
                        return Syntax.Constant(parse_expr())
                    end
                    local mark = at
                    local parsed, type_ = pcall(parse_type)
                    if parsed then return Syntax.Shape(type_) end
                    at = mark
                    return Syntax.Constant(parse_expr())
                end
                local labels = L{parse_label()}
                while accept(',') do labels:insert(parse_label()) end
                -- §S59: an arm that matches by SHAPE names what it matched. The binder is a
                -- NAME rather than a binding, because a match does not compute anything.
                local binds
                if kind() == 'as' then
                    take('as')
                    binds = take('name').spelling
                end
                cases:insert(Syntax.Case(labels, binds, parse_statements(), t.span))
            end
            local otherwise = L()
            if kind() == 'else' then
                at = at + 1
                otherwise = parse_statements()
            end
            take('end')
            return Syntax.Switch(subject, cases, otherwise, kw.span)
        end

        parse_while = function()
            local kw = take('while')
            local condition = parse_expr()
            take('do')
            local body = parse_statements()
            take('end')
            return Syntax.While(condition, body, kw.span)
        end

        -- §3.1: a terminal is a `do ... end` region or a transfer value. A `do` terminal states its
        -- result, and an unstated one is refused by Resolve rather than defaulted.
        local function parse_terminal()
            local t = peek()
            if t.kind == 'do' then
                at = at + 1
                local result
                if accept(':') then result = parse_type() end
                local statements = parse_statements()
                take('end')
                return Syntax.Body(statements, result, t.span)
            end
            return Syntax.Data(parse_expr(), t.span)
        end

        -- `;` SEPARATES A PRELUDE FROM A WRITTEN TERMINAL, and it stays (§S88's first draft said it
        -- had nothing left to do, and the test suite was the counterexample within one run). Both sides
        -- of that boundary are EXPRESSIONS -- `let secret = 8` and then `{ … }` -- so a separator is
        -- needed however application is spelled; greedy juxtaposition was never the reason. What `;`
        -- was never needed for is between two ITEMS, because `let`, `extern` and `host` delimit
        -- themselves, and that is why eating it here and requiring it there is the whole rule.
        -- `;` separates chain items from each other and from the terminal: the grammar requires it
        -- exactly where adjacent expressions would otherwise run together.
        separate = function() while accept(';') do end end

        local function parse_items(items)
            while true do
                separate()
                if kind() == 'extern' then
                    items:insert(parse_extern())
                elseif kind() == 'host' then
                    items:insert(parse_host())
                elseif kind() ~= 'let' then
                    return
                else
                    items:insert(parse_item())
                end
            end
        end

        -- A chain is zero or more items and then a terminal. This slice's terminal is a data
        -- expression; `do ... end` is the next alternative and needs statements.
        parse_chain = function()
            local first = peek().span
            local items = L()
            parse_items(items)
            separate()
            return Syntax.Chain(items, parse_terminal(), first)
        end

        -- §3.3: `{}` is Unit, `{ let x = v }` is a named aggregate, `{ v, v }` is positional, and
        -- the forms cannot mix. A `let` after `{` is genuinely ambiguous -- it can begin a named
        -- member or a positional element that is itself a chain -- so the named form is tried
        -- first and the position restored on failure. This is the one place the parser backtracks
        -- (§S27); the grammar states the constraint but not a decision procedure.
        --
        -- §3.7 + §S26: inside braces `mut` is *interior mutability of the member*, not a supply
        -- qualifier. A `mut` member is supplied like a read one, and any stage member makes the
        -- whole form a `Word` whose chain carries the stages -- which is exactly "a record type
        -- and a value aggregate are the same form" (§3.1).
        parse_aggregate = function(open)
            if accept('}') then return Syntax.Unit(open.span) end

            local mark = at
            local items = L()
            local named = pcall(function()
                parse_items(items)
                if kind() ~= '}' or #items == 0 then error('not a named aggregate', 0) end
            end)
            if named then
                take('}')
                local members, stages = L(), L()
                local staged = false
                for _, item in ipairs(items) do
                    if Syntax.Stage:isclassof(item) then
                        staged = true
                        local spec = item.stage
                        local mutable = spec.capability == Semantic.Mut
                            or spec.capability == Semantic.OwnMut
                        local supplied = spec.capability
                        if supplied == Semantic.Mut then supplied = Semantic.Read
                        elseif supplied == Semantic.OwnMut then supplied = Semantic.Own end
                        stages:insert(Syntax.Stage(Syntax.StageSpec(spec.name, supplied,
                            spec.constraint, spec.span, spec.name_range)))
                        members:insert(Syntax.Binding(spec.name, mutable, spec.constraint,
                            Syntax.Chain(L{}, Syntax.Data(Syntax.Name(spec.name, spec.span), spec.span), spec.span),
                            spec.span, spec.name_range))
                    else
                        members:insert(item.binding)
                    end
                end
                if staged then
                    return Syntax.Word(Syntax.Chain(stages,
                        Syntax.Data(Syntax.NamedAggregate(members, open.span), open.span), open.span), open.span)
                end
                return Syntax.NamedAggregate(members, open.span)
            end

            at = mark
            local elements = L{parse_chain()}
            while accept(',') do
                if kind() == '}' then break end
                elements:insert(parse_chain())
            end
            take('}')
            return Syntax.PositionalAggregate(elements, open.span)
        end

        -- The program is the same shape with the terminal optional (spec §2.6).
        local items = L()
        parse_items(items)
        separate()
        local terminal
        if kind() ~= 'eof' then terminal = parse_terminal() end
        take('eof')
        return Syntax.Program(Syntax.Chain(items, terminal, Source.Span(file, 1, 1)))
    end
end

end)

-- let/resolve.lua
module('let.resolve', function(require, ...)
-- Syntax -> Judge.Resolved (DESIGN §12.1, §S24).
--
-- Resolve answers one question per name: **which declaration does it denote?** It produces a
-- `Definition` per declaration, and for each a resolved `Initializer` -- so no later phase re-runs
-- lexical scoping or keys a fact by node identity.
--
-- Resolution is **post-order**: a declaration is entered only after its body resolves, because spec
-- §1.4 makes a binding visible after its initializer completes. That single ordering rule is what
-- makes `let a = a` an unknown name rather than a self-reference, and a forward reference unknown
-- rather than deferred.
--
-- The enclosing chain's id is reserved *before* its items resolve, because those items are scoped
-- to it -- even though its own name is not yet visible inside them.
return function(V)
    local Syntax, Chain, Semantic, Judge, Report, Source, L =
        V.Syntax, V.Chain, V.Semantic, V.Judge, V.Report, V.Source, V.List

    local Resolve = {}

    -- The primitive type words, by name. A `let`-bound type word joins them when type resolution
    -- reaches definitions and not just the vocabulary.
    -- §11.3's scalar type words, by name -- owned by `Semantic`, because the names of the type words
    -- are a semantic fact and `Contract` needs the same table (§S54).
    local PRIMITIVE = Semantic.primitive

    function Resolve.run(unit, program, k_ok, k_diag)
        local definitions = L()
        local scopes = {}
        local next_id, diagnostic = 0, nil

        local function push() scopes[#scopes + 1] = {} end
        local function pop() scopes[#scopes] = nil end
        local function bind(name, id) scopes[#scopes][name] = id end
        -- The LEVEL is part of the answer, because it is what makes a reference a capture: §1.4's
        -- table gives a word's capture the enclosing lexical scope as its extent, so a name found
        -- BELOW the current chain's level crosses a chain boundary and one found at or above it is
        -- ordinary -- the current chain's own items, or its body's own bindings.
        local function find(name)
            for i = #scopes, 1, -1 do
                local id = scopes[i][name]
                if id then return id, i end
            end
        end
        local function reserve() next_id = next_id + 1; return next_id end
        -- Every declaration, by id. A CAPTURE has to ask what it captures -- its own declaration's
        -- value is a reference to the outer binding (§3.2) and the mode it carries is that binding's
        -- mutability -- so the resolver needs the id -> definition map its consumers already do.
        local by_id = {}
        local function declare(definition)
            definitions:insert(definition)
            by_id[definition.id] = definition
            return definition
        end
        local function fail(d) diagnostic = d; return nil end
        -- Spec §1.4: defining the same name twice in one scope is an error, and shadowing is not
        -- -- a nested chain has its own scope, so the same name there is a different declaration.
        local function duplicate(name, span)
            if scopes[#scopes][name] then
                fail(Report.reject(Report.DuplicateBinding, span))
                return true     -- truthy on failure: `fail` itself returns nil, which is falsy
            end
        end

        -- The declared host types, by name: what exists, and what destroys one.
        local host_types = {}
        -- A type word, once per name: §2.4 makes a type an expression, so `Int` is a VALUE.
        local type_words = {}
        -- What a NAME denotes as a type: a primitive (§3.4), or a declared host type (§3.6).
        -- ONE owner, because this is asked wherever a name meets a type -- a written `: T`, a type
        -- name used as a value, and a `case` label -- and those must not disagree about `Int`.
        -- The declared type must be the interned instance: a nominal type equals only itself.
        local function type_of_name(name)
            return PRIMITIVE[name] or (host_types[name] and host_types[name].type)
        end
        local function resolve_type(expr)
            -- §11.2's `TypeExpr`, all six alternatives, because a type is a WORD: `Box with Int` is
            -- `with` and a record type is a record. These are structural, so they are built
            -- here rather than looked up -- and a record type's `mut` field lands on the FIELD, since
            -- that is what §3.7's interior mutability is a property of.
            if Syntax.Record:isclassof(expr) then
                local fields = L()
                for _, field in ipairs(expr.fields) do
                    local type_ = resolve_type(field.type)
                    if not type_ then return nil end
                    fields:insert(Semantic.Field(field.name, type_, field.mutable))
                end
                return Semantic.Aggregate(fields, nil)
            end
            -- §3.3: a positional element has no declaration, so a tuple's fields are unnamed and it
            -- is a record like any other -- which is why a tuple and a same-shaped record are one
            -- type rather than two.
            if Syntax.Tuple:isclassof(expr) then
                local fields = L()
                for _, element in ipairs(expr.elements) do
                    local type_ = resolve_type(element)
                    if not type_ then return nil end
                    fields:insert(Semantic.Field(nil, type_, false))
                end
                return Semantic.Aggregate(fields, nil)
            end
            if Syntax.Arrow:isclassof(expr) then
                local from = resolve_type(expr.from)
                if not from then return nil end
                local to = resolve_type(expr.to)
                if not to then return nil end
                return Semantic.Arrow(from, to)
            end
            if Syntax.Sum:isclassof(expr) then
                local left = resolve_type(expr.left)
                if not left then return nil end
                local right = resolve_type(expr.right)
                if not right then return nil end
                -- Two alternatives per node, so `A | B | C` is a nesting rather than a flat list.
                -- That keeps the surface and the type in step, and a sum of sums is still a sum.
                return Semantic.Sum(L{left, right})
            end
            if Syntax.Do:isclassof(expr) then
                local result = resolve_type(expr.result)
                if not result then return nil end
                return Semantic.Do(result)
            end
            if not Syntax.Ref:isclassof(expr) then
                return fail(Report.bug(Report.NoLowering('type form'), program.file.span))
            end
            -- A DECLARED host type (§3.6) is a type word like any other. It is `Named` rather than a
            -- new alternative because that is what it is: a type whose meaning the host owns, which
            -- is also why Copy cannot be derived for it (§2.5) and why it needs a destructor.
            --
            -- The SAME instance every time, and that is not an optimisation. A nominal type is one
            -- thing: two `Named('Handle')` values compare unequal, so building a fresh one per use
            -- makes `touch(h)` a type error against the very declaration that produced `h`. Scalars
            -- are single instances because ASDL makes a unique constructor one class; a declared
            -- type has to be interned to match.
            -- §1.1 read through §S3's nominality: a word's type is `Semantic.Word(template, prefix)`,
            -- so a name that denotes a WORD may be used as a TYPE, and it means the type of that
            -- word's VALUE -- exactly the rule `Int` already follows, where the name denotes a type
            -- word and the annotation means the type it NAMES. `let f : square` was `UnknownType`
            -- because this asked `type_of_name`, which knows only primitives and host types.
            --
            -- It is `Judge.word_of` (§S101), the SAME function `Lower` selects a callee with: `Resolve`
            -- runs before `Contract`, so the type cannot be asked for -- it is derived from the
            -- DECLARATION, which is structural and therefore available now. That is what makes a
            -- PARTIAL application a type too: `let add2 = add with 2` has the nominal type
            -- `Word(add, 1)`, and a stage typed `add2` is invocable exactly as one typed `square` is
            -- (§S99). A hand-rolled walk here stopped at the `Apply`, so `f : add2` was `UnknownType`
            -- while `add2 with 3` lowered -- one question with two answers.
            local word_id = find(expr.name)
            if word_id then
                local template, prefix = Judge.word_of(function(id)
                    local definition = by_id[id]
                    return definition and definition.declaration
                end, Judge.Reference(word_id, expr.span))
                if template then return Semantic.Word(template, prefix) end
            end
            local type_ = type_of_name(expr.name)
            if type_ then return type_ end
            return fail(Report.reject(Report.UnknownType, expr.span))
        end

        local function resolve_host(item)
            if duplicate(item.name, item.name_range.start) then return nil end
            if PRIMITIVE[item.name] or host_types[item.name] then
                return fail(Report.reject(Report.DuplicateBinding, item.name_range.start))
            end
            -- §3.6: the declaration is the whole contract, so the borrow index is read ONCE here --
            -- and §S38 makes `Semantic.integer_value` the one owner of an integer's value.
            local borrows
            if item.borrows then
                borrows = Semantic.integer_value(item.borrows)
                if not borrows or borrows < 1 then
                    return fail(Report.reject(Report.InvalidCaseLabel, item.name_range.start))
                end
            end
            host_types[item.name] = { destroys = item.destroys, borrows = borrows,
                                      type = Semantic.Named(item.name) }
            local id = reserve()
            -- The DECLARATION carries the destructor, because §3.6 makes the declaration the whole
            -- contract and §3.3 says destruction is inserted by `Lower` at scope exits -- which
            -- means `Lower` has to be able to ask a type what destroys it.
            declare(Judge.Definition(id, item.name, Judge.Host(item.destroys, borrows), nil,
                item.span, item.name_range))
            bind(item.name, id)
            return id
        end

        local resolve_initializer
        local resolve_body

        -- One chain -> its declaration. The chain's items are declarations in their own scope.
        -- `mutable` is §3.4's writable destination: a binding declared `mut` is assignable, and
        -- Lower makes it a `Cell` for exactly that reason. It rides on the DECLARATION because
        -- that is what mutability belongs to -- the same way `Judge.Member` already carries it.
        -- `own` is the definition being constructed, present only when the caller has already
        -- reserved its id. It is what the self name denotes: §1.4's "self name / recursion" row makes
        -- recursion a lexical, compile-time fact with no runtime reference, so a word that names
        -- itself is an ordinary reference to an ordinary definition -- which is what makes the call a
        -- call to the SAME belt instance rather than a second specialization of it (§S74).
        -- §12.1's table asks "which bindings does this word capture, in what order?" and this pair is
        -- what answers it: `level` is the scope depth of the chain being resolved and `captures` is
        -- its list. §2.2's residual is "captures + stage values 0…k-1 + prelude bindings", so the
        -- captures come first because they are the FRAME the rest of the packet lives in. A FILE is a
        -- chain too (§2.6), which is why the stack starts at the file's scope: a reference within the
        -- file is ordinary and a reference from a word in it is a capture.
        local current_level, current_captures = 1, L()

        -- §3.2: "captured state lives in a cell". A binding a word uses but does not OWN is a capture.
        -- It is a declaration of its own -- a binder, like a stage -- so a reference to it denotes the
        -- BINDER and not the outer definition, and its value IS the outer definition: that is what
        -- makes its value the ENCLOSING instance's, computed where that instance can compute it. One
        -- binder per (chain, outer binding), so two mentions are one capture and the order is first
        -- mention -- which is what makes the packet's layout deterministic.
        local function capture_of(outer, name, span, name_range, scope)
            local captures = current_captures
            for _, capture in ipairs(captures) do
                local definition = by_id[capture.binder]
                if definition and definition.declaration.value.definition == outer then
                    return capture.binder
                end
            end
            local binder = reserve()
            local declaration = by_id[outer] and by_id[outer].declaration
            -- §3.7: interior mutability is a property of the STORAGE and the storage belongs to the
            -- owner, so a `mut` binding is written through its capture and nothing else is. The
            -- declaration's own `mutable` is what `Contract` reads to allow that write.
            local mutable = declaration and declaration.mutable and true or false
            declare(Judge.Definition(binder, name,
                Judge.Value(Judge.Reference(outer, span), mutable, nil), scope, span, name_range))
            captures:insert(Chain.Capture(binder, name,
                mutable and Semantic.Mut or Semantic.Read))
            return binder
        end

        -- A binding's annotation, in ONE place, because there were two and the body's passed `nil`:
        -- `let s : Int | Handle = 5` inside a body was typed as the PAYLOAD and never injected, so the
        -- annotation was not merely unchecked, it changed what the value WAS. The second return says
        -- whether resolution succeeded, because "no annotation" and "a bad one" are different answers.
        local function annotation_of(binding)
            if not binding.constraint then return nil, true end
            local type_ = resolve_type(binding.constraint)
            if not type_ then return nil, false end
            return type_, true
        end

        local function resolve_value(chain, scope, name, mutable, annotation, own)
            push()
            local outer_level, outer_captures = current_level, current_captures
            local items, stages, group, members = L(), 0, L(), L()
            -- Is this chain a WORD -- an instance of its own -- or a VALUE, which is INLINED where it
            -- stands? §1.4's table gives a capture the enclosing lexical scope as its extent, so a
            -- reference crosses a boundary only when it enters a DIFFERENT instance: a chain with
            -- stages or a `do` terminal becomes a `Chain.Template` with a `run` of its own, while one
            -- with neither is lowered in the enclosing scope and captures nothing. `let a = f 1` is
            -- the second kind, and treating it as the first made every file-level binding a capture.
            local is_word = chain.terminal ~= nil and not Syntax.Data:isclassof(chain.terminal)
            if not is_word then
                for _, item in ipairs(chain.items) do
                    if Syntax.Stage:isclassof(item) then is_word = true break end
                end
            end
            if is_word then current_level, current_captures = #scopes, L() end
            local transient_from
            for _, item in ipairs(chain.items) do
                if Syntax.Stage:isclassof(item) then
                    -- A group is flushed when the stage that ends it arrives.
                    if #group > 0 then items:insert(Chain.Group(stages, group)); group = L() end
                    local spec = item.stage
                    local type_ = resolve_type(spec.constraint)
                    if not type_ then pop(); return nil end
                    if duplicate(spec.name, spec.name_range.start) then pop(); return nil end
                    local id = reserve()
                    if spec.capability == Semantic.Mut and not transient_from then
                        transient_from = stages
                    end
                    declare(Judge.Definition(id, spec.name, Judge.Bound(type_), scope,
                        spec.span, spec.name_range))
                    bind(spec.name, id)
                    items:insert(Chain.Stage(stages, spec.capability, type_, id))
                    stages = stages + 1
                elseif Syntax.Extern:isclassof(item) then
                    if duplicate(item.name, item.name_range.start) then pop(); return nil end
                    local template = resolve_extern(item, scope)
                    if not template then pop(); return nil end
                    local id = reserve()
                    declare(Judge.Definition(id, item.name, Judge.Word(template, nil),
                        scope, item.span, item.name_range))
                    bind(item.name, id)
                elseif Syntax.Prelude:isclassof(item) then
                    local binding = item.binding
                    if duplicate(binding.name, binding.name_range.start) then pop(); return nil end
                    local id = reserve()
                    local declared, ok = annotation_of(binding)
                    if not ok then pop(); return nil end
                    local declaration = resolve_value(binding.value, Judge.Lexical(id),
                        binding.name, binding.mutable, declared, id)
                    if not declaration then pop(); return nil end
                    declare(Judge.Definition(id, binding.name, declaration, scope,
                        binding.span, binding.name_range))
                    bind(binding.name, id)
                    group:insert(id)
                    members:insert(Judge.Member(binding.name, Judge.Reference(id, binding.span),
                        binding.mutable))
                else
                    pop()
                    return fail(Report.bug(Report.NoLowering('chain item'), chain.span))
                end
            end
            if #group > 0 then items:insert(Chain.Group(stages, group)) end

            -- `data` is the terminal's expression and `terminal` its judgment: a declaration whose
            -- chain has no stages is a VALUE and takes the expression, while a word takes the
            -- terminal -- which is why both are kept here.
            local terminal, data, kind, declared
            if not chain.terminal then
                -- §2.6: "A file with no written terminal exposes the named aggregate of its own
                -- prelude bindings, in source order." Read through §S26 -- an aggregate IS a chain
                -- -- that is the rule for any chain with no terminal, and this is its ONE owner:
                -- the entry file below builds its namespace the same way.
                kind = Chain.Data
                data = Judge.Aggregate(members, chain.span)
                terminal = Judge.Data(data)
            elseif chain.terminal then
                if Syntax.Data:isclassof(chain.terminal) then
                    kind = Chain.Data
                    data = resolve_initializer(chain.terminal.value, scope)
                    if not data then pop(); return nil end
                    terminal = Judge.Data(data)
                else
                    -- §3.1: "a runtime terminal MUST state its result" -- there is no term to read a
                    -- type from, so an unstated one is the program's fault, not a missing feature.
                    kind = Chain.Do
                    if not chain.terminal.result then
                        pop()
                        return fail(Report.reject(Report.UnstatedResult, chain.terminal.span))
                    end
                    declared = resolve_type(chain.terminal.result)
                    if not declared then pop(); return nil end
                    -- The self name must not be read by its own initializer or its stages, which run
                    -- while the word is being CONSTRUCTED -- and §1.4 makes it visible inside the
                    -- terminal `do` body, which runs after. So it is bound HERE, for the body alone:
                    -- the items above were resolved without it, an anonymous word has no self name,
                    -- and a data terminal (`let a = a`) never reaches this branch at all.
                    if own then
                        -- A stage of the same name and the self name are declarations in ONE scope,
                        -- so they cannot share it: binding one over the other makes a name silently
                        -- mean the wrong thing, which is worse than either answer. So it is what any
                        -- other duplicate is -- and the check is here rather than at the top because
                        -- the self name exists only for this branch.
                        if duplicate(name, chain.terminal.span) then pop(); return nil end
                        bind(name, own)
                    end
                    local statements = resolve_body(chain.terminal.statements, scope)
                    if not statements then pop(); return nil end
                    terminal = Judge.Body(statements)
                end
            end
            -- The chain ends here, and this is the ONE place it does: every early return above pops
            -- the scope and returns nil, so a failed resolve never continues -- which is why reading
            -- the captures here, before the restore, is enough.
            local captures = current_captures
            pop()
            if is_word then current_level, current_captures = outer_level, outer_captures end

            -- Spec §11.1: a chain with no stages and a data terminal *is* a value.
            if stages == 0 and kind ~= Chain.Do then
                if not terminal then
                    return fail(Report.bug(Report.NoLowering('namespace'), chain.span))
                end
                return Judge.Value(data, mutable and true or false, annotation)
            end
            local template = Chain.Template(name or '', items, stages, transient_from or stages,
                -- The declared result of a `do` terminal is what §11.3 makes the terminal's type:
                -- "a runtime terminal `do : R` is checked against every `return`".
                kind, declared, captures, Semantic.Runtime, Semantic.Ordered)
            return Judge.Word(template, terminal)
        end

        -- §11.2: conversions are DICTIONARY words, so a name that no lexical binding denotes may be
        -- one of them. §12.1: "Names ultimately resolve to lexical bindings or dictionary entries. A
        -- lexical binding wins over an entry" -- which is why this is the fallback and not the first
        -- test, and why `let ToInt = ...` shadows the conversion.
        --
        -- Each is a one-stage word whose terminal is the conversion itself, so it is applied,
        -- advanced and run by the machinery that already exists. The definitions are built once per
        -- resolver, because two uses of `ToInt` are two occurrences of one word.
        local dictionary = {}
        local function resolve_conversion(name, span, name_range, scope)
            local shape = Semantic.conversions[name]
            if not shape then return nil end
            if not dictionary[name] then
                push()
                -- The stage is a definition because the packet machinery needs one, and it needs a
                -- NAME because the packet's field is named from the binder. A conversion's argument
                -- has no source name, so it gets one -- and it must be a valid identifier, because
                -- that name reaches the emitted C as a struct member.
                local stage_id = reserve()
                declare(Judge.Definition(stage_id, 'value', Judge.Bound(shape.from),
                    scope, span, name_range))
                bind('value', stage_id)
                pop()
                local template = Chain.Template(name, L{Chain.Stage(0, Semantic.Read, shape.from,
                        stage_id)}, 1, 1, Chain.Convert(Semantic[name]), shape.to, L{},
                    Semantic.Runtime, Semantic.Pure)
                local id = reserve()
                declare(Judge.Definition(id, name, Judge.Word(template, nil), scope, span,
                    name_range))
                dictionary[name] = id
            end
            return dictionary[name]
        end

        -- §11.2's `Extern` -> a WORD whose terminal is a host symbol. The declaration IS the
        -- contract (§3.6): the ordered stages with their capabilities and types, the result, and
        -- purity -- because that is what the compiler holds a host to, and nothing else about the
        -- host is knowable. The stages are definitions like any other, so a host word's packet is
        -- built by the same machinery as a source word's.
        local function resolve_extern(item, scope)
            push()
            local items, stages, transient_from = L(), 0, nil
            for _, spec in ipairs(item.parameters) do
                local type_ = resolve_type(spec.constraint)
                if not type_ then pop(); return nil end
                if duplicate(spec.name, spec.name_range.start) then pop(); return nil end
                local stage_id = reserve()
                declare(Judge.Definition(stage_id, spec.name, Judge.Bound(type_), scope,
                    spec.span, spec.name_range))
                bind(spec.name, stage_id)
                if spec.capability == Semantic.Mut and not transient_from then transient_from = stages end
                items:insert(Chain.Stage(stages, spec.capability, type_, stage_id))
                stages = stages + 1
            end
            pop()
            local result = Semantic.Unit
            if item.result then
                result = resolve_type(item.result)
                if not result then return nil end
            end
            -- The terminal is `Chain.Host` and the JUDGE terminal is nil, because a host word has no
            -- body and no data to judge: the symbol is on the template, and the declaration's stages
            -- and result are the whole contract. That is why `Judge.Word`'s terminal is optional.
            local template = Chain.Template(item.name, items, stages, transient_from or stages,
                Chain.Host(item.symbol or item.name), result, L{}, Semantic.Runtime,
                item.pure and Semantic.Pure or Semantic.Ordered)
            return template
        end

        -- The stack of files whose chains are being resolved, so a cycle is a diagnostic rather
        -- than a hang: §2.6 makes a file that imports itself "a construction cycle".
        local importing = {}

        -- §2.6's import. One expression slot -- the path -- which must be a constant `Text`, so the
        -- spelling is the path and there is nothing to evaluate. The file's stages are supplied by
        -- the specialization arguments that FOLLOW, which is why this only needs the path: the
        -- result is a word whose stages the surrounding chain advances.
        local function resolve_import(expr, scope)
            local path = expr.argument
            local span = expr.span
            if not Syntax.Text:isclassof(path) then
                return fail(Report.reject(Report.ImportPath, span))
            end
            if importing[path.value] then
                return fail(Report.reject(Report.ImportCycle, span))
            end
            -- §13's kinds, and a diagnostic must not be dropped on the way out: `V.load` returns
            -- `Reject(MissingModule)` for a file that is not there, and returning nil WITHOUT it left
            -- the door with no diagnostic at all -- "the compiler stopped without a diagnostic", exit
            -- 2, which says the compiler is broken when the program named a file that is not there.
            local program, load_diagnostic = V.load(unit, path.value, span)
            if not program then return fail(load_diagnostic) end
            if not program then return nil end
            importing[path.value] = true
            local declaration = resolve_value(program.file, scope, '<import ' .. path.value .. '>', false)
            importing[path.value] = nil
            if not declaration then return nil end
            local id = reserve()
            declare(Judge.Definition(id, '<import ' .. path.value .. '>', declaration,
                Judge.Lexical(id), span, Source.Range(span, span)))
            return Judge.Reference(id, span)
        end

        resolve_initializer = function(expr, scope)
            -- §3.3/§S26: an aggregate's members are declarations with their own names, visible to
            -- later members. The aggregate is not a scope-bearing definition, so the members record
            -- the *enclosing* scope; only the name scope below is the aggregate's.
            if Syntax.NamedAggregate:isclassof(expr) then
                push()
                local members = L()
                for _, binding in ipairs(expr.members) do
                    if duplicate(binding.name, binding.name_range.start) then pop(); return nil end
                    -- §3.1: "a record type and a value aggregate are the same form", so a member's
                    -- value is a CHAIN -- and a chain is exactly what `resolve_value` resolves: items,
                    -- stages, terminal. So a member with preludes, or with stages (which make it a
                    -- WORD), is not a special case at all: it is a binding whose value is a chain, the
                    -- same thing a file's prelude is. It was `Missing(MemberPrelude)` because the
                    -- member path resolved the TERMINAL and refused anything before it.
                    --
                    -- `false` for the declaration's mutability and not `binding.mutable`: §3.7's `mut`
                    -- inside braces is interior mutability of the MEMBER, and `Judge.Member` carries
                    -- it -- the declaration's flag means §3.4 assignability, which a member of a
                    -- record does not have in its own right.
                    local id = reserve()
                    local declaration = resolve_value(binding.value, scope, binding.name, false, nil, id)
                    if not declaration then pop(); return nil end
                    declare(Judge.Definition(id, binding.name, declaration, scope,
                        binding.span, binding.name_range))
                    bind(binding.name, id)
                    -- The member's value is the *definition*, so the record's shape is written
                    -- once: a name, a type from the definition, and §3.7's mutability.
                    members:insert(Judge.Member(binding.name,
                        Judge.Reference(id, binding.span), binding.mutable))
                end
                pop()
                return Judge.Aggregate(members, expr.span)
            end

            if Syntax.PositionalAggregate:isclassof(expr) then
                local members = L()
                for _, element in ipairs(expr.elements) do
                    -- The positional form of the same sentence: an element is a chain too, so an
                    -- element with items is resolved as one -- and it has no name, because a positional
                    -- member has none (§11.6's `Member(string? name, ...)`).
                    if #element.items > 0 then
                        local id = reserve()
                        local declaration = resolve_value(element, scope, nil, false, nil, id)
                        if not declaration then return nil end
                        declare(Judge.Definition(id, '', declaration, scope, element.span,
                            Source.Range(element.span, element.span)))
                        members:insert(Judge.Member(nil, Judge.Reference(id, element.span), false))
                    else
                        local value = resolve_initializer(element.terminal.value, scope)
                        if not value then return nil end
                        members:insert(Judge.Member(nil, value, false))
                    end
                end
                return Judge.Aggregate(members, expr.span)
            end

            -- §1.4/§3.1: braces around STAGES are a WORD -- and §11.1 makes a chain with stages an
            -- instance of its own, so a word literal in value position is a VALUE and denotes a
            -- definition holding it, exactly as a positional element's chain does. This branch was
            -- MISSING, so `let Pair = let T : Int { let a : Int let b : Int }` was a
            -- `Bug(NoLowering('initializer'))`: an internal error about a shape the parser produces on
            -- purpose (parse.lua turns a stage list into this word, with the aggregate of the stage
            -- names as its data terminal). A program the grammar accepts is not the compiler's own
            -- fault, whatever the spelling turns out to mean.
            --
            -- The name is GENERATED because an anonymous word is named by nothing -- and a word's
            -- name is not only a diagnostic: `Lower` builds `let_<name>_construct`, `_advance_k` and
            -- `_run` from it, so two anonymous words sharing `''` would be one C function defined
            -- twice. The `id` is what makes them two definitions in the first place.
            if Syntax.Word:isclassof(expr) then
                local id = reserve()
                local declaration = resolve_value(expr.chain, scope, nil, false, nil, id)
                if not declaration then return nil end
                declare(Judge.Definition(id, 'word' .. id, declaration, scope, expr.span,
                    Source.Range(expr.span, expr.span)))
                return Judge.Reference(id, expr.span)
            end

            -- `{}` is the empty aggregate and the Unit value (§3.3), so it is a literal too.
            -- §3.4's operators. Syntax and Semantic each own a `UnaryOp`/`BinaryOp` sum -- they are
            -- separate vocabularies and Semantic sits below Syntax -- so the names are MAPPED here
            -- rather than shared, and the mapping is data because the two lists are the same list.
            if Syntax.Unary:isclassof(expr) then
                local operand = resolve_initializer(expr.operand, scope)
                if not operand then return nil end
                local operator = Semantic[getmetatable(expr.operator).kind]
                if not operator then return fail(Report.bug(Report.NoLowering('unary op'), expr.span)) end
                return Judge.Unary(operator, operand, expr.span)
            end
            if Syntax.Binary:isclassof(expr) then
                local left = resolve_initializer(expr.left, scope)
                if not left then return nil end
                local right = resolve_initializer(expr.right, scope)
                if not right then return nil end
                local operator = Semantic[getmetatable(expr.operator).kind]
                if not operator then return fail(Report.bug(Report.NoLowering('binary op'), expr.span)) end
                return Judge.Binary(operator, left, right, expr.span)
            end

            -- §1.4: `move place` transfers ownership. The place is resolved like any other
            -- expression; whether the transfer is legal is the ownership scan's question.
            if Syntax.Move:isclassof(expr) then
                local place = resolve_initializer(expr.place, scope)
                if not place then return nil end
                return Judge.Move(place, expr.span)
            end

            -- §1.4: a partial move's path must be statically known, so a subplace is named by a
            -- constant. A runtime index names no subplace -- that is a gap in the compiler, not a
            -- fault in the program, which is why it is `Missing` and not `Reject`.
            if Syntax.Project:isclassof(expr) then
                local base = resolve_initializer(expr.base, scope)
                if not base then return nil end
                return Judge.Project(base, expr.name, expr.span)
            end

            if Syntax.Index:isclassof(expr) then
                local base = resolve_initializer(expr.base, scope)
                if not base then return nil end
                -- §12.1's row, DERIVED: "is this step a constant or a runtime index?" A CONSTANT one
                -- names a member by offset, which is a `Judge.Index`; anything else is a
                -- `Judge.Element`, whose offset is an EXPRESSION -- and which member it names is then a
                -- runtime fact, which is why `Contract` checks the members can be one type.
                if Syntax.Integer:isclassof(expr.index) then
                    return Judge.Index(base, tonumber((expr.index.spelling:gsub('_', ''))), expr.span)
                end
                local index = resolve_initializer(expr.index, scope)
                if not index then return nil end
                return Judge.Element(base, index, expr.span)
            end

            -- §11.3's literals. They are one case because they are one case everywhere else: a
            -- `Judge.Literal` carries the syntax expression, and it is Contract that reads a type
            -- off it and Lower that turns it into a belt literal.
            if Syntax.Integer:isclassof(expr) or Syntax.Float:isclassof(expr)
                or Syntax.Boolean:isclassof(expr)
                or Syntax.Unit:isclassof(expr) or Syntax.Text:isclassof(expr) then
                return Judge.Literal(expr)
            end
            if Syntax.Name:isclassof(expr) then
                local id, level = find(expr.name)
                if id and level and level < current_level then
                    id = capture_of(id, expr.name, expr.span, Source.Range(expr.span, expr.span), scope)
                end
                if not id then
                    -- §2.4: "a type word is a chain with `Type` domains and a data terminal" -- so a
                    -- TYPE NAME is an expression like any other, which is what lets `case Int` be a
                    -- label (§S51) without a new vocabulary. One definition per name, because a type
                    -- word is a value and two mentions of `Int` are two mentions of one value.
                    local type_ = type_of_name(expr.name)
                    if type_ then
                        type_words[expr.name] = type_words[expr.name] or (function()
                            local type_id = reserve()
                            -- The declaration carries what the name DENOTES, because a type name
                            -- is a value of the type it names: `Int` denotes `Semantic.Int`, not a
                            -- `Named('Int')`. A label for a sum subject is compared against the
                            -- alternatives, so this is the difference between `case Int` working and
                            -- not (§S51).
                            declare(Judge.Definition(type_id, expr.name,
                                Judge.Type(type_), scope, expr.span, Source.Range(expr.span, expr.span)))
                            return { id = type_id, type = type_ }
                        end)()
                        id = type_words[expr.name].id
                    end
                end
                if not id then
                    id = resolve_conversion(expr.name, expr.span,
                        Source.Range(expr.span, expr.span), scope)
                end
                if not id then return fail(Report.reject(Report.UnknownName, expr.span)) end
                return Judge.Reference(id, expr.span)
            end
            -- `with` is left-associative, so the callee is itself an initializer: `f with a with b`
            -- is `Apply(Apply(f, a), b)` and the callee of the outer one is not a name.
            -- §2.6: `import` is "a dictionary entry in the construction phase, not a reserved
            -- spelling, so a lexical binding of that name still wins". That is why this tests the
            -- SCOPE before the name: `let import = ...` shadows it, and then the form is not an
            -- import at all.
            --
            -- Its one expression slot is the path, which must be a constant Text. The result is the
            -- imported file's TERMINAL -- which is exactly what `resolve_value` already returns for
            -- a chain, because a file IS a chain. So the import introduces one definition holding
            -- the file's declaration and the expression denotes it: a zero-stage word for a data
            -- terminal (which §S20 makes a value), or a word the importer advances and invokes.
            if Syntax.Specialize:isclassof(expr) and Syntax.Name:isclassof(expr.word)
                and expr.word.name == 'import' and not find('import') then
                return resolve_import(expr, scope)
            end
            if Syntax.Specialize:isclassof(expr) then
                local callee = resolve_initializer(expr.word, scope)
                if not callee then return nil end
                local argument = resolve_initializer(expr.argument, scope)
                if not argument then return nil end
                return Judge.Apply(callee, argument, expr.span)
            end
            -- §1.2's invocation stays its own form through resolution rather than being rewritten
            -- into an application here, because the two are NOT interchangeable: `f()` supplies no
            -- stage and is legal only where the word has none. Lower folds the arguments, so the
            -- operations are identical for a non-empty list, and `f()` is the one case that has no
            -- `with` spelling at all.
            if Syntax.Invoke:isclassof(expr) then
                local callee = resolve_initializer(expr.word, scope)
                if not callee then return nil end
                local arguments = L()
                for _, argument in ipairs(expr.arguments) do
                    local resolved = resolve_initializer(argument, scope)
                    if not resolved then return nil end
                    arguments:insert(resolved)
                end
                return Judge.Invoke(callee, arguments, expr.span)
            end
            return fail(Report.bug(Report.NoLowering('initializer'), expr.span))
        end

        -- A `do` body: a scope of statements. Each `let` is a declaration in it (§1.4), and the
        -- alternatives are the language's statement forms -- a closed set, which is what makes
        -- this a vocabulary and not a clone of the syntax tree.
        resolve_body = function(statements, scope)
            push()
            local resolved = L()
            for _, statement in ipairs(statements) do
                if Syntax.Local:isclassof(statement) then
                    local binding = statement.binding
                    if duplicate(binding.name, binding.name_range.start) then pop(); return nil end
                    local id = reserve()
                    local declared, ok = annotation_of(binding)
                    if not ok then pop(); return nil end
                    local declaration = resolve_value(binding.value, Judge.Lexical(id),
                        binding.name, binding.mutable, declared, id)
                    if not declaration then pop(); return nil end
                    declare(Judge.Definition(id, binding.name, declaration, scope,
                        binding.span, binding.name_range))
                    bind(binding.name, id)
                    resolved:insert(Judge.Local(id))
                elseif Syntax.Return:isclassof(statement) then
                    local value
                    if statement.value then
                        value = resolve_initializer(statement.value, scope)
                        if not value then pop(); return nil end
                    end
                    resolved:insert(Judge.Return(value, statement.span))
                elseif Syntax.Discard:isclassof(statement) then
                    local value = resolve_initializer(statement.value, scope)
                    if not value then pop(); return nil end
                    resolved:insert(Judge.Discard(value, statement.span))
                elseif Syntax.Switch:isclassof(statement) then
                    -- §12.1: the subject is resolved once, and each label is an EXPRESSION that
                    -- Contract will check against the subject's type. An arm is its own lexical
                    -- scope for the same reason an `if` arm is (§7.2).
                    local subject = resolve_initializer(statement.subject, scope)
                    if not subject then pop(); return nil end
                    local cases = L()
                    for _, arm in ipairs(statement.cases) do
                        -- §S60: a label SAYS which kind it is, so resolving one is a case over two
                        -- kinds rather than a guess about what a name denotes. A SHAPE is a type --
                        -- §2.4 makes a type an expression, and a structural shape has no other
                        -- spelling -- and a CONSTANT is a value.
                        local labels = L()
                        for _, label in ipairs(arm.labels) do
                            if Syntax.Shape:isclassof(label) then
                                local type_ = resolve_type(label.type)
                                if not type_ then pop(); return nil end
                                labels:insert(Judge.Shape(type_, nil))
                            else
                                local value = resolve_initializer(label.value, scope)
                                if not value then pop(); return nil end
                                labels:insert(Judge.Constant(value))
                            end
                        end
                        -- §S59: an arm that matched by SHAPE binds what it matched. A binder needs
                        -- exactly ONE shape -- two labels would bind two types -- and its own type
                        -- is that shape's, read straight off the label rather than derived from a
                        -- name, which is what `type_of_name` was being asked to do here.
                        local binds
                        if arm.binds then
                            local shape = #arm.labels == 1 and arm.labels[1]
                            if not (shape and Syntax.Shape:isclassof(shape)) then
                                pop()
                                return fail(Report.reject(Report.InvalidCaseLabel, arm.span))
                            end
                            local id = reserve()
                            declare(Judge.Definition(id, arm.binds,
                                Judge.Bound(labels[1].denotes), scope, arm.span,
                                Source.Range(arm.span, arm.span)))
                            -- Visible in the arm and nowhere else, so the arm's scope is pushed
                            -- around the body alone.
                            push()
                            bind(arm.binds, id)
                            binds = id
                        end
                        local body = resolve_body(arm.body, scope)
                        if not body then pop(); return nil end
                        if binds then pop() end
                        cases:insert(Judge.Case(labels, binds, body, arm.span))
                    end
                    local otherwise = resolve_body(statement.otherwise, scope)
                    if not otherwise then pop(); return nil end
                    resolved:insert(Judge.Switch(subject, cases, otherwise, statement.span))
                elseif Syntax.Assign:isclassof(statement) then
                    -- §3.4: the destination is evaluated first, "establishing the place without
                    -- replacing it", and then the right-hand side. That order is why both are
                    -- resolved here, left to right, and why Lower stores rather than rebinds.
                    local place = resolve_initializer(statement.place, scope)
                    if not place then pop(); return nil end
                    local value = resolve_initializer(statement.value, scope)
                    if not value then pop(); return nil end
                    resolved:insert(Judge.Assign(place, value, statement.span))
                elseif Syntax.If:isclassof(statement) then
                    local condition = resolve_initializer(statement.condition, scope)
                    if not condition then pop(); return nil end
                    -- §7.2: each arm has its own lexical scope, so each is a body of its own.
                    local yes = resolve_body(statement.yes, scope)
                    if not yes then pop(); return nil end
                    local no = resolve_body(statement.no, scope)
                    if not no then pop(); return nil end
                    resolved:insert(Judge.If(condition, yes, no, statement.span))
                elseif Syntax.While:isclassof(statement) then
                    local condition = resolve_initializer(statement.condition, scope)
                    if not condition then pop(); return nil end
                    local body = resolve_body(statement.body, scope)
                    if not body then pop(); return nil end
                    resolved:insert(Judge.While(condition, body, statement.span))
                elseif Syntax.Break:isclassof(statement) then
                    resolved:insert(Judge.Break(statement.span))
                elseif Syntax.Continue:isclassof(statement) then
                    resolved:insert(Judge.Continue(statement.span))
                else
                    -- Every statement form is handled now, so reaching here is a broken invariant
                    -- rather than a gap: a new form costs a constructor AND a case, and forgetting
                    -- the case is a Bug rather than a silently dropped statement.
                    pop()
                    return fail(Report.bug(Report.NoLowering('statement'), statement.span))
                end
            end
            pop()
            return resolved
        end

        push()     -- the module scope
        local members = L()
        for _, item in ipairs(program.file.items) do
            -- A top-level name is a namespace member whether it is written or DECLARED, because
            -- §2.6 is about names and not about where the name came from.
            if Syntax.Host:isclassof(item) then
                if not resolve_host(item) then pop(); return k_diag(unit, diagnostic) end
            elseif Syntax.Extern:isclassof(item) then
                if duplicate(item.name, item.name_range.start) then
                    pop(); return k_diag(unit, diagnostic)
                end
                local template = resolve_extern(item, nil)
                if not template then pop(); return k_diag(unit, diagnostic) end
                local id = reserve()
                declare(Judge.Definition(id, item.name, Judge.Word(template, nil), nil,
                    item.span, item.name_range))
                bind(item.name, id)
                members:insert(Judge.Member(item.name, Judge.Reference(id, item.span), false))
            elseif Syntax.Prelude:isclassof(item) then
                local binding = item.binding
                if duplicate(binding.name, binding.name_range.start) then
                    pop()
                    return k_diag(unit, diagnostic)
                end
                local id = reserve()
                -- §11.3 reads a type off a term where permitted, but a DECLARED annotation is a
                -- claim, not a reading -- so it is resolved here and CARRIED, because only Contract
                -- knows the value's type and only Contract can compare the two.
                local declared, ok = annotation_of(binding)
                if not ok then pop(); return k_diag(unit, diagnostic) end
                local declaration = resolve_value(binding.value, Judge.Lexical(id), binding.name,
                    binding.mutable, declared, id)
                if not declaration then pop(); return k_diag(unit, diagnostic) end
                declare(Judge.Definition(id, binding.name, declaration, nil,
                    binding.span, binding.name_range))
                bind(binding.name, id)
                members:insert(Judge.Member(binding.name, Judge.Reference(id, binding.span),
                    binding.mutable))
            else
                pop()
                return k_diag(unit, Report.bug(Report.NoLowering('top-level item'), program.file.span))
            end
        end
        -- The entry file's namespace is left to `Lower`, which assembles it from the definitions it
        -- can see (they are the ones with no `scope`). This is the SAME rule `resolve_value` applies
        -- to an imported file's chain -- "a file with no written terminal exposes the named aggregate
        -- of its own prelude bindings" -- and it has two implementations for one reason: the entry
        -- file is a module and not a definition, so its namespace is a `Belt` record rather than a
        -- `Judge.Initializer`, and building it here would need `rep` to map a WORD type, which is
        -- `Lower`'s `residual_type` and not `rep`'s business. Unifying them is a change to the
        -- semantic-to-belt mapping, not to this rule.
        local namespace
        if program.file.terminal then
            namespace = resolve_initializer(program.file.terminal.value, nil)
            if not namespace then pop(); return k_diag(unit, diagnostic) end
        end
        pop()

        local resolved = Judge.Resolved(definitions, namespace, L{})
        unit.ambient.resolved = resolved
        return k_ok(unit, resolved)
    end

    return Resolve
end

end)

-- let/contract.lua
module('let.contract', function(require, ...)
-- Judge.Resolved -> Judge.Program (DESIGN §12.2, §S25).
--
-- Contract **checks** rather than infers. Spec §3.1 and §11.3 require a stage to declare its type
-- word and a runtime terminal to state its result, and "reading a type off a term is not
-- inference": no type unknown is solved. So it reads a type off each declaration and checks every
-- use against it.
--
-- **A word value's type is nominal**: `Semantic.Word(template, prefix)`, where the prefix counts the
-- stages already supplied. That is what §S3 requires -- if `square` and `cube` shared a type, a
-- word-typed stage would admit either and the callee would need a uniform calling convention, which
-- is a vtable. So a reference to a word is `Word(id, 0)`, and an application either consumes the
-- last stage (yielding the terminal's type) or leaves `Word(id, prefix + 1)`.
--
-- Every definition gets an interface, value bindings included, because a data terminal with no
-- stages *is* a value (spec §11.1): the interface is a zero-stage data word.
--
-- `same` is deliberately identity here (`~=`): the primitive types are ASDL singletons, so identity
-- *is* structural equality. A structural `same` arrives with aggregates.
return function(V)
    local Syntax, Semantic, Chain, Judge, Report, L =
        V.Syntax, V.Semantic, V.Chain, V.Judge, V.Report, V.List

    local Contract = {}

    -- The stage items of a template, in order.
    local function stages_of(template)
        local stages = {}
        for _, item in ipairs(template.items) do
            if Chain.Stage:isclassof(item) then stages[#stages + 1] = item end
        end
        return stages
    end

    function Contract.run(unit, resolved, k_ok, k_diag)
        -- Declared here and assigned below, because the checks ask it and the table it needs is built
        -- after them -- the same shape `borrow_of` has.
        local copyable
        local names, declarations, types, typed = {}, {}, {}, L()
        for _, definition in ipairs(resolved.definitions) do
            names[definition.id] = definition.name
            declarations[definition.id] = definition.declaration
        end

        local diagnostic
        -- The FIRST failure is the one that matters. Once an interface cannot be built, everything
        -- that depends on it fails too -- so keeping the last would report a CONSEQUENCE and name
        -- the wrong thing. This is the difference between "`s.Text` is not an alternative" and "the
        -- function that mentions it does not return the right type", and only one of them is useful.
        local function fail(d)
            diagnostic = diagnostic or d
            return nil
        end

        -- The binding a destination place starts at, with its declaration. §3.4's writability is
        -- a property of that binding, so this is the one place the question is answered -- a
        -- projection or an index inherits it from its base rather than restating it.
        local function root_of(place)
            if Judge.Reference:isclassof(place) then return declarations[place.definition] end
            if Judge.Project:isclassof(place) then return root_of(place.base) end
            if Judge.Index:isclassof(place) or Judge.Element:isclassof(place) then
                return root_of(place.base)
            end
            return nil
        end

        -- Forward declarations: `type_of` asks for a definition's interface, and computing that
        -- interface asks `type_of` for the term a declaration is built from. The cycle is the point --
        -- and it is why the interface is PUBLISHED before a body is checked (§S74), so there is no
        -- cycle stack and nothing to re-enter -- so both are declared before either is used.
        -- The type words by NAME, built from DECLARATIONS rather than interfaces -- §S52's rule --
        -- because a declaration owns its fact and the interface may not be computed yet. This is what
        -- lets a sum's alternative be named, which is what a projection on a sum is (§S54).
        local word_by_name = {}
        for name, type_ in pairs(Semantic.primitive) do word_by_name[name] = type_ end
        for _, definition in ipairs(resolved.definitions) do
            local declaration = definition.declaration
            if Judge.Type:isclassof(declaration) then
                word_by_name[definition.name] = declaration.denotes
            elseif Judge.Host:isclassof(declaration) then
                word_by_name[definition.name] = Semantic.Named(definition.name)
            end
        end

        -- §3.5 says a value whose type equals exactly ONE alternative of a sum is INJECTED into it.
        -- So the question a site asks when a value meets an expected type is not "equal" but "equal
        -- OR injectable" -- and it is ONE rule, asked at every such site: a stage argument, a
        -- binding, a return, an assignment, a record member. Asking `equals` at each of them is how
        -- a sum-typed stage came to refuse the very values it exists to hold.
        -- §3.6's table, for the ONE row that is refused where the argument is supplied. The other
        -- three are decidable and fine: a literal is static storage that outlives every view, a place
        -- outlives the view as long as the view stays inside its scope (which is where an escape is
        -- caught), and a HOST call's result is foreign -- "the host's contract; Let holds nothing and
        -- checks nothing". Everything else is a temporary, and a view of a temporary outlives nothing.
        -- Being narrow here is the point: a row that refuses too much calls a correct program wrong,
        -- which is worse than a row that is not yet checked at all.
        local borrow_of

        -- §3.2: a capture is a second NAME for somebody else's storage, so asking what a name denotes
        -- has to follow it to the binding it captures -- exactly as `word_of` does in `Lower`. Without
        -- this, a host word a chain captures stops looking like a host word, and §3.6's foreign row
        -- silently becomes the temporary row: a correct program refused, which is the one outcome a
        -- check must never produce. Note that this does NOT answer `chain_owned`, which needs the
        -- capture to be visible AS a capture rather than followed.
        local function declaration_of(definition)
            local declaration = declarations[definition]
            while declaration and Judge.Value:isclassof(declaration)
                    and Judge.Reference:isclassof(declaration.value) do
                declaration = declarations[declaration.value.definition]
            end
            return declaration
        end

        local function check_borrowed_storage(interface, at, argument, span)
            if not interface.borrowed then return true end
            if borrow_of(interface.result) ~= at then return true end
            if Judge.Literal:isclassof(argument) then return true end
            if Judge.Reference:isclassof(argument) or Judge.Project:isclassof(argument)
                    or Judge.Index:isclassof(argument) or Judge.Element:isclassof(argument) then
                return true
            end
            local callee = nil
            if Judge.Apply:isclassof(argument) or Judge.Invoke:isclassof(argument) then
                callee = argument.callee
            end
            if callee and Judge.Reference:isclassof(callee) then
                local declaration = declaration_of(callee.definition)
                if declaration and Judge.Word:isclassof(declaration)
                        and Chain.Host:isclassof(declaration.word.terminal) then
                    return true
                end
            end
            return fail(Report.reject(Report.BorrowOfTemporary, span))
        end

        local function accepts(expected, actual)
            if expected:equals(actual) then return true end
            if not Semantic.Sum:isclassof(expected) then return false end
            local index, count = expected:alternative(actual)
            return index ~= nil and count == 1
        end

        local type_of, interface_of
        type_of = function(initializer)
            if Judge.Literal:isclassof(initializer) then
                local expr = initializer.value
                if Syntax.Integer:isclassof(expr) then return Semantic.Int end
                if Syntax.Unit:isclassof(expr) then return Semantic.Unit end
                if Syntax.Boolean:isclassof(expr) then return Semantic.Bool end
                if Syntax.Text:isclassof(expr) then return Semantic.Text end
                -- §11.3's `Float`: a float literal's type is its own form, the same rule the other
                -- literals follow. It was declared in every layer and produced by none, so `Float` and
                -- `Float32` were unwritable -- a type nothing can name a value of.
                if Syntax.Float:isclassof(expr) then return Semantic.Float end
                return fail(Report.bug(Report.NoLowering('literal'), expr.span))
            end

            if Judge.Reference:isclassof(initializer) then
                -- A word name denotes the *word value*, not its result, so its type is the whole
                -- arrow spine at prefix 0 -- spec §11.1 read through §S3's nominality.
                if Judge.Word:isclassof(declarations[initializer.definition]) then
                    return Semantic.Word(initializer.definition, 0)
                end
                -- Asked for, not read: `interface_of` computes it on demand, so a stage whose
                -- owning word has not been reached yet is no longer a hole.
                local interface = interface_of(initializer.definition)
                if not interface then return nil end
                return interface.result
            end

            if Judge.Apply:isclassof(initializer) then
                local callee = type_of(initializer.callee)
                if not callee then return nil end
                if not Semantic.Word:isclassof(callee) then
                    return fail(Report.reject(Report.NotExecutable, initializer.span))
                end
                local stages = stages_of(declarations[callee.template].word)
                local at = callee.prefix + 1
                if at > #stages then
                    return fail(Report.reject(Report.Oversaturated, initializer.span))
                end
                local argument = type_of(initializer.argument)
                if not argument then return nil end
                if not accepts(stages[at].type, argument) then
                    return fail(Report.reject(Report.MismatchedType, initializer.span))
                end
                local interface = interface_of(callee.template)
                if not interface then return nil end
                if not check_borrowed_storage(interface, at, initializer.argument, initializer.span) then
                    return nil
                end
                if at == #stages then return interface.result end
                return Semantic.Word(callee.template, at)
            end

            -- §3.4 and §1.5/§1.5: operators have no implicit conversions, so every rule is a
            -- statement about operand types. Arithmetic and bitwise are Int -> Int, comparisons are
            -- Int -> Bool, and `and`/`or` are Bool -> Bool. `not` is the one unary Bool.
            if Judge.Unary:isclassof(initializer) then
                local operand = type_of(initializer.operand)
                if not operand then return nil end
                local operator = initializer.operator
                if operator == Semantic.Not then
                    if not operand:equals(Semantic.Bool) then
                        return fail(Report.reject(Report.MismatchedType, initializer.span))
                    end
                    return Semantic.Bool
                end
                if not operand:equals(Semantic.Int) then
                    return fail(Report.reject(Report.MismatchedType, initializer.span))
                end
                return Semantic.Int
            end
            if Judge.Binary:isclassof(initializer) then
                local left = type_of(initializer.left)
                if not left then return nil end
                local right = type_of(initializer.right)
                if not right then return nil end
                local operator = initializer.operator
                if operator == Semantic.And or operator == Semantic.Or then
                    if not left:equals(Semantic.Bool) or not right:equals(Semantic.Bool) then
                        return fail(Report.reject(Report.MismatchedType, initializer.span))
                    end
                    return Semantic.Bool
                end
                if not left:equals(Semantic.Int) or not right:equals(Semantic.Int) then
                    return fail(Report.reject(Report.MismatchedType, initializer.span))
                end
                if operator == Semantic.Equal or operator == Semantic.NotEqual
                    or operator == Semantic.Less or operator == Semantic.LessEqual
                    or operator == Semantic.Greater or operator == Semantic.GreaterEqual then
                    return Semantic.Bool
                end
                return Semantic.Int
            end

            -- §1.2: invocation is transient saturation, so it must reach the terminal. An
            -- invocation that stops short is undersaturated -- the residual would be a temporary,
            -- and a temporary is not a value (§1.2), so there is nothing to give a type to.
            if Judge.Invoke:isclassof(initializer) then
                local callee = type_of(initializer.callee)
                if not callee then return nil end
                if not Semantic.Word:isclassof(callee) then
                    return fail(Report.reject(Report.NotExecutable, initializer.span))
                end
                local stages = stages_of(declarations[callee.template].word)
                local interface = interface_of(callee.template)
                if not interface then return nil end
                local at = callee.prefix
                for _, argument in ipairs(initializer.arguments) do
                    local argument_type = type_of(argument)
                    if not argument_type then return nil end
                    if at + 1 > #stages then
                        return fail(Report.reject(Report.Oversaturated, initializer.span))
                    end
                    if not accepts(stages[at + 1].type, argument_type) then
                        return fail(Report.reject(Report.MismatchedType, initializer.span))
                    end
                    if not check_borrowed_storage(interface, at + 1, argument, initializer.span) then
                        return nil
                    end
                    at = at + 1
                end
                if at < #stages then
                    return fail(Report.reject(Report.Undersaturated, initializer.span))
                end
                return interface_of(callee.template).result
            end

            -- Naming the class is what makes an unhandled form actionable instead of a search.
            local class = getmetatable(initializer)
            -- A move's type is the place's type: `move` transfers a value, it does not make one.
            if Judge.Move:isclassof(initializer) then
                -- A place is a name, a member or a constant index; anything else is a value, and a
                -- value is not something a move can take.
                local place = initializer.place
                if not (Judge.Reference:isclassof(place) or Judge.Project:isclassof(place)
                        or Judge.Index:isclassof(place) or Judge.Element:isclassof(place)) then
                    return fail(Report.reject(Report.ReadOnlyDestination, initializer.span))
                end
                return type_of(initializer.place)
            end

            -- A projection's type is the member's, read off the base. A RECORD's member is a field
            -- and its type is right there. A SUM has no members -- it has ALTERNATIVES, and an
            -- alternative is reached by the arm that MATCHED it (§S59), so `s.Int` is not a
            -- program: there is no way to ask for a payload without having established which
            -- alternative is there, which is exactly why a payload read cannot fail.
            if Judge.Project:isclassof(initializer) then
                local base = type_of(initializer.base)
                if not base then return nil end
                if Semantic.Sum:isclassof(base) then
                    return fail(Report.reject(Report.UnknownName, initializer.span))
                end
                if not Semantic.Aggregate:isclassof(base) then
                    return fail(Report.reject(Report.UnknownName, initializer.span))
                end
                for _, field in ipairs(base.fields) do
                    if field.name == initializer.name then return field.type end
                end
                return fail(Report.reject(Report.UnknownName, initializer.span))
            end

            -- §3.3: indexing a positional place yields an element place. The index is constant,
            -- so an out-of-range one is a diagnostic rather than a runtime trap.
            if Judge.Element:isclassof(initializer) then
                -- §12.1's derivation: `a[i]` with a RUNTIME `i` has one type only if every member of
                -- the aggregate has that type -- the offset names one of them and the compiler cannot
                -- know which, so a mixed tuple is a `MismatchedType` rather than a hole. It is the same
                -- question §3.5 asks of a sum's alternatives, asked of a record's members.
                local base = type_of(initializer.base)
                if not base then return nil end
                local index = type_of(initializer.index)
                if not index then return nil end
                if not index:equals(Semantic.Int) then
                    return fail(Report.reject(Report.MismatchedType, initializer.span))
                end
                if not Semantic.Aggregate:isclassof(base) or #base.fields == 0 then
                    return fail(Report.reject(Report.IndexOutOfRange, initializer.span))
                end
                local element = base.fields[1].type
                for _, field in ipairs(base.fields) do
                    if not field.type:equals(element) then
                        return fail(Report.reject(Report.MismatchedType, initializer.span))
                    end
                end
                return element
            end
            if Judge.Index:isclassof(initializer) then
                local base = type_of(initializer.base)
                if not base or not Semantic.Aggregate:isclassof(base) then
                    return fail(Report.reject(Report.IndexOutOfRange, initializer.span))
                end
                local field = base.fields[initializer.offset + 1]
                if not field then
                    return fail(Report.reject(Report.IndexOutOfRange, initializer.span))
                end
                return field.type
            end

            if Judge.Aggregate:isclassof(initializer) then
                local fields = L()
                for _, member in ipairs(initializer.members) do
                    local type_ = type_of(member.value)
                    if not type_ then return nil end
                    -- §3.7: a member's mutability is part of the record's *type*, not of how the
                    -- member was supplied, which is why it lands on the field.
                    fields:insert(Semantic.Field(member.name, type_, member.mutable))
                end
                return Semantic.Aggregate(fields, nil)
            end

            return fail(Report.bug(Report.NoLowering('initializer ' .. tostring(class and class.kind)),
                resolved.definitions[1].span))
        end

        -- §11.3: "a runtime terminal `do : R` is checked against every `return`", and a discarded
        -- value is dropped, so it must be Copy -- a destruction is an ownership action, and a
        -- discarded expression's required destruction stays observable (§7.3).
        -- §7.2: a condition is `Bool` -- "there is no implicit truthiness" (§12.3).
        -- §12.2's label identity. A label must be a literal, and two labels collide by VALUE
        -- than by spelling -- which is why this returns a key rather than comparing text.
        -- §S60: a label is a SHAPE or a CONSTANT, and which one it is is what the label SAYS. That
        -- is the difference from §S51 -- which read a label as an expression and therefore had to
        -- ask what a NAME denoted -- and it is why nothing below reads a declaration.
        --
        -- A SHAPE must be an alternative of a sum subject. A CONSTANT must be a literal of the
        -- subject's own type, and two constants collide by VALUE rather than by spelling: `1` and
        -- `0x1` are one label. Either way the key is what the label MEANS, and a repeat is a
        -- rejection rather than a silent second arm.
        local function case_key(label, subject)
            if Judge.Shape:isclassof(label) then
                if not Semantic.Sum:isclassof(subject) then return nil end
                for index, alternative in ipairs(subject.alternatives) do
                    if alternative:equals(label.denotes) then
                        return 'alt:' .. tostring(index - 1), index - 1
                    end
                end
                return nil
            end
            -- A CONSTANT label: a literal of the subject's own type, keyed by VALUE.
            local constant = label.value
            if not Judge.Literal:isclassof(constant) then return nil end
            local label_type = type_of(constant)
            if not label_type or not label_type:equals(subject) then return nil end
            local expr = constant.value
            if Syntax.Integer:isclassof(expr) then
                return 'Int:' .. tostring(Semantic.integer_value(expr.spelling))
            end
            if Syntax.Boolean:isclassof(expr) then return 'Bool:' .. tostring(expr.value) end
            return nil
        end

        local function check_condition(condition, span)
            local type_ = type_of(condition)
            if not type_ then return nil end
            if type_ ~= Semantic.Bool then
                return fail(Report.reject(Report.MismatchedType, span))
            end
            return true
        end

        -- Whether a statement list GUARANTEES an exit. A syntactic approximation, and the honest
        -- one: a `while` may not run and an `if` without an `else` may fall through, so neither
        -- terminates on its own -- which is exactly §12.3's "falling through the end returns Unit".
        -- Only the body's own list is asked; an arm that falls through merely continues after the
        -- `if`, so termination is not a property of an arm.
        local function terminates(statements)
            local last = statements[#statements]
            if not last then return false end
            if Judge.Return:isclassof(last) then return true end
            if Judge.If:isclassof(last) then
                return #last.no > 0 and terminates(last.yes) and terminates(last.no)
            end
            -- An arm that does not match falls through to after the switch, so a `switch`
            -- terminates only when every value is caught -- an `else`, or a Bool subject whose
            -- labels are `true` and `false`, which the spec calls exhaustive. Without this the
            -- statement below a `switch` looks like a fall-through and the word is rejected.
            if Judge.Switch:isclassof(last) then
                local every_arm = true
                local seen = {}
                -- `case_key` needs the subject's type, because what a label may be follows from it
                -- (§S51): a constant for a scalar subject, an alternative for a sum one.
                local subject_type = type_of(last.subject)
                for _, arm in ipairs(last.cases) do
                    if not terminates(arm.body) then every_arm = false end
                    for _, label in ipairs(arm.labels) do
                        local key = subject_type and case_key(label, subject_type)
                        if key then seen[key] = true end
                    end
                end
                if not every_arm then return false end
                if #last.otherwise > 0 then return terminates(last.otherwise) end
                -- Exhaustive means every VALUE is caught, and what that takes depends on the
                -- subject. A SUM always holds one of its alternatives, so labelling all of them is
                -- exhaustive -- which is the mirror of the Bool rule below, and the reason a sum
                -- `switch` can be a word's whole body.
                if subject_type and Semantic.Sum:isclassof(subject_type) then
                    local labelled = 0
                    for key in pairs(seen) do
                        if key:sub(1, 4) == 'alt:' then labelled = labelled + 1 end
                    end
                    return labelled == #subject_type.alternatives
                end
                if not subject_type or not subject_type:equals(Semantic.Bool) then return false end
                return seen['Bool:true'] and seen['Bool:false'] and true or false
            end
            return false
        end

        -- Every `return` is checked against the stated result, wherever it sits (§11.3, §7.2).
        -- §3.6's containment row -- "the view's scope must be inside the owner's" -- compares two
        -- SCOPES, and the fact that decides which scope the owner lives in is already in source. A
        -- `Judge.Bound` is a stage the CALLER supplies and a capture reaches storage the enclosing
        -- instance owns (a module prelude is one, because §S76 made it a capture), while a
        -- `Judge.Value` with its own initializer is a PRELUDE of the chain being lowered, which dies
        -- when the chain returns. So this READS A DECLARATION instead of carrying a lifetime, which is
        -- what §1.4 means by "every extent is a construct the compiler already computes".
        local function chain_owned(declaration)
            if not declaration or not Judge.Value:isclassof(declaration) then return false end
            return not Judge.Reference:isclassof(declaration.value)
        end

        -- §3.1 rule 4, on VALUES: a borrow travels with the value, so a view made from this chain's
        -- storage is still this chain's once it is bound, moved, projected or put in an aggregate. The
        -- answer is read from DECLARATIONS and never accumulated while a body is walked, so it cannot
        -- depend on the order the checks happen to run in.
        local function borrows_chain_storage(initializer)
            if initializer == nil then return false end
            if Judge.Reference:isclassof(initializer) then
                local declaration = declarations[initializer.definition]
                if declaration and Judge.Value:isclassof(declaration) then
                    return borrows_chain_storage(declaration.value)
                end
                return false
            end
            if Judge.Project:isclassof(initializer) or Judge.Index:isclassof(initializer)
                    or Judge.Element:isclassof(initializer) then
                return borrows_chain_storage(initializer.base)
            end
            if Judge.Move:isclassof(initializer) then
                return borrows_chain_storage(initializer.place)
            end
            if Judge.Aggregate:isclassof(initializer) then
                for _, member in ipairs(initializer.members) do
                    if borrows_chain_storage(member.value) then return true end
                end
                return false
            end
            -- The call that MAKES the view. §3.6's index names the storage it views, so this is where
            -- a view of a chain-owned place is born -- and it is the only place, because the core has
            -- no view type and only a host declaration can name a borrow.
            if Judge.Apply:isclassof(initializer) or Judge.Invoke:isclassof(initializer) then
                local callee = type_of(initializer.callee)
                if not callee or not Semantic.Word:isclassof(callee) then return false end
                local interface = interface_of(callee.template)
                if not interface or not interface.borrowed then return false end
                local index = borrow_of(interface.result)
                if not index then return false end
                local argument
                if Judge.Apply:isclassof(initializer) then
                    if index == callee.prefix + 1 then argument = initializer.argument end
                else
                    argument = initializer.arguments[index - callee.prefix]
                end
                if not argument then return false end
                return chain_owned(root_of(argument))
            end
            return false
        end

        local function check_body(statements, result)
            for _, statement in ipairs(statements) do
                if Judge.Return:isclassof(statement) then
                    local value = statement.value and type_of(statement.value) or Semantic.Unit
                    if not value then return nil end
                    if not value:equals(result) then
                        return fail(Report.reject(Report.MismatchedType, statement.span))
                    end
                    -- §3.1 rule 3: "no use may place it in a longer-lived position". A return is the
                    -- way out of a chain, so a view of this chain's own storage that leaves here
                    -- outlives what it views.
                    if borrows_chain_storage(statement.value) then
                        return fail(Report.reject(Report.BorrowedEscapes, statement.span))
                    end
                elseif Judge.Discard:isclassof(statement) then
                    local value = type_of(statement.value)
                    if not value then return nil end
                    if not copyable(value) then
                        return fail(Report.reject(Report.NeedsMove, statement.span))
                    end
                elseif Judge.If:isclassof(statement) then
                    if not check_condition(statement.condition, statement.span) then return nil end
                    if not check_body(statement.yes, result) then return nil end
                    if not check_body(statement.no, result) then return nil end
                elseif Judge.While:isclassof(statement) then
                    if not check_condition(statement.condition, statement.span) then return nil end
                    if not check_body(statement.body, result) then return nil end
                elseif Judge.Switch:isclassof(statement) then
                    -- Labels and the subject share a type, and a label is a literal -- see S50 for why
                    -- or Bool LITERALS, and "duplicate labels are errors, including numerically
                    -- equal spellings such as 1 and 0x1". So the key is the VALUE, not the text.
                    local subject = type_of(statement.subject)
                    if not subject then return nil end
                    local seen = {}
                    -- An arm that binds a non-Copy payload MOVES the subject (§3.5), and the arms
                    -- binding a non-Copy payload does. Every other arm leaves it alive.
                    for _, arm in ipairs(statement.cases) do
                        for _, label in ipairs(arm.labels) do
                            -- `case_key` answers the whole question for the subject's kind, so a
                            -- label that is not a constant of a scalar subject, or not an
                            -- alternative of a sum subject, is one rejection rather than two.
                            local key, alternative = case_key(label, subject)
                            if not key or seen[key] then
                                return fail(Report.reject(Report.InvalidCaseLabel, statement.span))
                            end
                            seen[key] = true
                            -- §S60: "a label is a SHAPE or a CONSTANT and SAYS WHICH" -- and this is the
                            -- phase that can say it, because it is the phase that has the SUBJECT's
                            -- type. `Lower` cannot: the belt representation of two alternatives can be
                            -- ONE type (two word values with empty packets are both `uint8_t`), so
                            -- re-deriving it there matched the LAST alternative and every arm
                            -- dispatched to one body. A label is where the answer belongs, and it is
                            -- the same answer the binder's payload comes from.
                            if Judge.Shape:isclassof(label) then label.alternative = alternative end
                        end
                        -- §S59: an arm that binds is an arm that matched by SHAPE, so the subject
                        -- must be a sum and the label one of its alternatives -- and the binder
                        -- must carry that alternative's type, since it IS the payload. A payload
                        -- that cannot be copied has to be MOVED out of the sum, and moving a
                        -- payload moves the whole sum; that spelling does not exist yet, so this
                        -- refuses rather than copying something that cannot be copied.
                        if arm.binds then
                            local declaration = declarations[arm.binds]
                            local type_ = declaration and declaration.declared
                            local index = type_ and Semantic.Sum:isclassof(subject)
                                and subject:alternative(type_)
                            if not index then
                                return fail(Report.reject(Report.InvalidCaseLabel, statement.span))
                            end
                            -- §S65: whether a binder COPIES or TAKES is DERIVED from the payload's
                            -- type (§1.4), exactly as a stage's declared capability decides whether
                            -- it borrows (§S45) -- so there is nothing to refuse here. A payload that
                            -- cannot be copied is moved, and §3.5 makes moving a payload a move of the
                            -- WHOLE sum, which is why the arms of a mixed sum disagree about it and
                            -- §3.3 rejects them rather than this line.
                        end
                        -- §S65: taking a payload TAKES the subject -- but nothing is REPORTED for
                        -- that here any more, because the rule became a MECHANISM. A path that leaves
                        -- the sum alive does not need an arm to dispose of it: §3.5's destructor is
                        -- chosen by the TAG and `Lower` builds that dispatch, so a sum nobody takes is
                        -- destroyed at its scope exit like anything else. What remains is the divergence
                        -- that is OBSERVABLE -- a join something reaches and then uses -- and that is
                        -- `Lower`'s `agree`, where the places are known.
                        if not check_body(arm.body, result) then return nil end
                    end
                    if not check_body(statement.otherwise, result) then return nil end
                elseif Judge.Assign:isclassof(statement) then
                    -- §3.4: "Assignment requires a writable destination place", and "assigning
                    -- through a read-only binding ... is an error". Writability is a property of
                    -- the binding the place STARTS at, so that is where the question is answered.
                    local root = root_of(statement.place)
                    if not root then
                        return fail(Report.reject(Report.ReadOnlyDestination, statement.span))
                    end
                    -- §3.7: a `mut` MEMBER is interior mutability, so a place is writable if the
                    -- binding it starts at is `mut` OR any step of its path names a mutable field.
                    -- That is one rule and not two: a `mut` binding makes everything under it
                    -- writable, and a `mut` member does the same for its own subtree.
                    local function writes_through_a_member(place)
                        if Judge.Reference:isclassof(place) then return false end
                        local base = type_of(place.base)
                        local fields = base and Semantic.Aggregate:isclassof(base) and base.fields
                        if not fields then return false end
                        local field
                        if Judge.Project:isclassof(place) then
                            for _, candidate in ipairs(fields) do
                                if candidate.name == place.name then field = candidate end
                            end
                        else
                            field = fields[place.offset + 1]
                        end
                        if field and field.mutable then return true end
                        return writes_through_a_member(place.base)
                    end
                    if not (Judge.Value:isclassof(root) and root.mutable)
                        and not writes_through_a_member(statement.place) then
                        return fail(Report.reject(Report.ReadOnlyDestination, statement.span))
                    end
                    local target = type_of(statement.place)
                    if not target then return nil end
                    local value = type_of(statement.value)
                    if not value then return nil end
                    -- §3.4: "Assignment of an EXISTING non-copyable value requires `move`." The word
                    -- is existing: a FRESH value -- a call's result, an aggregate, a literal -- owns
                    -- itself and is stored as it stands, while an existing PLACE of a non-Copy type has
                    -- to be taken, because reading a place is a borrow and a borrow is not a value
                    -- (§1.4). Reading the TYPE alone refused `h = made(n)`, which is a store of
                    -- something new and has nothing to move.
                    local existing = Judge.Reference:isclassof(statement.value)
                        or Judge.Project:isclassof(statement.value)
                        or Judge.Index:isclassof(statement.value)
                        or Judge.Element:isclassof(statement.value)
                    if existing and not copyable(value) and not Judge.Move:isclassof(statement.value) then
                        return fail(Report.reject(Report.NeedsMove, statement.span))
                    end
                    if not accepts(target, value) then
                        return fail(Report.reject(Report.MismatchedType, statement.span))
                    end
                end
            end
            return true
        end

        -- §12.2 says the state of this phase is "interface table, cycle stack" -- and that is what
        -- it now is: an interface is computed ON DEMAND and memoized, not filled in by a walk.
        --
        -- A walk has an ORDER, and a definition routinely references one with a HIGHER id: a word's
        -- stages are created inside the word's own chain, and so is any type word a `case` names. So
        -- a walk leaves holes that depend on which definition was visited first -- which is not a
        -- fact about the program, and it produced three separate defects of the same shape. The
        -- cycle stack is the other half, and it is what turns a reference cycle into a diagnostic
        -- rather than a hang (§1.4 defers mutual recursion, so "no interface" is the honest answer).
        local by_id, building = {}, {}

        -- §2.5: `Copy` is derived, and a WORD's value is its PACKET, so a word type is Copy exactly
        -- when every member of that packet is -- the rule a record follows, asked of the declaration
        -- because that is where the members are named. `Semantic.Word(template, prefix)` cannot answer
        -- it (its template is a NUMBER and `Semantic` sits below `Chain`, §11.4), so each layer derives
        -- the fact from the declaration and NEITHER ASKS THE OTHER -- §S61's shape exactly. Without it a
        -- word value the design calls Copy -- an imported file's namespace, whose only member is an
        -- `Int`-staged word -- was refused with `NeedsMove`, so `import` could not be bound at all.
        copyable = function(type_)
            if not type_ then return false end
            if Semantic.Word:isclassof(type_) then
                local definition = by_id[type_.template]
                if not definition or not Judge.Word:isclassof(definition.declaration) then return false end
                for _, id in ipairs(definition.declaration.word:members(type_.prefix)) do
                    local interface = types[id]
                    if not interface or not copyable(interface.result) then return false end
                end
                return true
            end
            -- ... and THROUGH a record or a sum, for the reason `Lower` does the same: the semantic
            -- derivation asks `Semantic.Word`, which cannot see a template, so a namespace containing a
            -- word would be reported non-Copy.
            if Semantic.Aggregate:isclassof(type_) then
                for _, field in ipairs(type_.fields) do
                    if not copyable(field.type) then return false end
                end
                return true
            end
            if Semantic.Sum:isclassof(type_) then
                for _, alternative in ipairs(type_.alternatives) do
                    if not copyable(alternative) then return false end
                end
                return true
            end
            return type_:copyable()
        end
        for _, definition in ipairs(resolved.definitions) do by_id[definition.id] = definition end

        -- §3.6: a host type may declare that it borrows argument i, and a value of such a type is a
        -- BORROWED type -- which §3.1 rule 4 propagates structurally, because a record holding a view
        -- holds the borrow too. `borrow_of` answers WHICH argument, because that is what §3.6's table
        -- needs in order to classify the storage; `Interface.borrowed` is this same question asked for
        -- a yes, so there is one owner for it and not two.
        local host_borrows = {}
        for _, definition in ipairs(resolved.definitions) do
            local declaration = definition.declaration
            if Judge.Host:isclassof(declaration) and declaration.borrows then
                host_borrows[definition.name] = declaration.borrows
            end
        end
        borrow_of = function(type_)
            if Semantic.Named:isclassof(type_) then return host_borrows[type_.name] end
            if Semantic.Aggregate:isclassof(type_) then
                for _, field in ipairs(type_.fields) do
                    local index = borrow_of(field.type)
                    if index then return index end
                end
            elseif Semantic.Sum:isclassof(type_) then
                for _, alternative in ipairs(type_.alternatives) do
                    local index = borrow_of(alternative)
                    if index then return index end
                end
            end
        end

        interface_of = function(id)
            local memoized = types[id]
            if memoized then return memoized end
            local definition = by_id[id]
            if not definition then
                return fail(Report.bug(Report.NoLowering('definition'), resolved.definitions[1].span))
            end
            -- A CYCLE in the derivation, which §12.1's acyclic resolution says cannot happen: a name
            -- There is no re-entry check here, and that is the design: an interface is a fact about a
            -- DECLARATION (§S52), so it is PUBLISHED into `types` as soon as the declaration determines
            -- it, before any body is checked. A body that names its own word -- recursion -- then finds
            -- it on the way in and never re-enters. The guard that used to live here was a guess about
            -- the future; what replaces it is a PLACE, and the place is the publish (§S74).
            local declaration = definition.declaration
            local interface
            if Judge.Bound:isclassof(declaration) then
                interface = Judge.Interface(L{}, declaration.declared, Chain.Data, false)
            elseif Judge.Type:isclassof(declaration) or Judge.Host:isclassof(declaration) then
                -- §2.4: "a type word is a chain with `Type` domains and a data terminal", evaluated
                -- at construction time and erased. So a declared type's NAME is a value of type
                -- `TypeWord` -- which is what lets `Handle` be a type and a name without either
                -- being a special case.
                interface = Judge.Interface(L{}, Semantic.TypeWord, Chain.Data, false)
            elseif Judge.Value:isclassof(declaration) then
                local type_ = type_of(declaration.value)
                if not type_ then return nil end
                -- A DECLARED annotation is a claim the compiler checks (§12.2 "checks rather than
                -- infers"), and until now it was simply dropped: `let x : Int = true` was accepted
                -- because the type was read off the value and the annotation never looked at.
                -- §3.5: a sum is inhabited by a member whose type matches exactly ONE alternative.
                -- "None" and "more than one" are different refusals, which is why the alternative
                -- rule reports a count rather than a bare index.
                if declaration.declared then
                    if Semantic.Sum:isclassof(declaration.declared) then
                        local index, count = declaration.declared:alternative(type_)
                        if not index then
                                return fail(Report.reject(Report.MismatchedType, definition.span))
                        end
                        if count > 1 then
                            return fail(Report.reject(Report.InvalidConversion, definition.span))
                        end
                    elseif not declaration.declared:equals(type_) then
                        return fail(Report.reject(Report.MismatchedType, definition.span))
                    end
                end
                interface = Judge.Interface(L{}, declaration.declared or type_, Chain.Data, false)
            elseif Judge.Word:isclassof(declaration) then
                local stages = L()
                for _, item in ipairs(declaration.word.items) do
                    if Chain.Stage:isclassof(item) then
                        -- §11.1/§S3's boundary, checked where the DECLARATION is: a stage is a value
                        -- the CALLER supplies, so its type must be one a value can have. An ARROW and
                        -- a `do` are SHAPES and have no representation at all -- `rep` maps both to
                        -- nil -- so a stage declared with one reached `Belt.Parameter` with a nil and
                        -- CRASHED the compiler. It is the program's fault, and `NotExecutable` is the
                        -- same refusal that invoking such a stage already gets (§S99).
                        if Semantic.Arrow:isclassof(item.type) or Semantic.Do:isclassof(item.type) then
                            return fail(Report.reject(Report.NotExecutable, definition.span))
                        end
                        stages:insert(Judge.Parameter(names[item.binder], item.capability, item.type))
                    end
                end
                -- A data terminal's type is read off its value; a `do` terminal's is DECLARED,
                -- which is why §3.1 makes the annotation mandatory for it -- there is no term to
                -- read the type from. A HOST terminal has no term at all: the declaration's stages
                -- and result ARE the contract (§3.6), so its result is the template's.
                local result, body
                if not declaration.terminal then
                    result = declaration.word.result
                elseif Judge.Data:isclassof(declaration.terminal) then
                    result = type_of(declaration.terminal.value)
                else
                    result = declaration.word.result
                    body = declaration.terminal.statements
                end
                if not result then return nil end
                -- §S52: the interface is what the DECLARATION says, so it is published BEFORE the body
                -- is checked. That is the whole of what recursion needs -- a declaration is complete
                -- even while its definition is not -- and it is why the checks below can name this
                -- very word without re-entering this derivation (§S74).
                interface = Judge.Interface(stages, result, declaration.word.terminal,
                    borrow_of(result) ~= nil)
                types[id] = interface
                if body then
                    if not check_body(body, result) then return nil end
                    if not terminates(body) and result ~= Semantic.Unit then
                        return fail(Report.reject(Report.MismatchedType, definition.span))
                    end
                end
            else
                return fail(Report.bug(Report.NoLowering('declaration'), definition.span))
            end
            types[id] = interface
            typed:insert(Judge.Typed(id, interface))
            return interface
        end

        -- The drive. Every definition is ASKED for, so every one is checked -- but the order no
        -- longer matters, because each interface is computed on demand and memoized.
        for _, definition in ipairs(resolved.definitions) do
            if not interface_of(definition.id) then return k_diag(unit, diagnostic) end
        end

        -- A written terminal replaces the namespace (§2.6), and its type is the module's result.
        local namespace_type
        if resolved.namespace then
            namespace_type = type_of(resolved.namespace)
            if not namespace_type then return k_diag(unit, diagnostic) end
        end

        local program = Judge.Program(resolved.definitions, resolved.namespace, namespace_type, typed)
        unit.ambient.program = program
        return k_ok(unit, program)
    end

    return Contract
end

end)

-- let/lower.lua
module('let.lower', function(require, ...)
-- The demanded instances: Judge.Program -> Belt.Function* (DESIGN §12.3, §S23, §S25).
--
-- **Lower is demand-driven from the roots.** The roots are the module initializer and each exported
-- word's entry point (spec §2.6); a root demands what it needs, and the set of demanded instances
-- is progress on `Unit` because it outlives any one `Function` (§6).
--
-- That is not an optimization. Spec §5.2 makes an instance exist *because something demanded it*:
-- "each specialization constructs a new semantic result". §S25 refines the granularity to the
-- **prefix**: a word value is `R(t,0)`, demanded by the definition that binds it, while `advance_k`
-- and `run` are demanded by applications. So a word nothing applies is demanded at prefix 0 only --
-- its value exists, its later prefixes and its terminal do not, and it can never fail compilation.
--
-- `demand` reserves an instance's id **before** lowering it, which is what makes a cycle terminate:
-- a self-application finds the id already there instead of recursing.
--
-- Numbering, restated because it is the rule that has to be exactly right: within a block, producer
-- positions are zero-based, parameters first and then instructions; at consumer position `p`,
-- `Ref(distance, output)` denotes producer `p - 1 - distance`; the exit's position is the end of the
-- instruction sequence.
return function(V)
    local B, Semantic, Syntax, Chain, Judge, Report, L =
        V.Belt, V.Semantic, V.Syntax, V.Chain, V.Judge, V.Report, V.List

    local Lower = {}

    -- Representation. The semantic type word is what the program means; the belt type is what the
    -- emitter materializes, and the two are different vocabularies (DESIGN §S5).
    local residual_type

    local function rep(L_, type_)
        -- §10: `Semantic` owns meaning and `Belt` owns representation, and this is the ONLY mapping
        -- between them. So anything else here is a caller mistake -- and it used to be a SILENT one,
        -- because `rep` fell through to nil and every caller reads nil as "no representation for
        -- this". Twice that meant a value which was ALREADY a belt type was mapped a second time,
        -- and the check that asks whether it has a representation answered no. The guard costs
        -- nothing and makes the whole class impossible: a belt type is not a `Semantic.Type`, so it
        -- cannot be mapped twice by accident.
        assert(Semantic.Type:isclassof(type_),
            'rep maps a Semantic.Type to a Belt.Type, not a ' ..
            tostring(getmetatable(type_) and getmetatable(type_).kind or type_))
        if type_ == Semantic.Int then return B.Int end
        if type_ == Semantic.Bool then return B.Bool end
        if type_ == Semantic.Unit then return B.Unit end
        -- §11.3: Text is a module-lifetime literal, and its representation is the belt's `Text` --
        -- a pointer to static storage. The two foreign views (`CString`, `CPointer`) are host
        -- vocabulary (§3.6) and arrive with it.
        if type_ == Semantic.Text then return B.Text end
        -- §11.7's scalar types, one for one. The foreign pair is a representation and nothing more:
        -- §3.6 says a view's extent is the scope that made it, so there is no belt type for "borrowed"
        -- and there should not be.
        if type_ == Semantic.U8 then return B.U8 end
        if type_ == Semantic.U32 then return B.U32 end
        -- §2.2: a WORD's value is its PACKET, so a word type maps to its residual. This is why the
        -- mapping takes the lowerer at all: `residual_type` builds a packet out of the template's
        -- items, which `Semantic` cannot see (a word type names its template by number, §11.4) and
        -- which `Chain` cannot map into `Belt`. Everything else here is structural, which is what `rep`
        -- was when it had one argument -- and one argument made a record CONTAINING a word impossible:
        -- an imported file's namespace is exactly that, so `import` was
        -- `Bug(NoLowering(form = representation))`.
        if Semantic.Word:isclassof(type_) then
            local declaration = L_.declarations[type_.template]
            if declaration and Judge.Word:isclassof(declaration) then
                return residual_type(L_, declaration.word, type_.prefix)
            end
            return nil
        end
        if type_ == Semantic.Float then return B.Float end
        if type_ == Semantic.Float32 then return B.Float32 end
        -- A DECLARED host type's representation is its own name: the host owns the C definition, so
        -- the compiler names it and nothing more. That is §3.6's "the host's contract; Let holds
        -- nothing and checks nothing" made concrete.
        if Semantic.Named:isclassof(type_) then return B.Named(type_.name) end
        -- §11.7 has a sum on both sides, so the mapping is structural like a record's. An ARROW and a
        -- `do`, by contrast, have no representation at all: a word's type is nominal in its template
        -- (§S3) and a `do` describes a chain, so neither is a layout -- and `rep` returning nil is
        -- how that is said.
        if Semantic.Sum:isclassof(type_) then
            local alternatives = L()
            for _, alternative in ipairs(type_.alternatives) do
                local mapped = rep(L_, alternative)
                if not mapped then return nil end
                alternatives:insert(mapped)
            end
            return B.Sum(alternatives)
        end
        if type_ == Semantic.CString then return B.CString end
        if type_ == Semantic.CPointer then return B.CPointer end
        -- A record's representation is a record of its members' representations, so the mapping is
        -- recursive and the mutability of a member is part of the representation (§3.7).
        if Semantic.Aggregate:isclassof(type_) then
            local fields = L()
            for _, field in ipairs(type_.fields) do
                local field_type = rep(L_, field.type)
                if not field_type then return nil end
                fields:insert(B.Field(field.name, field_type, field.mutable))
            end
            return B.Aggregate(fields)
        end
        return nil
    end

    local function stages_of(template)
        local stages = {}
        for _, item in ipairs(template.items) do
            if Chain.Stage:isclassof(item) then stages[#stages + 1] = item end
        end
        return stages
    end

    ---------------------------------------------------------------------------------------------
    -- The lowerer: the demanded set, the functions produced, and the lookup tables a declaration
    -- needs. All of it is progress on one transition, so it lives beside `Unit`, not on a God
    -- object.
    ---------------------------------------------------------------------------------------------

    local function lowerer(unit, program)
        local L_ = { unit = unit, program = program, demanded = {}, functions = {},
                     next_id = 0, diagnostic = nil,
                     definitions = {}, declarations = {}, names = {}, types = {} }
        for _, definition in ipairs(program.definitions) do
            L_.definitions[definition.id] = definition
            L_.declarations[definition.id] = definition.declaration
            L_.names[definition.id] = definition.name
        end
        for _, entry in ipairs(program.typed) do L_.types[entry.definition] = entry.interface end
        -- The one thing `Judge.word_of` needs from this layer: where a declaration lives (§S101). It is
        -- a function rather than the table because `Resolve` keeps the same table in the other shape --
        -- it holds the DEFINITION and the declaration is its `.declaration` field.
        L_.lookup = function(id) return L_.declarations[id] end
        -- §3.2's captures, indexed BOTH ways: by the binder a body names, and by the binding whose
        -- storage that binder is -- because that second one is the binding that has to become a CELL.
        -- A capture is not a copy of the owner's state; it is a second name for the same storage.
        L_.capture_of_binder, L_.capture_of_owner = {}, {}
        for _, definition in ipairs(program.definitions) do
            local declaration = definition.declaration
            if Judge.Word:isclassof(declaration) then
                for _, capture in ipairs(declaration.word.captures or {}) do
                    L_.capture_of_binder[capture.binder] = capture
                    local inner = L_.definitions[capture.binder]
                    if inner then
                        L_.capture_of_owner[inner.declaration.value.definition] = capture
                    end
                end
            end
        end
        -- What destroys a value of each named type, by name. §3.6 puts the destructor in the type's
        -- DECLARATION, and §3.3 puts destruction in `Lower`, so this is where the two meet.
        L_.destructors = {}
        for _, definition in ipairs(program.definitions) do
            local declaration = definition.declaration
            if Judge.Host:isclassof(declaration) and declaration.destroys then
                L_.destructors[definition.name] = declaration.destroys
            end
        end
        return L_
    end

    -- Reserve an instance's id before lowering it, so a cycle finds the id rather than recursing.
    local function demand(L_, key, build)
        local existing = L_.demanded[key]
        if existing then return existing end
        L_.next_id = L_.next_id + 1
        local id = L_.next_id
        L_.demanded[key] = id
        local belt, diagnostic = build(L_, id)
        if not belt then L_.diagnostic = diagnostic; return nil end
        L_.functions[id] = belt
        return id
    end

    ---------------------------------------------------------------------------------------------
    -- Regions. Each instance gets its own `Function` child, and within it a region owns the current
    -- block, the locations and the effect thread.
    ---------------------------------------------------------------------------------------------

    -- A draft block. Blocks are indexed from ONE in their function, and an `Edge` names a block by
    -- that id -- so a split can wire a join before the join's own body exists.
    local function new_block(C)
        local block = { parameters = L{}, instructions = L{}, id = #C.out.blocks + 1 }
        C.out.blocks:insert(block)
        return block
    end

    local function open(L_, name)
        local node = L_.unit:child{ instance = name }
        local C = node:region()
        C.out.name = name
        C.out.next_value = 0
        C.out.blocks = L{}
        local entry = new_block(C)
        C.state.block = entry
        C.state.locations = {}
        C.state.values = {}      -- definition id -> the belt value standing for it
        C.state.places = {}      -- definition id -> §1.4's Initialized | Moved
                                 -- (progress: the scan's current point, not a fact in a value)
        return C
    end

    local function parameter(C, type_, capability)
        local block = C.state.block
        local position = #block.parameters
        block.parameters:insert(B.Parameter(type_, capability))
        local value = { id = C.out.next_value, type = type_ }
        C.out.next_value = C.out.next_value + 1
        C.state.locations[value.id] = { position = position, output = 0 }
        return value
    end

    local function ref(C, value)
        local at = C.state.locations[value.id]
        local position = #C.state.block.parameters + #C.state.block.instructions
        return B.Ref(position - 1 - at.position, at.output)
    end

    local function emit(C, op, types)
        local block = C.state.block
        local position = #block.parameters + #block.instructions
        block.instructions:insert(B.Instruction(op, types, nil))
        local values = L()
        for i = 1, #types do
            local value = { id = C.out.next_value, type = types[i] }
            C.out.next_value = C.out.next_value + 1
            C.state.locations[value.id] = { position = position, output = i - 1 }
            values:insert(value)
        end
        return values
    end

    local function pure(C, op, type_) return emit(C, B.Pure(op), L{type_})[1] end

    -- An ordered operation produces its effect successor **last**, and the region carries it: that
    -- is what keeps the effect chain unbroken without the emitter inventing a value for it.
    local function ordered(C, op, type_)
        local types = type_ and L{type_, B.Effect} or L{B.Effect}
        local values = emit(C, B.Ordered(op), types)
        C.state.effect = values[#types]
        if type_ then return values[1] end
    end

    local function freeze(C, results, exported)
        -- Every draft block, frozen in id order: a split's arms and join are blocks of the SAME
        -- function, so the function's body is the list, not the block the region happened to end in.
        local blocks = L()
        for _, block in ipairs(C.out.blocks) do
            blocks:insert(B.Block(block.parameters, block.instructions, block.exit))
        end
        return B.Function(C.out.name, B.Signature(C.out.blocks[1].parameters, results), blocks,
            exported and true or false)
    end

    ---------------------------------------------------------------------------------------------
    -- The packet. `R(t,k)` is the record after k stable stages, and its members are exactly the
    -- chain's declarations in the order the chain produced them: group 0's preludes, stage 0,
    -- group 1's preludes, stage 1, ..., group k's preludes.
    ---------------------------------------------------------------------------------------------

    local function packet_of(L_, template, k) return template:members(k) end

    local function packet_members_are_in_chain(L_, template, k)
        local members = {}
        -- §2.2: `R(t,k) = captures + stage values 0…k-1 + prelude bindings of groups 0…k`. The
        -- captures are the FRAME, so they come first at EVERY prefix -- which is what makes the packet
        -- structurally the same record at every stage, and what lets a nested word reach the storage
        -- its enclosing instance owns.
        for _, capture in ipairs(template.captures or {}) do
            members[#members + 1] = capture.binder
        end
        for _, item in ipairs(template.items) do
            if Chain.Group:isclassof(item) then
                if item.at <= k then
                    for _, id in ipairs(item.preludes) do
                        members[#members + 1] = id
                    end
                end
            elseif item.index < k then
                members[#members + 1] = item.binder
            end
        end
        return members
    end

    local field_type_of

    -- What a name HOLDS, which is the question every packet field and every place's content asks.
    local function belt_type_of(L_, id)
        local declaration = L_.declarations[id]
        if Judge.Bound:isclassof(declaration) then return rep(L_, declaration.declared) end
        -- A WORD's value is its PACKET and not its result (§2.2), and a CAPTURE's value is whatever the
        -- binding it captures holds -- its own declaration is a second NAME for somebody else's
        -- storage, so following it is the difference between typing the frame and typing its answer.
        --
        -- ONLY a capture may be followed, and `L_.capture_of_binder` is that question. Asking it
        -- STRUCTURALLY -- "a Value whose value is a Reference" -- also matched an ordinary binding
        -- that happens to hold a word value, so `let chosen : square | inc = inc` was typed as the
        -- PACKET, the sum was never injected, and the host got `uint8_t` where the module struct
        -- wanted the sum. The captures are known before anything is lowered (`Judge.Resolved`
        -- carries them), so this is the definition rather than a proxy for it.
        if L_.capture_of_binder[id] and declaration and Judge.Value:isclassof(declaration)
                and Judge.Reference:isclassof(declaration.value) then
            local outer = L_.declarations[declaration.value.definition]
            if outer and Judge.Word:isclassof(outer) then
                return residual_type(L_, outer.word, 0)
            end
        end
        local interface = L_.types[id]
        return interface and rep(L_, interface.result)
    end

    -- The SEMANTIC counterpart of `belt_type_of`, and it exists because §3.5's injection is a question
    -- about MEANING rather than shape: a word definition's slot holds a word VALUE, so its type is
    -- nominal in the definition itself (§S3) and is not `L_.types[id].result`, which is what the word
    -- RETURNS. That is the same rule `Contract` reads off a Reference (`type_of`), derived here from
    -- the same declaration -- the shape §S92 already uses for copyability, and the reason the two
    -- layers agree without either asking the other.
    local function slot_type_of(L_, id)
        local declaration = L_.declarations[id]
        if Judge.Bound:isclassof(declaration) then return declaration.declared end
        if L_.capture_of_binder[id] and declaration and Judge.Value:isclassof(declaration)
                and Judge.Reference:isclassof(declaration.value) then
            local outer = L_.declarations[declaration.value.definition]
            if outer and Judge.Word:isclassof(outer) then
                return Semantic.Word(declaration.value.definition, 0)
            end
        end
        local interface = L_.types[id]
        return interface and interface.result
    end

    residual_type = function(L_, template, k)
        local fields = L()
        for _, id in ipairs(packet_of(L_, template, k)) do
            local field_type = field_type_of(L_, id)
            local type_ = field_type
            if not type_ then return nil end
            fields:insert(B.Field(L_.names[id], type_, false))
        end
        return B.Aggregate(fields)
    end

    -- The word a callee names, and how many stages it already holds. The question is `Judge.word_of`'s
    -- (§S101), because `Resolve` asks it too -- a name in TYPE position is the type of the value it
    -- denotes -- and two copies of this walk is the defect this design keeps finding. The only thing
    -- this layer adds is where declarations live.
    local function word_of(L_, initializer)
        return Judge.word_of(L_.lookup, initializer)
    end

    ---------------------------------------------------------------------------------------------
    -- Initializers. One alternative plus its method.
    ---------------------------------------------------------------------------------------------

    -- Forward declarations: an application demands a callee's instance, and the builders below are
    -- what run when it does, so the dependency runs both ways.
    local build_construct, build_advance, build_run, lower_body, lower_if, lower_while, is_cell,
        place_value, capture_arguments, lower_place, live, arguments_of, destroy_value, destroy_sum,
        lower_element
    local lower_assign, lower_switch, lower_short_circuit, lower_entry

    -- The construction of a word value: `construct` plus §2.2's capture frame, in ONE place, because
    -- three sites build `R(t,0)` -- naming a word, supplying its first stage, and invoking it with no
    -- arguments -- and the capture arguments must be computed in the ENCLOSING instance in all three.
    local function construct_base(L_, C, template, word)
        local construct = demand(L_, 'construct:' .. template, function(M, id)
            return build_construct(M, template, id)
        end)
        if not construct then return nil, L_.diagnostic end
        local captures, diagnostic = capture_arguments(L_, C, word)
        if not captures then return nil, diagnostic end
        return ordered(C, B.CallFunction(construct, ref(C, C.state.effect), captures),
            residual_type(L_, word, 0))
    end

    -- The base of an application, `R(t,0)`: CONSTRUCTED when the callee is a word named in this scope,
    -- and READ when it is a CAPTURE. §3.2's "one indirection" is exactly this -- the packet already
    -- exists, in the enclosing instance's frame or behind the cell it holds -- so constructing a second
    -- one would give the word a state of its own instead of the owner's, which is the same defect
    -- §S75 records for a module prelude one level up.
    local function base_of(L_, C, template, word, callee)
        if callee and Judge.Reference:isclassof(callee) and L_.capture_of_binder[callee.definition] then
            local p, diagnostic = lower_place(L_, C, callee)
            if not p then return nil, diagnostic end
            return place_value(C, p)
        end
        -- §3.6/§11.1: a stage whose type is a WORD already HOLDS its packet -- the caller built it and
        -- passed it -- so the base is that value rather than a construction from source, which a stage
        -- has none of. This is the other half of naming one: `word_of` says WHICH word, and this says
        -- where its prefix values come from.
        if callee and Judge.Reference:isclassof(callee) then
            local bound = L_.declarations[callee.definition]
            if bound and Judge.Bound:isclassof(bound) and bound.declared
                    and Semantic.Word:isclassof(bound.declared) then
                local p, diagnostic = lower_place(L_, C, callee)
                if not p then return nil, diagnostic end
                return place_value(C, p)
            end
        end
        return construct_base(L_, C, template, word)
    end


    -- A place's state. DESIGN §3.3: ownership is a *sequential scan with an agreement check at
    -- every join*, so the state is progress on the region -- not a dataflow solution and not a
    -- value. A definition is initialized once it is lowered, and `move` is what falsifies it.
    local function place(C, id)
        local state = C.state.places[id]
        if not state then state = { moved = {} }; C.state.places[id] = state end
        return state
    end

    -- Two paths conflict when either contains the other: a moved subplace makes every place that
    -- contains it, and every place inside it, unusable until a value is assigned (§1.4).
    local function contains(outer, inner)
        if outer == inner or outer == '' then return true end
        return inner:sub(1, #outer + 1) == outer .. '.'
    end

    -- §1.4's path check. `intermediate` is a read *through* a place -- a projection reads its base
    -- to reach a member, which never touches a hole elsewhere in it, and §1.4 says so.
    local function check_place(C, root, path, span, intermediate)
        for was in pairs(place(C, root).moved) do
            if contains(was, path) then
                return Report.reject(Report.UninitializedPlace, span)
            end
            if not intermediate and contains(path, was) then
                return Report.reject(Report.PartiallyInitialized, span)
            end
        end
    end

    local materialize

    -- Take ownership of a place: §1.4's `move place`. On a Copy place it is that value, copied,
    -- and the place stays initialized; on a non-Copy one the source becomes uninitialized. The
    -- transfer is recorded in the belt as a `Move`, which has no runtime representation of its
    -- own -- the value is already in hand, and the source is simply not destroyed.
    -- §3.1's second rule: "destruction: reverse initialization order, at scope exit / return /
    -- replacement." This is the SCOPE EXIT half, and it is a scan rather than an analysis for the
    -- same reason ownership is (§3.3): the region's environment already says what is live, and the
    -- place state already says what was moved out. A moved-out binding has no value left to destroy,
    -- which is why a `move` out of a scope is not a leak.
    --
    -- Whether a value of this type must be DESTROYED. A derived property, like Copy (§2.5) and
    -- derived the same way -- structurally, from the type: a declared host type says so in its
    -- declaration (§3.6), a record says so if ANY member does, and a scalar owns nothing. It is the
    -- mirror image of Copy, which asks whether every member is Copy.
    local destroys
    destroys = function(L_, type_)
        if not type_ then return false end
        if Semantic.Named:isclassof(type_) then return L_.destructors[type_.name] ~= nil end
        if Semantic.Aggregate:isclassof(type_) then
            for _, field in ipairs(type_.fields) do
                if destroys(L_, field.type) then return true end
            end
        end
        -- §3.5: a sum is destructible when ANY alternative is -- the exact MIRROR of §2.5's `Copy` rule
        -- for a sum ("every alternative"). They cannot be one rule: `Copy` asks whether every part may be
        -- duplicated, while destruction is chosen by the TAG, so one alternative that owns something is
        -- enough to make destroying the sum mean something.
        if Semantic.Sum:isclassof(type_) then
            for _, alternative in ipairs(type_.alternatives) do
                if destroys(L_, alternative) then return true end
            end
        end
        return false
    end

    local function destructor_of(L_, id)
        local interface = L_.types[id]
        if not interface or not destroys(L_, interface.result) then return nil end
        return interface.result
    end

    -- §12.3: "a block's parameters are `[Effect] + the values live at the split`, and an edge's arguments
    -- match them one for one" -- so a value that has to CROSS a split must be nameable, and a lowered
    -- value that is not a definition (a call's result, a load, a field read) is not. This is the same
    -- reason §S34's switch subject is bound, and it is the only binding this phase invents.
    local function name_it(L_, C, value, type_)
        L_.synthetic = (L_.synthetic or 0) - 1
        C.state.values[L_.synthetic] = value
        return L_.synthetic
    end

    -- Will destroying this build BLOCKS? A sum's destruction is a dispatch on its tag (§3.5), and a
    -- record's is one when a member's is. Asked by the RETURN path, because a value that crosses a split
    -- has to be named and naming one that stays put would put a C variable in every function.
    local function dispatches(L_, type_)
        if Semantic.Sum:isclassof(type_) then
            for _, alternative in ipairs(type_.alternatives) do
                if destroys(L_, alternative) then return true end
            end
            return false
        end
        if Semantic.Aggregate:isclassof(type_) then
            for _, field in ipairs(type_.fields) do
                if destroys(L_, field.type) and dispatches(L_, field.type) then return true end
            end
        end
        return false
    end

    -- Every binding THIS region introduced whose type declares a destructor, in initialization
    -- order. A region's `values` is the carried parameters plus what it bound itself, and only the
    -- second has a scope that ends with the region -- a parameter belongs to whoever created it.
    -- That is the same distinction the interface draws, so it is drawn the same way: a parameter's
    -- position is inside the parameter list.
    local function destroyable(L_, C)
        local found = {}
        for id, value in pairs(C.state.values) do
            local location = C.state.locations[value.id]
            -- §3.2: a CAPTURE is not owned HERE. Its storage belongs to the enclosing instance -- one
            -- indirection, shared -- so destroying it from a frame that merely borrowed it destroys the
            -- owner's value a second time. The owner's own scope exit is what destroys it.
            -- ... and a WORD is not owned here either: a word's value is its PACKET (§2.2), while its
            -- interface's result is the type its `run` RETURNS -- so destroying one as a value of that
            -- type hands a host destructor a struct where it wants a handle.
            local declaration = L_.declarations[id]
            if location and location.position >= #C.state.block.parameters
                and not Judge.Word:isclassof(declaration)
                and not L_.capture_of_binder[id] and destructor_of(L_, id) then
                found[#found + 1] = id
            end
        end
        table.sort(found)
        return found
    end

    -- Destroy ONE value, and its parts. §3.1 rule 2 is about INITIALIZATION order, so a record's
    -- members go in reverse member order -- and a member that was moved out has no value left to
    -- destroy, which is the same place state the scan already keeps, one path deeper. Without this a
    -- record that owns a resource destroys only the record, and the resource leaks.
    destroy_value = function(L_, C, root, path, type_, value)
        if Semantic.Named:isclassof(type_) then
            ordered(C, B.Destroy(ref(C, C.state.effect), ref(C, value),
                L_.destructors[type_.name]), nil)
            return
        end
        -- §3.5: a sum's destructor is chosen by its TAG, so it is a dispatch and not a sequence. Until
        -- this existed a sum fell through the line below and NOTHING was emitted for it: a silent leak,
        -- and one only a host counting its own allocations could see (§S81, §S83).
        if Semantic.Sum:isclassof(type_) then
            destroy_sum(L_, C, root, path, type_, value)
            return
        end
        if not Semantic.Aggregate:isclassof(type_) then return end
        for index = #type_.fields, 1, -1 do
            local field = type_.fields[index]
            local inner = path == '' and tostring(index - 1) or (path .. '.' .. (index - 1))
            if destroys(L_, field.type) and not place(C, root).moved[inner] then
                local member = pure(C, B.LoadField(ref(C, value), index - 1), rep(L_, field.type))
                destroy_value(L_, C, root, inner, field.type, member)
            end
        end
    end

    -- Destroy them in REVERSE initialization order, which is rule 2's other half.
    local function destroy_all(L_, C)
        local found = destroyable(L_, C)
        for index = #found, 1, -1 do
            local id = found[index]
            if not place(C, id).moved[''] then
                -- §S32: a cell's VALUE is its address, so destroying what it holds is a LOAD of
                -- the content and not a call on the storage. Without this the emitter hands the
                -- destructor `&v` where it wants a value -- invalid C for a host type, and a
                -- destroy of the wrong thing for a record, whose members are read off `value`.
                local value = C.state.values[id]
                if is_cell(L_, id) then
                    -- `belt_type_of` and not `L_.types[id].result`: the Load produces the CONTENT,
                    -- and the interface's result is the content's SEMANTIC type -- what a cell holds
                    -- is a belt type, and `destroy_value` below still wants the semantic one.
                    value = ordered(C, B.Load(ref(C, C.state.effect), ref(C, value)),
                        belt_type_of(L_, id))
                end
                destroy_value(L_, C, id, '', L_.types[id].result, value)
            end
        end
    end

    -- §3.2's table has three rows and this decides between them: "captured by a sibling word ⇒ celled
    -- (one indirection)", "captured read of a Copy value ⇒ copied; no cell", "not captured ⇒ zero
    -- cost". Celling is therefore a property of the (mode, type) PAIR, derived here and asked twice --
    -- once for the capture's own binder and once for the binding it captures -- because the cell IS
    -- the owner's storage: one indirection, shared, and no second allocation.
    local copyable

    -- §2.5: `Copy` is derived, and a WORD's value is its PACKET, so a word type is Copy exactly when
    -- every member of that packet is -- the rule a record follows, asked of a template because that is
    -- where the members are named. `Semantic.Word(template, prefix)` cannot answer it (it names its
    -- template by NUMBER and `Semantic` sits below `Chain`, §11.4), which is the same reason `rep` takes
    -- the lowerer. Until this existed a word value the design calls COPY -- an imported file's
    -- namespace, whose only member is an `Int`-staged word -- was reported non-Copy, so `import` could
    -- not even be bound.
    local function word_value_is_copy(L_, template, k)
        for _, id in ipairs(template:members(k)) do
            local declaration = L_.declarations[id]
            local type_ = Judge.Bound:isclassof(declaration) and declaration.declared
                or (L_.types[id] and L_.types[id].result)
            if not copyable(L_, type_) then return false end
        end
        return true
    end

    copyable = function(L_, type_)
        if not type_ then return false end
        if Semantic.Word:isclassof(type_) then
            local declaration = L_.declarations[type_.template]
            if not declaration or not Judge.Word:isclassof(declaration) then return false end
            return word_value_is_copy(L_, declaration.word, type_.prefix)
        end
        -- A record or a sum CONTAINING a word is why this cannot simply be `type_:copyable()`: the
        -- semantic derivation recurses into its members by asking `Semantic.Word`, which cannot see a
        -- template -- so a namespace whose only member is a word was reported non-Copy and could not be
        -- bound at all. Recursing HERE keeps one rule and reaches every member.
        if Semantic.Aggregate:isclassof(type_) then
            for _, field in ipairs(type_.fields) do
                if not copyable(L_, field.type) then return false end
            end
            return true
        end
        if Semantic.Sum:isclassof(type_) then
            for _, alternative in ipairs(type_.alternatives) do
                if not copyable(L_, alternative) then return false end
            end
            return true
        end
        return type_:copyable()
    end

    -- The type of a name's SLOT in a packet -- the question `residual_type`, `unpack` and
    -- `build_construct` all ask. It is NOT `belt_type_of`, which answers what reading the place GIVES:
    -- a celled capture's slot holds the owner's ADDRESS (§3.2's one indirection), so the slot is a
    -- cell while the content is a value, and one answer cannot be both.
    local capture_is_celled

    -- The type of a name's SLOT in a packet -- the question `residual_type`, `unpack` and
    -- `build_construct` all ask. It is NOT `belt_type_of`, which answers what reading the place GIVES:
    -- a CELLED binding's slot holds its ADDRESS (§3.2's one indirection), so the slot is a cell while
    -- the content is a value, and one answer cannot be both. `is_cell` is the whole rule -- captures,
    -- `mut`, and interior mutability -- and it is the same question `materialize` asks before it
    -- allocates, so a slot and its value cannot disagree about which of the two it is (§S84).
    field_type_of = function(L_, id)
        local content = belt_type_of(L_, id)
        if not content then return nil end
        if is_cell(L_, id) then return B.Cell(content) end
        return content
    end

    capture_is_celled = function(L_, capture)
        if capture.mode == Semantic.Mut then return true end
        local inner = L_.definitions[capture.binder]
        local outer = inner and inner.declaration.value.definition
        local declaration = outer and L_.declarations[outer]
        -- A WORD's value is its PACKET (§2.2), so §3.2's cheap row asks whether every member of that
        -- packet is Copy -- and an EMPTY packet is Copy, which is the case of an extern or a pure
        -- word: there is nothing to own, so one indirection would buy nothing.
        if declaration and Judge.Word:isclassof(declaration) then
            return not word_value_is_copy(L_, declaration.word, 0)
        end
        local interface = L_.types[capture.binder]
        return interface ~= nil and not copyable(L_, interface.result)
    end

    -- A binding is a CELL when it is declared `mut`. §3.4 makes such a binding a writable
    -- destination, and a destination is a location rather than a name for a value; §3.2's cell is
    -- that location. Because the cell is a *value* whose identity is fixed at its declaration,
    -- assignment never forces a phi at a join -- the cell is the same on every path and only its
    -- contents change. That is the whole reason cells are the representation for assignment.
    is_cell = function(L_, id)
        local declaration = L_.declarations[id]
        if declaration == nil or not Judge.Value:isclassof(declaration) then return false end
        if declaration.mutable then return true end
        -- §3.7: a `mut` MEMBER is interior mutability -- the value is writable through the name
        -- whatever the binding's own mutability says -- so the binding is a cell for exactly the
        -- reason a `mut` binding is: writing through a projected place needs the storage addressable.
        -- Derived from the type (§S71), and asked of the INTERFACE because a binding need not carry an
        -- annotation -- `let r = { let x mut = 1 }` has no declared type to read. What made this
        -- collide before was §3.2's conflict, which is conditional and was being applied
        -- unconditionally; a non-Copy record in a cell can now be MOVED, which is what lets it be
        -- exported and read by its owner rather than copied.
        if L_.types[id] ~= nil and L_.types[id].result:interior_mutability() then return true end
        -- §3.2: and a binding somebody CAPTURES is address-taken, because the capture is a pointer to
        -- its storage rather than a copy of it. This is the reason §S71's condition had none: "moving
        -- the owner while a view is live" was satisfiable only in the vacuous case, because no view
        -- existed anywhere for a `mut` binding to conflict with.
        local capture = L_.capture_of_binder[id] or L_.capture_of_owner[id]
        return capture ~= nil and capture_is_celled(L_, capture)
    end

    local function take_place(L_, C, p, span)
        -- §3.2's conflict is CONDITIONAL: "moving ... the owner WHILE A VIEW IS LIVE is a conflict."
        -- A view is a pointer into the storage, and this phase has no pointers that outlive an
        -- expression -- the field addresses `FieldAddress` builds do not, and captures are not built
        -- at all -- so the condition is not met and a cell can be moved out of. Equating "celled"
        -- with "viewed" was the condition DROPPED, and it made every `mut` binding immovable, which
        -- is what made §3.7's interior mutability collide with moves, reads and export (§S70).
        local diagnostic = check_place(C, p.root, p.path, span, false)
        if diagnostic then return nil, diagnostic end
        -- What is handed over is what the place HOLDS, and for a cell that is its content: a cell's
        -- value is its address (§S32), so the storage is not the value.
        local value = place_value(C, p)
        if copyable(L_, p.type) then return value end
        -- §3.2's condition, now REAL: "moving ... the owner WHILE A VIEW IS LIVE is a conflict", and a
        -- **celled** capture is exactly that view -- a pointer into this storage, alive in another
        -- word's frame -- while a copied one is a copy and conflicts with nothing. The check belongs
        -- HERE and not earlier, because a Copy read is not a move at all: `c = c + 1` reads the old
        -- value to destroy it, and refusing that would call a correct program wrong. §S71 recorded
        -- this check as correct and VACUOUS, and said captures were the piece that would give it
        -- meaning; this is that piece arriving.
        -- The question is about the OWNER's storage, so a move written THROUGH a capture (`move c`
        -- inside a word that captures `c`) asks about the binding the capture is a second name for and
        -- not about the capture's own binder -- otherwise the rule would depend on which word happened
        -- to be asking, which is exactly the kind of accident a rule must not have.
        local owner = p.root
        local through = L_.capture_of_binder[owner]
        if through then owner = L_.definitions[owner].declaration.value.definition end
        local view = L_.capture_of_owner[owner]
        if view and capture_is_celled(L_, view) then
            return nil, Report.reject(Report.ConflictingBorrow, span)
        end
        ordered(C, B.Move(ref(C, C.state.effect), ref(C, value)), nil)
        place(C, p.root).moved[p.path] = true
        return value
    end

    -- A name is the root place: everything lives in a definition, and the empty path is it.
    local function take(L_, C, id, span)
        local value = C.state.values[id]
        if not value then
            local lowered, diagnostic = materialize(L_, C, id, span)
            if not lowered then return nil, diagnostic end
            value = lowered
        end
        -- The place carries whether it is a CELL, because that is what decides if it can be moved
        -- out of at all (§3.2) and whether a read loads it. A place record that omitted it would
        -- silently treat a cell as an ordinary value.
        local cell = is_cell(L_, id)
        return take_place(L_, C, { value = value, path = '', type = L_.types[id].result, root = id,
            cell = cell, content = cell and belt_type_of(L_, id) or nil }, span)
    end

    -- Read a place as a value: the path check, then §1.4's rule that an existing non-copyable
    -- place must be moved rather than read -- a read is a borrow, and a borrow is not a value.
    -- §S69: a place is a LOCATION and a value is what reading it gives. This is the ONE place that
    -- turns one into the other, so a read and a move cannot disagree about what a place holds -- which
    -- they did the moment `lower_place` stopped building a value for a place that has an address.
    place_value = function(C, p)
        if p.cell and p.path == '' then
            return ordered(C, B.Load(ref(C, C.state.effect), ref(C, p.value)), p.content)
        end
        if p.address then
            local field_address = pure(C, B.FieldAddress(ref(C, p.address), p.offset),
                B.Cell(rep(L_, p.type)))
            return ordered(C, B.Load(ref(C, C.state.effect), ref(C, field_address)), rep(L_, p.type))
        end
        return p.value
    end

    local function read_place(L_, C, p, span)
        -- §1.4 decided what a read COSTS, and a cell is the one place it is not a copy: a cell is
        -- STORAGE, so reading it is a load. A load of something that cannot be copied would hand
        -- out a second owner of the same value -- so a non-Copy binding that is `mut` is
        -- unreadable: it cannot be copied, and §3.2 forbids moving out of a live cell, which is the
        -- same fact `take_place` states from the other side (`ConflictingBorrow`).
        local diagnostic = check_place(C, p.root, p.path, span, false)
        if diagnostic then return nil, diagnostic end
        -- §1.4: a read of a non-Copy place is not a copy, and a cell read is a load -- so a load of
        -- something that cannot be copied would hand out a second owner. The checks come first, so a
        -- refused read builds nothing at all.
        if not copyable(L_, p.type) then return nil, Report.reject(Report.NeedsMove, span) end
        return place_value(C, p)
    end

    -- Walk a place: the aggregate it lives in, the path to it, and its semantic type. The path is
    -- what partial initialization is keyed by, so it is built as the place is walked.
    lower_place = function(L_, C, initializer)
        if Judge.Reference:isclassof(initializer) then
            local value = C.state.values[initializer.definition]
            if not value then
                local lowered, diagnostic = materialize(L_, C, initializer.definition, initializer.span)
                if not lowered then return nil, diagnostic end
                value = lowered
            end
            local cell = is_cell(L_, initializer.definition)
            return { value = value, path = '', type = L_.types[initializer.definition].result,
                     root = initializer.definition, cell = cell,
                     content = cell and belt_type_of(L_, initializer.definition) or nil }
        end
        if Judge.Project:isclassof(initializer) or Judge.Index:isclassof(initializer) then
            local base, diagnostic = lower_place(L_, C, initializer.base)
            if not base then return nil, diagnostic end
            diagnostic = check_place(C, base.root, base.path, initializer.span, true)
            if diagnostic then return nil, diagnostic end
            -- A projection is a RECORD's field read and nothing else. A sum has no members: its
            -- payload is reached by the arm that MATCHED it (§S59), which `Contract` enforces
            -- before this runs -- so there is no fallible read to make safe here.
            local offset, field
            if Judge.Project:isclassof(initializer) then
                for index, candidate in ipairs(Semantic.Aggregate:isclassof(base.type)
                        and base.type.fields or {}) do
                    if candidate.name == initializer.name then offset, field = index - 1, candidate end
                end
                if not offset then return nil, Report.reject(Report.UnknownName, initializer.span) end
            else
                offset = initializer.offset
                field = Semantic.Aggregate:isclassof(base.type) and base.type.fields[offset + 1]
                if not field then return nil, Report.reject(Report.IndexOutOfRange, initializer.span) end
            end
            -- A projection through a CELL loads first: the cell is the record's storage, so the
            -- record the field is read from is its contents. The result is an ordinary value, so
            -- the projected place is not itself a cell -- which is why a field of a `mut` binding
            -- cannot be moved out of while the cell is live (§3.2).
            -- §S69: reading a MEMBER is a different question from reading the RECORD. When the base
            -- lives in storage -- a cell, or a chain of them -- the field is read through the
            -- STORAGE: its address, then a `Load`. The old shape loaded the whole record into a
            -- temporary first, and that is a copy of an owning value whenever the record is not
            -- `Copy` -- which a record with a `mut` member is not (§2.5), so the very case §3.7 is
            -- about was the one that could not be read.
            --
            -- §S68: an address CHAINS. A projection's address is the address of the record that
            -- CONTAINS its field -- exactly what `StoreField` takes, and it prints
            -- `(*addr).field = v` -- so one level is the base's own storage and a deeper one is the
            -- field's address taken through it.
            local address = base.value
            if not base.cell then
                if base.address then
                    address = pure(C, B.FieldAddress(ref(C, base.address), base.offset),
                        B.Cell(rep(L_, base.type)))
                else
                    address = nil
                end
            end
            -- §S69: a place is a LOCATION and a value is what reading it gives, so this builds a
            -- value only for the path that has no address at all -- a field of a VALUE -- where it
            -- is read off the value itself and costs no copy. Where there IS an address the value
            -- belongs to `read_place`, which also means a store destination never builds one: that
            -- is what removed a whole-record copy from every projected store.
            local value
            if not address then
                value = pure(C, B.LoadField(ref(C, base.value), offset), rep(L_, field.type))
            end
            local path = base.path == '' and tostring(offset) or (base.path .. '.' .. offset)
            return { value = value, path = path, type = field.type, root = base.root,
                     offset = offset, cell = false, depth = (base.depth or 0) + 1,
                     -- The CELL to store through, when there is one. A read needs the loaded
                     -- record; a write needs the storage. They are different questions and the
                     -- place carries both, so `r.x = v` has somewhere to put the write.
                     address = address }
        end
        if Judge.Element:isclassof(initializer) then
            -- A runtime index is not a PLACE: a place is one address and the index decides WHICH address
            -- at run time. `lower_element_store` answers a destination and `lower_element` a value, so
            -- reaching here means one of them missed a case -- the compiler disagreeing with itself.
            return nil, Report.bug(Report.NoLowering('element place'), initializer.span)
        end
        return nil, Report.bug(Report.NoLowering('place'), initializer.span)
    end

    -- §2.6: "a word's fields come from the namespace". This is the ONE place a capture's value is
    -- computed, and it is computed in the ENCLOSING instance -- where the captured binding is either
    -- that instance's own storage or one of its OWN captures, so a capture of a capture chains with
    -- no new vocabulary. A celled capture passes the owner's ADDRESS, which is why one indirection is
    -- enough and why nothing is copied: the capture and the owner are the same cell.
    capture_arguments = function(L_, C, template)
        local values = L()
        for _, capture in ipairs(template.captures or {}) do
            local definition = L_.definitions[capture.binder]
            local outer = definition.declaration.value.definition
            -- If THIS instance already holds the binding -- because it is itself a word that captures
            -- it -- then that IS the value. §3.2's one indirection is the OWNER's storage, so a
            -- recursive or nested construction hands on what it was given instead of rebuilding it,
            -- which is exactly what stopped `f`'s recursive call from constructing `made` again.
            local source
            for id in pairs(C.state.values) do
                local held = L_.capture_of_binder[id]
                if held and L_.definitions[id].declaration.value.definition == outer then
                    source = id
                    break
                end
            end
            local outer, diagnostic
            if source then
                outer, diagnostic = lower_place(L_, C, Judge.Reference(source, definition.span))
            else
                outer, diagnostic = lower_place(L_, C, definition.declaration.value)
            end
            if not outer then return nil, diagnostic end
            -- A celled capture passes the owner's ADDRESS -- a cell's value IS its address -- and a
            -- copied one passes what reading the place gives. That single branch is §3.2's whole table.
            -- A `Belt.Ref`, like every other argument list: the caller's operand convention is the
            -- belt's, and the numbering rule is that every operand's ref is computed after all of them
            -- are emitted -- which is why the values are collected here and referred to at the call.
            local value = capture_is_celled(L_, capture) and outer.value or place_value(C, outer)
            values:insert(ref(C, value))
        end
        return values
    end

    -- §3.6's borrow, as opposed to §1.4's move: the place must be initialized and readable, but a
    -- non-Copy value is FINE here -- that is the whole point of viewing one. `read_place` refuses a
    -- non-Copy read because a read of a place is a value and a borrow is not; a borrow is exactly
    -- what a borrowing stage wants.
    local function lower_borrow(L_, C, initializer)
        local p, diagnostic = lower_place(L_, C, initializer)
        if not p then return nil, diagnostic end
        diagnostic = check_place(C, p.root, p.path, initializer.span, false)
        if diagnostic then return nil, diagnostic end
        if p.cell and p.path == '' then
            return ordered(C, B.Load(ref(C, C.state.effect), ref(C, p.value)), p.content)
        end
        return p.value
    end

    -- §1.5's operators, as DATA -- and one table per question, because the division is not the same
    -- for operands as it is for results. A comparison takes two Ints and produces a Bool, while
    -- `and`, `or` and `not` are Bool to Bool because they are about truth and not arithmetic. The
    -- check in §12.2 and these two rules must state the same thing, and the folding rule in `Known`
    -- must not disagree with either: `not`'s operand was the one place they did, because it was
    -- being lowered with the Int that arithmetic asks for.
    local COMPARISON = {
        [Semantic.Equal] = true, [Semantic.NotEqual] = true, [Semantic.Less] = true,
        [Semantic.LessEqual] = true, [Semantic.Greater] = true, [Semantic.GreaterEqual] = true,
    }
    local TRUTH = { [Semantic.Not] = true, [Semantic.And] = true, [Semantic.Or] = true }

    local function operand_type_of(operator)
        return TRUTH[operator] and B.Bool or B.Int
    end
    local function result_type_of(operator, left)
        return (TRUTH[operator] or COMPARISON[operator]) and B.Bool or left
    end

    -- §S61: a term's type is not a question this layer ASKS, it is what lowering the term
    -- PRODUCES -- §11.7's `Instruction` already carries its results -- so `type_` below means one
    -- thing only: the type the value must BECOME. Every branch produces a value that says its own
    -- type, and the injection is decided by reading that value instead of re-deriving it.
    -- §3.5/§S48's injection: WHICH alternative the value already inhabits. The question is SEMANTIC and
    -- it has to be asked semantically, because the belt representation of two alternatives can be ONE
    -- type -- two word values with empty packets are both `uint8_t` -- and then `Belt.Sum:alternative`
    -- finds two matches and the first was taken. That is a WRONG PROGRAM rather than a wrong message,
    -- and at a borrowed stage it was no injection at all, which `cc` reported as a type error.
    --
    -- A word value's identity is nominal in `(template, prefix)` and `Lower` derives it from the
    -- DECLARATION (`word_of`), which is the same answer that selects a callee (§S99); every other
    -- type's equality is mirrored by the belt (§S49), so the representation is asked only after the
    -- declaration has been. When neither can say, that is a disagreement with `Contract` -- which
    -- accepted the program, so it decided an alternative -- and it is reported rather than skipped.
    local function injection_tag(L_, initializer, value, semantic, type_)
        if semantic and Semantic.Sum:isclassof(semantic) then
            local template, prefix = word_of(L_, initializer)
            if template then
                local index, count = semantic:alternative(Semantic.Word(template, prefix))
                if index and count == 1 then return index end
            end
        end
        local index, count = type_:alternative(value.type)
        if index and count == 1 then return index end
        return nil
    end

    -- §3.5's construction, in ONE place: a site that expects a sum and a value that is not one.
    local function inject(L_, C, type_, semantic, value, initializer)
        if not type_ or not B.Sum:isclassof(type_) then return value end
        if B.Sum:isclassof(value.type) then return value end
        local tag = injection_tag(L_, initializer, value, semantic, type_)
        if not tag then
            return nil, Report.bug(Report.NoLowering('injection'), initializer.span)
        end
        return pure(C, B.InjectSum(tag, ref(C, value)), type_)
    end

    local function lower_initializer(L_, C, initializer, type_, semantic)
        -- §3.5's construction, and the reason it lives HERE: every construct that expects a type
        -- goes through this function -- a binding, a stage argument, a return, a record member -- so
        -- injection is one rule in one place rather than a case at each site.
        --
        -- §S61: the value is lowered FIRST and its type is read back off the value, so which
        -- alternative it inhabits is answered by the belt rather than derived from the term. The
        -- SEMANTIC type travels beside the belt one because the belt cannot always answer -- see
        -- `injection_tag` -- and it is the DECLARATION that is asked, never the term.
        if type_ and B.Sum:isclassof(type_) then
            local value, diagnostic = lower_initializer(L_, C, initializer, nil)
            if not value then return nil, diagnostic end
            return inject(L_, C, type_, semantic, value, initializer)
        end
        if Judge.Literal:isclassof(initializer) then
            local expr = initializer.value
            -- §S61: a literal's type is its own form, so each of these names the type it
            -- produces rather than being told it -- and a `Text` literal is a `Text`, because a
            -- conversion to `CString` is a dictionary word and never a silent retype (§S42).
            if Syntax.Unit:isclassof(expr) then
                return pure(C, B.UnitLiteral, B.Unit)
            end
            if Syntax.Integer:isclassof(expr) then
                return pure(C, B.IntegerLiteral(expr.spelling), B.Int)
            end
            if Syntax.Float:isclassof(expr) then
                return pure(C, B.FloatLiteral(expr.spelling), B.Float)
            end
            if Syntax.Boolean:isclassof(expr) then
                return pure(C, B.BooleanLiteral(expr.value), B.Bool)
            end
            if Syntax.Text:isclassof(expr) then
                return pure(C, B.TextLiteral(expr.value), B.Text)
            end
            return nil, Report.bug(Report.NoLowering('literal'), expr.span)
        end

        if Judge.Aggregate:isclassof(initializer) then
            -- §3.3: members initialize top to bottom, so each is lowered in order and the record
            -- is a `Construct` of them. A member that is a definition materializes on demand.
            local values = L()
            for i, member in ipairs(initializer.members) do
                -- The record OWNS its members. A member that names a definition is taken from it
                -- -- which for a non-Copy member is a move -- and anything else is an rvalue
                -- already owned. Reading a named member instead would be a borrow, and a borrow
                -- is not something a record can hold (§1.4).
                local value, diagnostic
                if Judge.Reference:isclassof(member.value) then
                    value, diagnostic = take(L_, C, member.value.definition, member.value.span)
                else
                    -- §S61: no type is handed in. The member's own type is what lowering it
                    -- PRODUCES, and passing an expected type here was the last place this layer
                    -- asked a question it can answer by producing one -- it also CRASHED when the
                    -- aggregate was an injection payload, because the expected type is the sum and
                    -- a sum has no `fields` to read a member's type from.
                    value, diagnostic = lower_initializer(L_, C, member.value)
                end
                if not value then return nil, diagnostic end
                values:insert(value)
            end
            -- A ref is relative to the CONSUMER's position, so the refs are computed only once
            -- every operand has been emitted -- the same rule `construct_record` obeys, and the
            -- third time it decides whether the output is right.
            local refs = L()
            for _, value in ipairs(values) do refs:insert(ref(C, value)) end
            -- §S61: the record's type is built from the types the members just PRODUCED -- the
            -- same construction `Contract.type_of` performs on the semantic side, because §10 keeps
            -- a vocabulary per layer and neither has to ask the other for this one.
            local fields = L()
            for i, value in ipairs(values) do
                fields:insert(B.Field(initializer.members[i].name, value.type,
                    initializer.members[i].mutable))
            end
            return pure(C, B.Construct(refs), B.Aggregate(fields))
        end

        -- §3.4's operators. The pure ones are a `Pure.Binary`, which is what lets `Known` fold
        -- them; `/` and `%` are `CheckedBinary` because they TRAP on a zero divisor and a trap
        -- is observable, so the operation is ordered and carries the effect.
        if Judge.Unary:isclassof(initializer) then
            local operand, diagnostic = lower_initializer(L_, C, initializer.operand,
                operand_type_of(initializer.operator))
            if not operand then return nil, diagnostic end
            return pure(C, B.Unary(initializer.operator, ref(C, operand)),
                result_type_of(initializer.operator, operand.type))
        end
        if Judge.Binary:isclassof(initializer) then
            -- §3.4 has `and`/`or` short-circuit, and that is a CONTROL decision rather than an
            -- arithmetic one: the right operand must not run when the left decides.
            if initializer.operator == Semantic.And or initializer.operator == Semantic.Or then
                return lower_short_circuit(L_, C, initializer, B.Bool)
            end
            local operand_type = operand_type_of(initializer.operator)
            local left, diagnostic = lower_initializer(L_, C, initializer.left, operand_type)
            if not left then return nil, diagnostic end
            local right
            right, diagnostic = lower_initializer(L_, C, initializer.right, operand_type)
            if not right then return nil, diagnostic end
            -- Both refs are computed only NOW, because a ref is relative to the CONSUMER and the
            -- consumer is this instruction. Computing one inside the loop that lowers the operands
            -- makes it relative to wherever that loop had reached -- the second corollary.
            if initializer.operator == Semantic.Divide or initializer.operator == Semantic.Remainder then
                return ordered(C, B.CheckedBinary(initializer.operator, ref(C, C.state.effect),
                    ref(C, left), ref(C, right)), B.Int)
            end
            return pure(C, B.Binary(initializer.operator, ref(C, left), ref(C, right)),
                result_type_of(initializer.operator, left.type))
        end

        -- §1.4: `move place` transfers ownership. The place is a name in this slice; a member or
        -- index place arrives with postfix on the left of a place.
        if Judge.Move:isclassof(initializer) then
            local p, diagnostic = lower_place(L_, C, initializer.place)
            if not p then return nil, diagnostic end
            return take_place(L_, C, p, initializer.span)
        end

        -- A projection or a constant index is a place, so reading it is the same question a name
        -- asks: is it initialized, and is it Copy.
        -- §12.1's runtime index, and it is a VALUE and not a place: the dispatch reads one member and
        -- hands it over, so `a[i]` as a destination is a different rule (see the gap below).
        if Judge.Element:isclassof(initializer) then
            return lower_element(L_, C, initializer)
        end

        if Judge.Project:isclassof(initializer) or Judge.Index:isclassof(initializer) then
            local p, diagnostic = lower_place(L_, C, initializer)
            if not p then return nil, diagnostic end
            return read_place(L_, C, p, initializer.span)
        end


        -- §2.6: a name is visible through the namespace, so a Reference to a WORD denotes the word
        -- VALUE `R(t,0)` and not its result -- which is why naming one has to CONSTRUCT it. This
        -- belongs here rather than in `lower_module`, because an imported file's namespace is an
        -- ordinary value that Resolve builds, and its word members need exactly the same treatment.
        if Judge.Reference:isclassof(initializer)
            and Judge.Word:isclassof(L_.declarations[initializer.definition]) then
            local template = initializer.definition
            local word = L_.declarations[template].word
            local value, diagnostic = base_of(L_, C, template, word, initializer)
            if not value then return nil, diagnostic end
            return value
        end

        if Judge.Reference:isclassof(initializer) then
            local p, diagnostic = lower_place(L_, C, initializer)
            if not p then return nil, diagnostic end
            return read_place(L_, C, p, initializer.span)
        end

        if Judge.Apply:isclassof(initializer) then
            local template, prefix = word_of(L_, initializer.callee)
            if not template then
                return nil, Report.reject(Report.NotExecutable, initializer.span)
            end
            local word = L_.declarations[template].word
            local stages = stages_of(word)
            local stage = stages[prefix + 1]
            if not stage then
                -- `word_of` says WHICH word and at WHICH prefix, so a prefix with no stage means an
                -- application of something that is not a word of this callee -- §1.2's saturation
                -- rule, reported rather than indexed.
                return nil, Report.reject(Report.Oversaturated, initializer.span)
            end
            local argument_type = rep(L_, stage.type)
            if not argument_type then
                return nil, Report.bug(Report.NoLowering('representation'), initializer.span)
            end
            -- §3.6's table, and §11.3's capability: a `Read` or `Mut` stage VIEWS its argument and
            -- an `Own` one takes it. That is the difference between a borrow and a move, and it is
            -- declared rather than inferred -- so the borrower writes `f x` and the owner writes
            -- `f (move x)`, and `Lower` must not demand the second from the first.
            --
            -- A borrow is not a belt VALUE and has no representation (§3.6: "a reference is never a
            -- value, its representation is unobservable"). So it lowers to the value itself, and what
            -- makes it a borrow is precisely that the source's place is NOT marked moved: the owner
            -- still owns it. Whether the host retains it is the host's contract, and §3.6 says the
            -- declaration, not the implementation, is what the compiler holds a host to.
            local capability = stage.capability
            local borrowed = capability == Semantic.Read or capability == Semantic.Mut
            local argument, diagnostic
            if borrowed and Judge.Reference:isclassof(initializer.argument) then
                argument, diagnostic = lower_borrow(L_, C, initializer.argument)
                -- §3.5: the callee's stage has the SUM's type, so the caller BUILDS the sum even when
                -- it borrows -- the tag is part of what the callee reads, and a borrow says only that
                -- the caller keeps ownership. Passing the value itself was the C type error, and the
                -- only reason it survived is that nothing had built a sum from a borrowed place.
                if argument then
                    argument, diagnostic = inject(L_, C, argument_type, stage.type, argument,
                        initializer.argument)
                    if not argument then return nil, diagnostic end
                end
            else
                argument, diagnostic = lower_initializer(L_, C, initializer.argument, argument_type,
                    stage.type)
            end
            if not argument then return nil, diagnostic end

            -- The roots of this application: whatever the value at `prefix` is, the step that
            -- reaches `prefix + 1`, and -- only when that step saturates the chain -- the terminal.
            --
            -- The base is the CALLEE when the callee is itself an application: `f a b` has prefix 1
            -- at the outer step, so its base is `f a` and not a fresh `construct`. Calling
            -- `construct` unconditionally hands `advance_1` a `R(t,0)` where it wants `R(t,1)` --
            -- which is a type error in the emitted C and, before that, a second construction of a
            -- chain that had already been built.
            local base
            if prefix == 0 then
                local constructed, diagnostic = base_of(L_, C, template, word, initializer.callee)
                if not constructed then return nil, diagnostic end
                base = constructed
            else
                base, diagnostic = lower_initializer(L_, C, initializer.callee,
                    residual_type(L_, word, prefix))
                if not base then return nil, diagnostic end
            end
            local advance = demand(L_, 'advance:' .. template .. ':' .. (prefix + 1), function(M, id)
                return build_advance(M, template, prefix + 1, id)
            end)
            if not advance then return nil, L_.diagnostic end

            local reached = ordered(C, B.CallFunction(advance, ref(C, C.state.effect),
                L{ref(C, base), ref(C, argument)}), residual_type(L_, word, prefix + 1))
            if prefix + 1 < #stages then return reached end

            local run = demand(L_, 'run:' .. template, function(M, id)
                return build_run(M, template, id)
            end)
            if not run then return nil, L_.diagnostic end
            return ordered(C, B.CallFunction(run, ref(C, C.state.effect), L{ref(C, reached)}),
                rep(L_, L_.types[template].result))
        end

        -- §1.2: `f(a, b)` and `f with a with b` lower to the SAME operations in the same order -- the
        -- only difference is the residual's lifetime, which the belt does not yet distinguish -- so the
        -- arguments are folded into `Apply`s and the existing path does the work. `f()` is the one
        -- case `with` cannot spell: it supplies no stage, so it runs the terminal directly
        -- and is legal only where the word has no stages left to supply.
        if Judge.Invoke:isclassof(initializer) then
            if #initializer.arguments == 0 then
                local template, prefix = word_of(L_, initializer.callee)
                if not template then
                    return nil, Report.reject(Report.NotExecutable, initializer.span)
                end
                local word = L_.declarations[template].word
                if prefix ~= 0 or #stages_of(word) ~= 0 then
                    return nil, Report.reject(Report.Undersaturated, initializer.span)
                end
                local base, diagnostic = base_of(L_, C, template, word, initializer.callee)
                if not base then return nil, diagnostic end
                local run = demand(L_, 'run:' .. template, function(M, id)
                    return build_run(M, template, id)
                end)
                if not run then return nil, L_.diagnostic end
                return ordered(C, B.CallFunction(run, ref(C, C.state.effect), L{ref(C, base)}),
                    rep(L_, L_.types[template].result))
            end
            local folded = initializer.callee
            for _, argument in ipairs(initializer.arguments) do
                folded = Judge.Apply(folded, argument, initializer.span)
            end
            return lower_initializer(L_, C, folded, type_, semantic)
        end

        local class = getmetatable(initializer)
        return nil, Report.bug(Report.NoLowering('initializer ' .. tostring(class and class.kind)),
            L_.definitions[1].span)
    end


    -- A `do` body: statements in order, and its exit is its `return`. §12.3: "Bare `return` and
    -- falling through the end of a runtime body both return Unit" -- so a body that never returns
    -- is an exit returning Unit, and whether that matches the declared result is Contract's check.
    local function copy(t)
        local out = {}
        for key, value in pairs(t) do out[key] = value end
        return out
    end

    -- A place's state is copied per arm: a move in one arm must not be visible in the other, or
    -- the agreement check at the join could not see the very difference it exists to reject.
    local function copy_places(places)
        local out = {}
        for id, state in pairs(places) do out[id] = { moved = copy(state.moved) } end
        return out
    end

    -- The live values of a region: what the sequential scan has bound and not yet left scope.
    --
    -- This is §3.3's transport list, and it is deliberately NOT a liveness analysis. The region's
    -- environment already IS the live set -- a binding enters it when it is bound and leaves it when
    -- its scope ends -- so the scan that checks ownership is the same scan that knows what is live.
    -- Order is by definition id, which is what makes an edge's arguments and its target's
    -- parameters agree without either side sorting anything.
    live = function(C)
        local ids = {}
        for id in pairs(C.state.values) do ids[#ids + 1] = id end
        table.sort(ids)
        return ids
    end

    -- The arguments of an edge into a block whose parameters are `[Effect] + carried`, in the SAME
    -- order those parameters were created. One owner, because an edge whose arguments and whose
    -- target's parameters disagree is a read of an uninitialized C variable -- a wrong program the
    -- belt's own numbering rule warns about and that no later phase can detect.
    arguments_of = function(region, carried)
        local arguments = L{ref(region, region.state.effect)}
        for _, id in ipairs(carried) do
            arguments:insert(ref(region, region.state.values[id]))
        end
        return arguments
    end

    -- One successor region of the control the parent is building: its own block, its own region,
    -- and the interface that carries the parent's live values in. Returns the region and the
    -- arguments its incoming edge must pass.
    --
    -- `target` is where the region's own fallthrough goes -- a join for a split, the header for a
    -- loop -- so `arm` is the one place that knows how control continues.
    --
    -- The interface is DEGENERATE, and that is the design's own claim rather than a shortcut.
    -- §3.3 makes ownership state path-independent, so no place ever crosses as a parameter; and
    -- with no assignment (C8), no VALUE differs across the arms either. Every edge therefore
    -- passes on exactly what it received: this is an identity, not a phi, and the phi arrives with
    -- assignment. What remains is transport -- a value built before the split lives in the
    -- parent's block, and a block names only its own positions, so it must be named here.
    local function arm(L_, C, block, statements, result_type, span, target, carried, binds)
        local child = C:region()
        child.state.block = block
        child.state.locations = {}
        child.state.places = copy_places(C.state.places)
        -- Shared, not copied: a `break` inside a nested `if` inside this body belongs to THIS loop.
        child.state.loop = C.state.loop
        child.state.effect = parameter(child, B.Effect, Semantic.Read)
        child.state.values = {}
        for _, id in ipairs(carried) do
            child.state.values[id] = parameter(child, C.state.values[id].type, Semantic.Read)
        end

        -- §S59: an arm that matched by SHAPE binds what it matched. Field `1+K` of a sum is
        -- alternative `K`'s payload -- a KNOWN offset, so this is a plain `LoadField`: pure, of
        -- known type, and unable to fail, because the arm's own test established that tag is K.
        if binds then
            local payload = pure(child, B.LoadField(
                ref(child, child.state.values[binds.subject]), 1 + binds.tag), binds.type)
            -- §3.5/§S65: taking a NON-COPY payload consumes the WHOLE subject, because a sum has no
            -- partial state to be in -- its tag would otherwise name a value that is no longer
            -- there. The path that is marked is the ROOT (`''`), so every alternative reads as gone
            -- and the subject is never destroyed half-taken.
            --
            --     A COPY payload is a copy (§1.4) and consumes nothing, so the arms of a sum that
            --     mixes the two disagree about the subject's state. That is §3.3's
            --     `OwnershipDiverges` doing its job, and it is a consequence of §3.5 rather than
            --     a limitation added here.
            if not binds.copyable then
                ordered(child, B.Move(ref(child, child.state.effect), ref(child, payload)), nil)
                place(child, binds.subject).moved[''] = true
            end
            child.state.values[binds.id] = payload
        end

        local arguments = arguments_of(C, carried)
        local ok, diagnostic = lower_body(L_, child, statements, result_type, span, function(region)
            -- The region's OWN `let`s die with it, so only the carried values cross -- and they
            -- cross as the very parameters they arrived as. That is the identity phi.
            return B.Jump(B.Edge(target.id, arguments_of(region, carried)))
        end)
        if not ok then return nil, diagnostic end
        return child, arguments
    end

    -- Set equality for a place's holes. Ownership state is a SET of moved paths, and every place
    -- §3.3 talks about is compared this way: at a split, at a backedge, and at a `break`.
    local function same_holes(left, right)
        for key in pairs(left) do
            if right[key] == nil then return false end
        end
        for key in pairs(right) do
            if left[key] == nil then return false end
        end
        return true
    end

    local function holes(C, id)
        local place = C.state.places[id]
        return place and place.moved or {}
    end

    -- §3.3: at a join, every place that OUTLIVES it must agree on every incoming path.
    -- Divergence is a **Reject** -- not a guard, not a dynamic flag, not a fixpoint. That single
    -- rule is why ownership is a scan and not a pass, and it is the claim this design rests on.
    -- `C` is the region whose places are the ones that outlive the join.
    -- §3.3's rule is about "every place that OUTLIVES" the join, and a path that does not arrive at it
    -- imposes nothing -- an arm ending in `return` is the obvious case. What is NOT obvious, and what
    -- makes the conservative version the right one, is that **a path's state outlives the join whenever
    -- the PLACE outlives the path**: §S66's own test moves a FILE-level place inside a returning arm,
    -- and a place whose scope is the module outlives the arm, the switch and the function. So `agree`
    -- compares every path, and getting cleverer here needs scope information it does not have.
    local function agree(C, yes, no, span)
        -- With fewer than two arriving paths there is nothing to agree about: one path's state IS the
        -- join's state, and none leaves the parent's -- because nothing after the join observes it.
        local agreed = {}
        -- §S66: the ids are the UNION of what the three paths know about, not the parent's set.
        -- A place's entry is created when something first marks it, and the first marking usually
        -- happens INSIDE an arm -- so iterating the parent's table silently skipped exactly the
        -- place the two arms disagreed about, which made this check blind to the divergence it
        -- exists for. An id one path has and another does not is compared too, through `holes`:
        -- absent means `{}`, which is "not moved" and not "unknown".
        local ids = {}
        for id in pairs(yes.state.places) do ids[id] = true end
        for id in pairs(no.state.places) do ids[id] = true end
        for id in pairs(C.state.places) do ids[id] = true end
        for id in pairs(ids) do
            local left = holes(yes, id)
            if not same_holes(left, holes(no, id)) then
                return nil, Report.reject(Report.OwnershipDiverges, span)
            end
            agreed[id] = { moved = copy(left) }
        end
        return agreed
    end

    -- A split, and its join. The join block exists before either arm, because an `Edge` names its
    -- target by block id -- and its parameters are created after both arms, because what the arms
    -- must agree about is exactly what the join is allowed to keep.
    -- A DISPATCH over `count` alternatives on a value that is known only at run time: one test per
    -- alternative, in order, then a trap for a value that names none. §3.5's destructor chooses its arm
    -- by TAG and §12.1's runtime index chooses by OFFSET, and both are this shape -- a value compared
    -- against a constant -- so this is the one place that builds it.
    --
    -- All of the caller's values must already be NAMED, because §12.3 makes a block's parameters the
    -- values live at the split and an edge's arguments match them one for one. A caller that needs a
    -- value to come OUT of the dispatch uses a CELL, which is how this design carries a value across a
    -- join that differs per path (§11.7: its identity is fixed, only its contents differ, "and contents
    -- are memory, not an SSA name"); `build_arm(k)` emits into the arm for the k-th alternative.
    local function dispatch(L_, C, count, subject, reason, build_arm)
        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end
        local join, trap = new_block(C), new_block(C)
        local tests, arms = {}, {}
        for k = 1, count do
            tests[k] = new_block(C)
            arms[k] = new_block(C)
        end
        C.state.block.exit = B.Jump(B.Edge(tests[1].id, arguments_of(C, carried)))

        local function adopt(block)
            C.state.block = block
            C.state.effect = parameter(C, B.Effect, Semantic.Read)
            C.state.values = {}
            for _, id in ipairs(carried) do
                C.state.values[id] = parameter(C, types[id], Semantic.Read)
            end
        end

        for k = 1, count do
            adopt(tests[k])
            local literal = pure(C, B.IntegerLiteral(tostring(k - 1)), B.Int)
            local equal = pure(C, B.Binary(Semantic.Equal, ref(C, C.state.values[subject]),
                ref(C, literal)), B.Bool)
            local next_block = tests[k + 1] and tests[k + 1].id or trap.id
            tests[k].exit = B.Branch(ref(C, equal),
                B.Edge(arms[k].id, arguments_of(C, carried)),
                B.Edge(next_block, arguments_of(C, carried)))
        end

        for k = 1, count do
            adopt(arms[k])
            build_arm(k)
            arms[k].exit = B.Jump(B.Edge(join.id, arguments_of(C, carried)))
        end

        adopt(trap)
        trap.exit = B.Trap(ref(C, C.state.effect), reason)
        adopt(join)
        return true
    end

    -- §12.1's row, DERIVED: "is this step a constant or a runtime index?" An index whose value is not
    -- known until run time is a DISPATCH on it -- one test per member, in the order the members are
    -- written -- and each arm reads the CONSTANT offset it is about. That is the shape of §3.5's
    -- destructor (a dispatch on a tag) and it needs no new opcode.
    --
    -- **The value crosses the join in a CELL, because this design has no value phi.** §S35 says the value
    -- phi appears in exactly one place, `and`/`or`, and §11.7 says why the cell is the alternative: "a
    -- cell is a belt value whose identity is fixed before any control flow can reach it, so it crosses a
    -- join unchanged and only its contents differ per path -- and contents are memory, not an SSA name."
    -- Arm 0 stores nothing, because the cell is initialised with member 0, and an index that names no
    -- member TRAPS: a runtime index cannot be checked statically, and §1.5 already traps where C would be
    -- undefined (`/` by zero), so this is the same rule and not a new one.
    lower_element = function(L_, C, initializer)
        local record, diagnostic = lower_initializer(L_, C, initializer.base)
        if not record then return nil, diagnostic end
        local index, index_diagnostic = lower_initializer(L_, C, initializer.index, B.Int)
        if not index then return nil, index_diagnostic end
        local aggregate = record.type
        if not B.Aggregate:isclassof(aggregate) or #aggregate.fields == 0 then
            return nil, Report.bug(Report.NoLowering('element'), initializer.span)
        end
        local element_type = aggregate.fields[1].type
        local record_id = name_it(L_, C, record, aggregate)
        local index_id = name_it(L_, C, index, B.Int)
        local first = pure(C, B.LoadField(ref(C, C.state.values[record_id]), 0), element_type)
        local cell = ordered(C, B.Allocate(ref(C, C.state.effect), ref(C, first)),
            B.Cell(element_type))
        local cell_id = name_it(L_, C, cell, B.Cell(element_type))

        -- The index that names no member TRAPS, and that is what lets a cell stand in for the phi this
        -- design does not have: the trap EXITS, so every path that arrives at the join has the cell set.
        dispatch(L_, C, #aggregate.fields, index_id, 'index out of range', function(k)
            if k > 1 then
                local member = pure(C, B.LoadField(ref(C, C.state.values[record_id]), k - 1),
                    element_type)
                ordered(C, B.Store(ref(C, C.state.effect), ref(C, C.state.values[cell_id]),
                    ref(C, member)), nil)
            end
        end)
        return ordered(C, B.Load(ref(C, C.state.effect), ref(C, C.state.values[cell_id])), element_type)
    end

    -- §12.1's runtime index as a DESTINATION: the same dispatch, with a `StoreField` in each arm instead
    -- of a `LoadField`. It cannot be a PLACE -- a place is one address and the index decides WHICH
    -- address at run time -- so it is the one destination `lower_place` does not answer, and the address
    -- it writes through is the base record's, which §S68 says chains like any other.
    local function lower_element_store(L_, C, statement)
        local initializer = statement.place
        local target, diagnostic = lower_place(L_, C, initializer.base)
        if not target then return nil, diagnostic end
        local address = target.cell and target.value or target.address
        if not address then
            return nil, Report.bug(Report.UnaddressableDestination, statement.span)
        end
        local aggregate = target.type
        if not Semantic.Aggregate:isclassof(aggregate) or #aggregate.fields == 0 then
            return nil, Report.bug(Report.NoLowering('element store'), statement.span)
        end
        local element_type = rep(L_, aggregate.fields[1].type)
        local index, index_diagnostic = lower_initializer(L_, C, initializer.index, B.Int)
        if not index then return nil, index_diagnostic end
        local value, value_diagnostic = lower_initializer(L_, C, statement.value, element_type)
        if not value then return nil, value_diagnostic end

        local address_id = name_it(L_, C, address, address.type)
        local index_id = name_it(L_, C, index, B.Int)
        local value_id = name_it(L_, C, value, element_type)
        dispatch(L_, C, #aggregate.fields, index_id, 'index out of range', function(k)
            ordered(C, B.StoreField(ref(C, C.state.values[address_id]), k - 1,
                ref(C, C.state.values[value_id])), nil)
        end)
        return true
    end

    -- §3.5: "destroying a sum needs a destructor chosen by its TAG". Every destructor before this one was
    -- straight-line; this one cannot be, because which alternative is live is not a fact about the sum's
    -- TYPE -- the tag says so, and the tag is a runtime value. So it is a chain of tests whose arms are
    -- blocks, and this is where §3.3's scope-exit destruction and §12.3's block graph meet.
    --
    -- Nothing else here is new. §3.5 puts the tag at field 0 and alternative K's payload at field 1+K --
    -- the numbers `InjectSum` writes and `lower_switch` compares -- so every read is a pure `LoadField`
    -- at a known offset, and the ops are the ones the graph already has.
    destroy_sum = function(L_, C, root, path, type_, value)
        local alternatives = {}
        for index, alternative in ipairs(type_.alternatives) do
            if destroys(L_, alternative) then alternatives[#alternatives + 1] = index end
        end
        if #alternatives == 0 then return end

        -- The value must be visible in every arm, and a `Ref` is relative to its CONSUMER, so it crosses
        -- the edges as an argument -- which needs a name (§12.3, and the same reason as §S34).
        local subject = name_it(L_, C, value, type_)
        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end

        local join = new_block(C)
        local tests, arms = {}, {}
        for position in ipairs(alternatives) do tests[position] = new_block(C) end
        for _, index in ipairs(alternatives) do arms[index] = new_block(C) end
        C.state.block.exit = B.Jump(B.Edge(tests[1].id, arguments_of(C, carried)))

        -- Adopt a block the chain entered: its parameters are `[Effect] + the live values`, in the order
        -- `arguments_of` wrote them -- the adoption `lower_if` performs at its join.
        local function adopt(block)
            C.state.block = block
            C.state.effect = parameter(C, B.Effect, Semantic.Read)
            C.state.values = {}
            for _, id in ipairs(carried) do
                C.state.values[id] = parameter(C, types[id], Semantic.Read)
            end
        end

        for position, index in ipairs(alternatives) do
            adopt(tests[position])
            local tag = pure(C, B.LoadField(ref(C, C.state.values[subject]), 0), B.Int)
            -- The tag is ZERO-based: `InjectSum` writes `index - 1` and `lower_switch` compares the same.
            local literal = pure(C, B.IntegerLiteral(tostring(index - 1)), B.Int)
            local equal = pure(C, B.Binary(Semantic.Equal, ref(C, tag), ref(C, literal)), B.Bool)
            -- The LAST test has nothing after it: the tag must name one of the alternatives, so its `no`
            -- edge goes straight to the join.
            local next_block = tests[position + 1] and tests[position + 1].id or join.id
            tests[position].exit = B.Branch(ref(C, equal),
                B.Edge(arms[index].id, arguments_of(C, carried)),
                B.Edge(next_block, arguments_of(C, carried)))
        end

        for _, index in ipairs(alternatives) do
            adopt(arms[index])
            local payload = pure(C, B.LoadField(ref(C, C.state.values[subject]), 1 + (index - 1)),
                rep(L_, type_.alternatives[index]))
            local inner = path == '' and tostring(index) or (path .. '.' .. index)
            destroy_value(L_, C, root, inner, type_.alternatives[index], payload)
            arms[index].exit = B.Jump(B.Edge(join.id, arguments_of(C, carried)))
        end

        -- Adopt the join, so whatever the caller destroys next lands after the dispatch on every path.
        -- The place state is NOT reset and nothing is agreed, because a destruction changes no place's
        -- state -- which is why this needs no `agree` where `lower_if` does.
        adopt(join)
    end

    lower_if = function(L_, C, statement, result_type)
        -- The statement carries its own span, so Lower is not told where the statement is.
        local span = statement.span
        local condition, diagnostic = lower_initializer(L_, C, statement.condition, B.Bool)
        if not condition then return nil, diagnostic end

        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end

        local join = new_block(C)
        -- The caller keeps the block it allocated. A region's `state.block` moves on as it builds
        -- nested control, so reading it back would wire the branch to wherever the arm ENDED --
        -- which is a wrong program that compiles and only shows up with nesting.
        local yes_block, no_block = new_block(C), new_block(C)
        local yes, yes_arguments = arm(L_, C, yes_block, statement.yes, result_type, span, join, carried)
        if not yes then return nil, yes_arguments end
        local no, no_arguments = arm(L_, C, no_block, statement.no, result_type, span, join, carried)
        if not no then return nil, no_arguments end
        if not no then return nil, no_arguments end

        local agreed, diverged = agree(C, yes, no, span)
        if not agreed then return nil, diverged end

        C.state.block.exit = B.Branch(ref(C, condition),
            B.Edge(yes_block.id, yes_arguments), B.Edge(no_block.id, no_arguments))

        -- Adopt the join. The arms' own bindings are gone, the ownership state is the agreed one,
        -- and each carried value is now the join's parameter -- the same value on every path,
        -- which is what "no phi yet" means precisely.
        C.state.block = join
        C.state.locations = {}
        C.state.places = agreed
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        C.state.values = {}
        for _, id in ipairs(carried) do
            C.state.values[id] = parameter(C, types[id], Semantic.Read)
        end
        return true
    end

    -- §3.3's uniformity with a loop: the backedge must agree with the header, and so must every
    -- `break` and every `continue` inside the body. This is a LOCAL check and NOT a fixed point --
    -- the header's state is the state on entry, which is already known -- and that is precisely
    -- why a loop needs no initialization analysis.
    --
    -- A `while` never terminates on its own, because the condition may be false first, so the
    -- exit block is always reachable: the loop joins the enclosing code rather than ending it.
    lower_while = function(L_, C, statement, result_type)
        local span = statement.span
        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end

        -- The header, entered from here and again from the backedge.
        local header = new_block(C)
        local exit = new_block(C)
        local enclosing = C.state.loop
        C.state.block.exit = B.Jump(B.Edge(header.id, arguments_of(C, carried)))

        local head = C:region()
        head.state.block = header
        head.state.locations = {}
        head.state.places = copy_places(C.state.places)
        head.state.effect = parameter(head, B.Effect, Semantic.Read)
        head.state.values = {}
        for _, id in ipairs(carried) do
            head.state.values[id] = parameter(head, types[id], Semantic.Read)
        end

        local condition, diagnostic = lower_initializer(L_, head, statement.condition, B.Bool)
        if not condition then return nil, diagnostic end

        -- The loop's own control state. `break` and `continue` are jumps into it, and each site
        -- records the ownership state it leaves in, so the agreement below covers all of them.
        head.state.loop = { header = header, exit = exit, carried = carried, sites = {} }

        local body_block = new_block(C)
        local body, body_diagnostic = arm(L_, head, body_block, statement.body, result_type,
            span, header, carried)
        if not body then return nil, body_diagnostic end

        local agreed, diverged = agree(head, body, head, span)
        if not agreed then return nil, diverged end
        for _, site in ipairs(head.state.loop.sites) do
            for _, id in ipairs(carried) do
                if not same_holes(holes(head, id), site.moved[id] or {}) then
                    return nil, Report.reject(Report.OwnershipDiverges, span)
                end
            end
        end

        head.state.block.exit = B.Branch(ref(head, condition),
            B.Edge(body_block.id, arguments_of(head, carried)),
            B.Edge(exit.id, arguments_of(head, carried)))

        -- Adopt the exit: the loop is over, and the ownership state is the one every edge into it
        -- agreed on.
        C.state.block = exit
        C.state.locations = {}
        C.state.places = agreed
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        C.state.values = {}
        for _, id in ipairs(carried) do
            C.state.values[id] = parameter(C, types[id], Semantic.Read)
        end
        C.state.loop = enclosing
        return true
    end

    -- §3.4: assignment. The destination is established first and NOT replaced -- the place is
    -- computed, not written -- then the right-hand side is evaluated, and only then does the write
    -- happen. Because a `mut` binding is a cell, the write is a `Store` into storage, so the
    -- destination's identity is untouched and no phi is needed at a join.
    -- §12.3: `switch` evaluates its subject EXACTLY ONCE, so the subject crosses every edge. It has
    -- no source definition, and `live` is keyed by definition id, so it gets a SYNTHETIC one -- the
    -- only binding Lower invents, and it exists because an edge argument has to be nameable.
    --
    -- One TEST block per LABEL, chained: each compares the subject and branches to its arm or on to
    -- the next test. So `case 1, 2` is two tests into one arm, which is what a label LIST means --
    -- and it needs no `or`, which short-circuits and would need the value phi this design avoided.
    -- There is no fallthrough, so an arm's body simply ends; and a `switch` is not a loop, so a
    -- `break` inside an arm belongs to the enclosing `while` and is not this form's business.
    lower_switch = function(L_, C, statement, result_type)
        local span = statement.span
        -- §S61: no type is handed in, because the subject's type is whatever lowering it produces
        -- -- and there is nothing here that needs to know it in advance.
        local subject, diagnostic = lower_initializer(L_, C, statement.subject)
        if not subject then return nil, diagnostic end

        -- A `switch` with nothing to match is a no-op: the subject is evaluated (its effects are
        -- the source's) and control continues. Nothing is emitted, so no block is created either.
        if #statement.cases == 0 and #statement.otherwise == 0 then return true end

        L_.synthetic = (L_.synthetic or 0) - 1
        local subject_id = L_.synthetic
        C.state.values[subject_id] = subject

        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end

        -- §S60: a shape label CARRIES its type, so this reads the label itself and never a
        -- declaration -- which is the read §S52 warns about: a type word's definition is created
        -- while resolving the very switch it labels, so its interface may not exist yet.
        local function binding_of(case)
            local denotes = case.labels[1].denotes
            -- §S60: the label SAYS WHICH alternative it is -- `Contract` filled that in, because it
            -- is the phase with the SUBJECT's type -- so the tag is READ here and not re-derived.
            local tag = case.labels[1].alternative
            if tag == nil then return nil end
            if not tag then return nil end
            -- §S65: §1.4 decides whether the binder copies or takes, so it is derived from the
            -- payload's type and not from a spelling at the call site.
            return { id = case.binds, subject = subject_id, tag = tag, type = rep(L_, denotes),
                     copyable = copyable(L_, denotes) }
        end
        local join = new_block(C)
        local arm_blocks = {}
        for index in ipairs(statement.cases) do arm_blocks[index] = new_block(C) end
        local fallback = #statement.otherwise > 0 and new_block(C) or join

        local tests = {}
        for index, case in ipairs(statement.cases) do
            for _, label in ipairs(case.labels) do
                tests[#tests + 1] = { block = new_block(C), label = label, arm = arm_blocks[index] }
            end
        end

        -- The entry leaves for the first test, or straight past the switch when there are no arms.
        C.state.block.exit = B.Jump(B.Edge((tests[1] and tests[1].block or fallback).id,
            arguments_of(C, carried)))

        -- The arms, and the `else` if there is one, all continue at the join.
        local regions = {}
        for index, case in ipairs(statement.cases) do
            local binds
            if case.binds then
                binds = binding_of(case)
                -- `Contract` established that the label IS an alternative of the subject, so a
                -- refusal here is the compiler disagreeing with itself.
                if not binds then
                    return nil, Report.bug(Report.NoLowering('case binder'), span)
                end
            end
            local region, arguments = arm(L_, C, arm_blocks[index], case.body, result_type, span,
                join, carried, binds)
            if not region then return nil, arguments end
            regions[#regions + 1] = region
        end
        if #statement.otherwise > 0 then
            local region, arguments = arm(L_, C, fallback, statement.otherwise, result_type, span,
                join, carried)
            if not region then return nil, arguments end
            regions[#regions + 1] = region
        end

        -- The tests. Each carries the same parameters as an arm, so the edge that reaches it names
        -- the effect first and then the carried values, in the order they were created.
        for index, test in ipairs(tests) do
            local next_block = tests[index + 1] and tests[index + 1].block or fallback
            local region = C:region()
            region.state.block = test.block
            region.state.locations = {}
            region.state.places = copy_places(C.state.places)
            region.state.loop = C.state.loop
            region.state.effect = parameter(region, B.Effect, Semantic.Read)
            region.state.values = {}
            for _, id in ipairs(carried) do
                region.state.values[id] = parameter(region, types[id], Semantic.Read)
            end
            local other = region.state.values[subject_id]

            -- §3.5: a SUM subject is discriminated by its TAG, which is field 0 of `{tag, payload}`.
            -- The tag is never exposed as a field -- nothing in the language names it -- so this is
            -- the one place that knows where it lives, and `Contract` has already established that a
            -- SHAPE label is an alternative of this subject.
            local equal
            if Judge.Shape:isclassof(test.label) then
                -- §S60: WHICH alternative this label is, read off the label -- see `binding_of`.
                -- The subject must still be a sum, because a tag is field 0 of `{tag, payload}`.
                if not B.Sum:isclassof(types[subject_id]) then
                    return nil, Report.bug(Report.NoLowering('case subject'), statement.span)
                end
                local tag = test.label.alternative
                if tag == nil then
                    return nil, Report.bug(Report.NoLowering('case alternative'), statement.span)
                end
                local at = pure(region, B.LoadField(ref(region, other), 0), B.Int)
                local index = pure(region, B.IntegerLiteral(tostring(tag)), B.Int)
                equal = pure(region, B.Binary(Semantic.Equal, ref(region, at), ref(region, index)),
                    B.Bool)
            else
                local label, label_diagnostic = lower_initializer(L_, region, test.label.value,
                    types[subject_id])
                if not label then return nil, label_diagnostic end
                equal = pure(region, B.Binary(Semantic.Equal, ref(region, other),
                    ref(region, label)), B.Bool)
            end
            region.state.block.exit = B.Branch(ref(region, equal),
                B.Edge(test.arm.id, arguments_of(region, carried)),
                B.Edge(next_block.id, arguments_of(region, carried)))
            regions[#regions + 1] = region
        end

        -- §S66: does the switch cover every value its subject can hold? Then its fall-through is not
        -- a path, and comparing it invents one. Two subject kinds can be exhaustive in the belt: a
        -- sum whose every alternative is labelled, and a Bool whose both values are. The same fact
        -- §12.3 states as "a switch terminates only when every value is caught" -- derived here from
        -- the belt types, because the labels' alternatives are belt types and this is where the
        -- agreement is decided.
        local function covers_everything()
            if #statement.otherwise > 0 or #statement.cases == 0 then return false end
            local subject_type = types[subject_id]
            if B.Sum:isclassof(subject_type) then
                for _, alternative in ipairs(subject_type.alternatives) do
                    local matched = false
                    for _, test in ipairs(tests) do
                        if Judge.Shape:isclassof(test.label)
                            and alternative:equals(rep(L_, test.label.denotes)) then
                            matched = true
                        end
                    end
                    if not matched then return false end
                end
                return true
            end
            if subject_type == B.Bool then
                local seen = {}
                for _, test in ipairs(tests) do
                    local constant = Judge.Constant:isclassof(test.label) and test.label.value
                    if constant and Judge.Literal:isclassof(constant)
                        and Syntax.Boolean:isclassof(constant.value) then
                        seen[constant.value] = true
                    end
                end
                return seen[true] == true and seen[false] == true
            end
            return false
        end
        local exhaustive = covers_everything()

        -- §3.3 at the merge: the paths that can REACH the join must agree about the places that
        -- outlive the switch. The arms and the `else` are those paths. A test block's state is the
        -- parent's and its fall-through carries it into the join, so a test is a path too -- which is
        -- why it is compared unless the switch covers everything, when that edge cannot be taken.
        local agreed, diverged
        for index = 1, exhaustive and #statement.cases or #regions do
            local one
            one, diverged = agree(C, regions[1], regions[index], span)
            if not one then return nil, diverged end
            agreed = one
        end

        C.state.block = join
        C.state.locations = {}
        C.state.places = agreed
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        C.state.values = {}
        for _, id in ipairs(carried) do
            C.state.values[id] = parameter(C, types[id], Semantic.Read)
        end
        return true
    end

    -- §3.4's short-circuiting operators, and the ONE place a value genuinely differs per path.
    -- `a and b` is `b` when `a` is true and `a` when it is false, and only one of them runs -- so
    -- this is where the VALUE PHI appears: a parameter of the join that the two arms fill with
    -- different producers. Nothing else in the design needed one. §S32 made the thing that differs
    -- MEMORY (a cell, whose identity is fixed), and §S28 made it AGREE across paths (the identity
    -- interface, because no assignment existed to disagree about). Neither is available here: not
    -- running the right operand is the operator's whole meaning, so the difference is irreducible.
    --
    -- The short arm needs the LEFT value as a parameter, because that value lives in the parent's
    -- block and a block names only its own positions. The long arm needs nothing extra: its merge
    -- value is the right operand, which it evaluates itself.
    lower_short_circuit = function(L_, C, initializer, type_)
        local span = initializer.span
        local is_and = initializer.operator == Semantic.And
        local left, diagnostic = lower_initializer(L_, C, initializer.left, rep(L_, Semantic.Bool))
        if not left then return nil, diagnostic end

        local carried = live(C)
        local types = {}
        for _, id in ipairs(carried) do types[id] = C.state.values[id].type end

        local join = new_block(C)
        local short_block, long_block = new_block(C), new_block(C)

        -- `and` evaluates the right operand only when the left is TRUE; `or` only when it is FALSE.
        -- So the operators differ in which edge is the short one and what the short arm merges --
        -- nothing else, which is why this is one function and not two.
        local yes_block = is_and and long_block or short_block
        local no_block = is_and and short_block or long_block
        C.state.block.exit = B.Branch(ref(C, left),
            B.Edge(yes_block.id, arguments_of(C, carried)),
            B.Edge(no_block.id, arguments_of(C, carried)))

        -- The short arm: no statements at all, one extra parameter for the value it merges.
        local short = C:region()
        short.state.block = short_block
        short.state.locations = {}
        short.state.places = copy_places(C.state.places)
        short.state.loop = C.state.loop
        short.state.effect = parameter(short, B.Effect, Semantic.Read)
        short.state.values = {}
        for _, id in ipairs(carried) do
            short.state.values[id] = parameter(short, types[id], Semantic.Read)
        end
        local merged = parameter(short, B.Bool, Semantic.Read)
        local short_arguments = arguments_of(C, carried)
        short_arguments:insert(ref(C, left))
        local short_out = L{ref(short, short.state.effect)}
        for _, id in ipairs(carried) do short_out:insert(ref(short, short.state.values[id])) end
        short_out:insert(ref(short, merged))
        short.state.block.exit = B.Jump(B.Edge(join.id, short_out))

        -- The long arm: the right operand, evaluated here and passed on as the merge value.
        local long = C:region()
        long.state.block = long_block
        long.state.locations = {}
        long.state.places = copy_places(C.state.places)
        long.state.loop = C.state.loop
        long.state.effect = parameter(long, B.Effect, Semantic.Read)
        long.state.values = {}
        for _, id in ipairs(carried) do
            long.state.values[id] = parameter(long, types[id], Semantic.Read)
        end
        local right, right_diagnostic = lower_initializer(L_, long, initializer.right, rep(L_, Semantic.Bool))
        if not right then return nil, right_diagnostic end
        local long_out = arguments_of(long, carried)
        long_out:insert(ref(long, right))
        long.state.block.exit = B.Jump(B.Edge(join.id, long_out))

        local agreed, diverged = agree(C, short, long, span)
        if not agreed then return nil, diverged end

        -- Adopt the join. Its parameters are `[Effect] + carried + the merged value`, so the value
        -- the expression denotes is the join's LAST parameter -- the other side of the phi the two
        -- arms just filled in.
        C.state.block = join
        C.state.locations = {}
        C.state.places = agreed
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        C.state.values = {}
        for _, id in ipairs(carried) do
            C.state.values[id] = parameter(C, types[id], Semantic.Read)
        end
        return parameter(C, B.Bool, Semantic.Read)
    end

    lower_assign = function(L_, C, statement)
        -- The one destination that is not a place (§12.1's runtime index), answered BEFORE `lower_place`
        -- because there is no single address to build.
        if Judge.Element:isclassof(statement.place) then
            return lower_element_store(L_, C, statement)
        end
        local target, diagnostic = lower_place(L_, C, statement.place)
        if not target then return nil, diagnostic end
        diagnostic = check_place(C, target.root, target.path, statement.span, false)
        if diagnostic then return nil, diagnostic end
        -- §3.4's destination is the *binding*. A projected one is a `StoreField` through the address
        -- the place carries, and §S68 gives every projection inside addressable storage one, at any
        -- depth, because the address chains. This guard is where TWO DERIVATIONS of one fact have to
        -- agree, which is why it stays: `Contract` answers "is this place writable" by walking the
        -- PATH (`writes_through_a_member`), and `is_cell` answers "is this storage addressable" by
        -- asking the TYPE (`interior_mutability`). Writable must imply addressable, and the only way
        -- it cannot is the compiler disagreeing with itself -- an interface not yet built when
        -- `is_cell` asks for it. So it is a `Bug` and not a `Missing`: a `Missing` says the language
        -- needs a mechanism, and §S71 built this one.
        local projected = target.path ~= ''
        if projected and not target.address then
            return nil, Report.bug(Report.UnaddressableDestination, statement.span)
        end

        local value
        if Judge.Move:isclassof(statement.value) then
            -- §3.4: "the right-hand side either definitely moved the destination ... or
            -- definitely did not". Taking the source marks it moved, which is what makes the
            -- replaced-value question static -- there is nothing left to destroy.
            local source, taken = lower_place(L_, C, statement.value.place)
            if not source then return nil, taken end
            value, diagnostic = read_place(L_, C, source, statement.value.span)
            if not value then return nil, diagnostic end
            if not source.cell then
                local moved = take_place(L_, C, source, statement.value.span)
                if not moved then return nil, moved end
            end
        else
            value, diagnostic = lower_initializer(L_, C, statement.value, rep(L_, target.type))
            if not value then return nil, diagnostic end
        end

        -- §3.1 rule 2: destruction happens "at scope exit, on return, and on REPLACEMENT" -- and
        -- replacement is this statement. So the old value goes before the new one is stored, and only
        -- in the branch where the right-hand side did NOT move the destination (§3.4 and §S17: "the
        -- RHS either definitely moved the destination ... or definitely did not", which is what makes
        -- the question static and the destruction unconditional). `place_value` is what the old value
        -- IS -- the cell's content for a root, the member read through its address for a projection --
        -- so this asks the one owner of that question instead of loading a record by hand.
        -- ... and "is there an old value at all?" is the place's own state: a destination that was
        -- MOVED OUT has nothing left to destroy, which is §3.4's sentence again from the other side --
        -- `move h` then `h = made(n)` must not release the handle the move already handed over.
        if not Judge.Move:isclassof(statement.value) and destroys(L_, target.type)
                and not place(C, target.root).moved[target.path] then
            destroy_value(L_, C, target.root, target.path, target.type, place_value(C, target))
        end

        if target.path == '' then
            ordered(C, B.Store(ref(C, C.state.effect), ref(C, target.value), ref(C, value)), nil)
        else
            -- The store goes through the CELL, not through the loaded record: a field of a
            -- record that is not address-taken cannot be written at all, which is why `is_cell`
            -- asks whether any place inside the binding is.
            ordered(C, B.StoreField(ref(C, target.address), target.offset, ref(C, value)), nil)
        end
        -- §3.4: assignment REPLACES, so the destination is initialized afterwards however it was
        -- before -- which is the same fact §3.1 rule 2's "on replacement" is the other half of. Without
        -- this a `move` followed by an assignment left the place marked moved forever, and the next
        -- read of it was refused as uninitialized.
        place(C, target.root).moved[target.path] = nil
        return true
    end

    lower_body = function(L_, C, statements, result_type, span, fallthrough)
        for _, statement in ipairs(statements) do
            if C.state.block.exit then
                return nil, Report.bug(Report.NoLowering('statement after an exit'), span)
            end
            if Judge.Local:isclassof(statement) then
                local value, diagnostic = materialize(L_, C, statement.definition, span)
                if not value then return nil, diagnostic end
                C.state.values[statement.definition] = value
            elseif Judge.Return:isclassof(statement) then
                local value
                if statement.value then
                    local diagnostic
                    value, diagnostic = lower_initializer(L_, C, statement.value, result_type)
                    if not value then return nil, diagnostic end
                else
                    value = pure(C, B.UnitLiteral, B.Unit)
                end
                -- A value that crosses a split must be nameable (§12.3), and the destruction below is a
                -- dispatch when a sum is live here -- so the return value is bound BEFORE it and read from
                -- the binding afterwards. Only when there IS a dispatch: naming one that stays put would
                -- put a C variable in every function that returns.
                local named
                for _, id in ipairs(destroyable(L_, C)) do
                    if dispatches(L_, L_.types[id].result) then
                        named = name_it(L_, C, value, result_type)
                        break
                    end
                end
                destroy_all(L_, C)
                C.state.block.exit = B.Return(L{ref(C, named and C.state.values[named] or value),
                    ref(C, C.state.effect)})
            elseif Judge.Discard:isclassof(statement) then
                -- Contract proved it Copy, so nothing is destroyed and nothing is emitted; the
                -- value is built because building it is what its effects are.
                local diagnostic
                if Judge.Reference:isclassof(statement.value) or Judge.Project:isclassof(statement.value)
                    or Judge.Index:isclassof(statement.value) then
                    local p
                    p, diagnostic = lower_place(L_, C, statement.value)
                    if not p then return nil, diagnostic end
                    local read
                    read, diagnostic = read_place(L_, C, p, statement.span)
                    if not read then return nil, diagnostic end
                else
                    local value
                    value, diagnostic = lower_initializer(L_, C, statement.value)
                    if not value then return nil, diagnostic end
                end
            elseif Judge.Switch:isclassof(statement) then
                local ok, diagnostic = lower_switch(L_, C, statement, result_type)
                if not ok then return nil, diagnostic end
            elseif Judge.Assign:isclassof(statement) then
                local ok, diagnostic = lower_assign(L_, C, statement)
                if not ok then return nil, diagnostic end
            elseif Judge.If:isclassof(statement) then
                local ok, diagnostic = lower_if(L_, C, statement, result_type)
                if not ok then return nil, diagnostic end
            elseif Judge.While:isclassof(statement) then
                local ok, diagnostic = lower_while(L_, C, statement, result_type)
                if not ok then return nil, diagnostic end
            elseif Judge.Break:isclassof(statement) or Judge.Continue:isclassof(statement) then
                -- `break` and `continue` are statements with no operand, and both are errors outside
                -- Inside one they are jumps, and the ownership state they leave in is checked by
                -- the loop that owns them -- which is why the site is recorded rather than
                -- checked here, where the header's state is not in hand.
                local loop = C.state.loop
                if not loop then
                    return nil, Report.reject(Report.NotExecutable, statement.span)
                end
                loop.sites[#loop.sites + 1] = { moved = {} }
                local site = loop.sites[#loop.sites]
                for _, id in ipairs(loop.carried) do site.moved[id] = copy(holes(C, id)) end
                local target = Judge.Break:isclassof(statement) and loop.exit or loop.header
                C.state.block.exit = B.Jump(B.Edge(target.id, arguments_of(C, loop.carried)))
            else
                return nil, Report.bug(Report.NoLowering('statement'), statement.span)
            end
        end
        -- §3.3, again: the tail of a body is the region's EXIT, and the caller owns what that exit
        -- is. A word body that reaches its end returns Unit (§12.3); an arm that reaches its end
        -- continues at its join. Same rule, two regions -- so the tail is a parameter, not a case.
        if not C.state.block.exit then
            destroy_all(L_, C)
            C.state.block.exit = fallthrough(C)
        end
        return true
    end

    -- A definition's value, lowered on demand: an aggregate's member is a definition too, and it
    -- is scoped to the enclosing chain, so the top-level walk does not reach it (§S23).
    materialize = function(L_, C, id, span)
        local declaration = L_.declarations[id]
        if not declaration then
            return nil, Report.reject(Report.UseBeforeInitializer, span)
        end
        -- A WORD is a value too -- `R(t,0)`, which is what §2.6's "all top-level names are visible
        -- through the module namespace" means for a name that denotes a word -- so materializing one
        -- CONSTRUCTS it. Refusing it here is what made a capture of a word unreachable: the capture's
        -- declaration is a reference to the word, and a reference to a word is a value.
        if Judge.Word:isclassof(declaration) then
            local lowered, diagnostic = construct_base(L_, C, id, declaration.word)
            if not lowered then return nil, diagnostic end
            if is_cell(L_, id) then
                lowered = ordered(C, B.Allocate(ref(C, C.state.effect), ref(C, lowered)),
                    B.Cell(belt_type_of(L_, id)))
            end
            C.state.values[id] = lowered
            place(C, id)
            return lowered
        end
        if not Judge.Value:isclassof(declaration) then
            return nil, Report.reject(Report.UseBeforeInitializer, span)
        end
        local lowered, diagnostic = lower_initializer(L_, C, declaration.value, belt_type_of(L_, id),
            slot_type_of(L_, id))
        if not lowered then return nil, diagnostic end
        -- §3.4/§3.2: an assignable binding is address-taken, so it is allocated ONCE, at its
        -- declaration -- which is before any control flow can reach it. Every read loads it and
        -- every write stores it, and the cell's identity never changes.
        -- `is_cell` and not `declaration.mutable`: §3.7 makes a `mut` MEMBER a second reason for the
        -- storage to be addressable, and this was the second place the rule was written -- the other
        -- is `lower_place` -- so implementing it in one of them produced a binding that was celled for
        -- reads and not for writes. One owner, asked twice.
        if is_cell(L_, id) then
            lowered = ordered(C, B.Allocate(ref(C, C.state.effect), ref(C, lowered)),
                B.Cell(belt_type_of(L_, id)))
        end
        C.state.values[id] = lowered
        place(C, id)
        return lowered
    end

    -- Bind a packet's members from an incoming record: each is a LoadField of the parameter, so
    -- `advance_k` can rebuild the next record without re-running anything.
    local function unpack(L_, C, template, k, record)
        for i, id in ipairs(packet_of(L_, template, k)) do
            C.state.values[id] = pure(C, B.LoadField(ref(C, record), i - 1), field_type_of(L_, id))
        end
    end

    -- Run the preludes of one group, binding each. A member already bound is a field the record
    -- already carries, so it is skipped rather than recomputed.
    local function run_group(L_, C, template, k)
        for _, id in ipairs(packet_of(L_, template, k)) do
            if not C.state.values[id] then
                local declaration = L_.declarations[id]
                if not declaration or not declaration.value then
                    return nil, Report.bug(Report.NoLowering('prelude'), L_.definitions[1].span)
                end
                local value, diagnostic = lower_initializer(L_, C, declaration.value, belt_type_of(L_, id),
                    slot_type_of(L_, id))
                if not value then return nil, diagnostic end
                C.state.values[id] = value
            end
        end
        return true
    end

    local function construct_record(L_, C, template, k)
        local type_ = residual_type(L_, template, k)
        local refs = L()
        for _, id in ipairs(packet_of(L_, template, k)) do refs:insert(ref(C, C.state.values[id])) end
        return pure(C, B.Construct(refs), type_), type_
    end

    ---------------------------------------------------------------------------------------------
    -- The three generated functions of a word. `construct` and `advance_k` build the residual
    -- records; `run` enters the terminal with the packet as its parameters (spec §2.3).
    ---------------------------------------------------------------------------------------------

    build_construct = function(L_, template, id)
        local definition = L_.definitions[template]
        local C = open(L_, 'let_' .. definition.name .. '_construct')
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        -- §2.2's frame: the captures are PARAMETERS, declared before anything is emitted (parameters
        -- first, then instructions) and bound to their binders, so the chain uses them exactly as it
        -- uses its own storage. `unpack` refills them from the packet at every advance, and
        -- `run_group` then skips them rather than recomputing them -- which is what stops a word from
        -- rebuilding the module state it was given.
        for _, capture in ipairs(definition.declaration.word.captures or {}) do
            C.state.values[capture.binder] =
                parameter(C, field_type_of(L_, capture.binder), Semantic.Read)
        end
        local ok, diagnostic = run_group(L_, C, definition.declaration.word, 0)
        if not ok then return nil, diagnostic end
        local record, type_ = construct_record(L_, C, definition.declaration.word, 0)
        C.state.block.exit = B.Return(L{ref(C, record), ref(C, C.state.effect)})
        return freeze(C, L{type_, B.Effect}, false)
    end

    -- **Parameters first, then instructions.** A producer's position is its index among the
    -- block's parameters followed by its instructions, so emitting an instruction before a later
    -- parameter exists gives both the same position, and `ref` then silently resolves to the
    -- wrong one. Every builder declares its whole packet before it emits anything.
    build_advance = function(L_, template, k, id)
        local definition = L_.definitions[template]
        local word = definition.declaration.word
        local C = open(L_, ('let_%s_advance_%d'):format(definition.name, k - 1))
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        local previous = parameter(C, residual_type(L_, word, k - 1), Semantic.Read)
        local stage = stages_of(word)[k]
        local stage_value = parameter(C, rep(L_, stage.type), Semantic.Read)
        unpack(L_, C, word, k - 1, previous)
        C.state.values[stage.binder] = stage_value
        local ok, diagnostic = run_group(L_, C, word, k)
        if not ok then return nil, diagnostic end
        local record, type_ = construct_record(L_, C, word, k)
        C.state.block.exit = B.Return(L{ref(C, record), ref(C, C.state.effect)})
        return freeze(C, L{type_, B.Effect}, false)
    end

    build_run = function(L_, template, id)
        local definition = L_.definitions[template]
        local word = definition.declaration.word
        local C = open(L_, 'let_' .. definition.name .. '_run')
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        unpack(L_, C, word, word.stages, parameter(C, residual_type(L_, word, word.stages), Semantic.Read))
        local type_ = rep(L_, L_.types[template].result)
        if not type_ then
            return nil, Report.bug(Report.NoLowering('representation'), definition.span)
        end
        -- The terminal is a data expression, a `do` body, or -- for a DECLARED host word -- a host
        -- symbol. They lower differently: the first is a value, the second a sequence of statements
        -- whose exit is its `return`, and the third is one call whose arguments are the packet's
        -- members in order. Falling off the end of a body returns Unit (§12.3).
        --
        -- Purity decides which host op: a pure host word folds and carries no effect (§12.2's full
        -- promise), an ordered one takes the effect and threads it.
        -- A CONVERSION word's run is one pure op over the packet's member. §11.7 puts `Convert` among
        -- the pure ops, which is what lets the folder fold one whose operand it knows -- and a folded
        -- conversion is why `ToCString "x"` costs nothing at all.
        if word.terminal and Chain.Convert:isclassof(word.terminal) then
            local members = packet_of(L_, word, word.stages)
            -- The sole member is the LAST one: §2.2 puts the capture frame first, and a conversion
            -- word is built by the resolver where there is nothing to capture -- so this is its stage,
            -- and reading it as `[1]` would be reading the frame.
            local member = members[#members]
            local value = pure(C, B.Convert(word.terminal.kind, ref(C, C.state.values[member])), type_)
            C.state.block.exit = B.Return(L{ref(C, value), ref(C, C.state.effect)})
            return freeze(C, L{type_, B.Effect}, false)
        end
        if not definition.declaration.terminal then
            local arguments = L()
            for index in ipairs(packet_of(L_, word, word.stages)) do
                arguments:insert(ref(C, C.state.values[packet_of(L_, word, word.stages)[index]]))
            end
            local symbol = word.terminal.symbol
            if word.purity == Semantic.Pure then
                local result = pure(C, B.PureHostCall(symbol, arguments), type_)
                C.state.block.exit = B.Return(L{ref(C, result), ref(C, C.state.effect)})
            else
                local result = ordered(C, B.HostCall(symbol, ref(C, C.state.effect), arguments), type_)
                C.state.block.exit = B.Return(L{ref(C, result), ref(C, C.state.effect)})
            end
        elseif Judge.Data:isclassof(definition.declaration.terminal) then
            local result, diagnostic =
                lower_initializer(L_, C, definition.declaration.terminal.value, type_)
            if not result then return nil, diagnostic end
            C.state.block.exit = B.Return(L{ref(C, result), ref(C, C.state.effect)})
        else
            local ok, diagnostic = lower_body(L_, C, definition.declaration.terminal.statements,
                type_, definition.span, function(region)
                    local unit = pure(region, B.UnitLiteral, B.Unit)
                    return B.Return(L{ref(region, unit), ref(region, region.state.effect)})
                end)
            if not ok then return nil, diagnostic end
        end
        return freeze(C, L{type_, B.Effect}, false)
    end

    ---------------------------------------------------------------------------------------------
    -- The root. The module initializer IS the file chain's run (spec §2.6), so it is lowered
    -- inline: every top-level value prelude runs in source order because spec §2.6 makes
    -- initialization observable, and a written terminal replaces the namespace (§2.6).
    ---------------------------------------------------------------------------------------------

    -- §2.6: "an embedding host selects and invokes an exported top-level word after initialization
    -- completes." So every top-level word gets an ENTRY POINT -- a function taking the module value
    -- plus that word's remaining stages -- and it is a ROOT of demand, alongside the initializer.
    --
    -- That is the whole point: without it, a word nothing inside the module applies is demanded at
    -- prefix 0 only (S25), so its `advance_k` and `run` do not exist and the host has nothing to
    -- call. Being a root is what makes an exported word lowerable on its own.
    --
    -- The word VALUE comes out of the namespace, because the initializer constructed it and put it
    -- there. That is also why entries are generated only for the implicit namespace: a written
    -- terminal CHOOSES the export surface (§2.6), so which names it exposes is not structural.
    lower_entry = function(L_, template, id)
        local declaration = L_.declarations[template]
        if not declaration or not Judge.Word:isclassof(declaration) then
            return nil, Report.bug(Report.NoLowering('entry point'), L_.definitions[1].span)
        end
        local word = declaration.word
        local stages = stages_of(word)
        -- The initializer is demanded first, so the namespace's type is already known. A written
        -- terminal does not produce entries at all -- it CHOOSES the export surface (§2.6), so
        -- which names it exposes is not a structural fact and the entry cannot read one out of it.
        local namespace_type = L_.namespace_type
        local result_type = rep(L_, L_.types[template].result)
        if not namespace_type or not result_type then
            return nil, Report.bug(Report.NoLowering('representation'), L_.definitions[1].span)
        end

        -- The member's index in the namespace, which is source order among the top-level names --
        -- the same order `lower_module` builds the record in.
        local index
        for _, definition in ipairs(L_.definitions) do
            if not definition.scope
                and (Judge.Value:isclassof(definition.declaration)
                     or Judge.Word:isclassof(definition.declaration)) then
                index = (index or -1) + 1
                if definition.id == template then break end
            end
        end
        if not index then
            return nil, Report.bug(Report.NoLowering('entry point'), L_.definitions[1].span)
        end

        local C = open(L_, 'let_' .. L_.names[template] .. '_entry')
        -- Every parameter exists BEFORE any instruction: the numbering rule's first corollary, and
        -- the reason the stages are created in one pass and only then consumed.
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        local module = parameter(C, namespace_type, Semantic.Read)
        local supplied = L()
        for _, stage in ipairs(stages) do
            supplied:insert(parameter(C, rep(L_, stage.type), Semantic.Read))
        end

        local value = pure(C, B.LoadField(ref(C, module), index), residual_type(L_, word, 0))
        for k = 0, #stages - 1 do
            local advance = demand(L_, 'advance:' .. template .. ':' .. (k + 1), function(M, which)
                return build_advance(M, template, k + 1, which)
            end)
            if not advance then return nil, L_.diagnostic end
            value = ordered(C, B.CallFunction(advance, ref(C, C.state.effect),
                L{ref(C, value), ref(C, supplied[k + 1])}), residual_type(L_, word, k + 1))
        end
        local run = demand(L_, 'run:' .. template, function(M, which)
            return build_run(M, template, which)
        end)
        if not run then return nil, L_.diagnostic end
        local result = ordered(C, B.CallFunction(run, ref(C, C.state.effect), L{ref(C, value)}),
            result_type)
        C.state.block.exit = B.Return(L{ref(C, result), ref(C, C.state.effect)})
        return freeze(C, L{result_type, B.Effect}, true)
    end

    local function lower_module(L_, id)
        local C = open(L_, 'let_module_init')
        C.state.effect = parameter(C, B.Effect, Semantic.Read)

        local members = L()
        for _, definition in ipairs(L_.definitions) do
            if not definition.scope then
                local declaration = definition.declaration
                if Judge.Value:isclassof(declaration) then
                    -- `field_type_of` and not `rep`: what a namespace member's SLOT holds is the same
                    -- question a capture's slot and a packet member's slot ask, and it is not the same
                    -- question as "what does this type look like" -- a WORD-typed value's layout is its
                    -- packet, and a CELLED member's slot is its address. This site bypassed both rules,
                    -- which is why binding a partial application was a `Bug(NoLowering)`.
                    local type_ = field_type_of(L_, definition.id)
                    if not type_ then
                        return nil, Report.bug(Report.NoLowering('representation'), definition.span)
                    end
                    -- `materialize` and not `lower_initializer`: a top-level `mut` prelude is a CELL
                    -- exactly as a local one is, and this was the second place the cell was decided --
                    -- so the namespace held the value where every word's capture expected the address.
                    local value, diagnostic = materialize(L_, C, definition.id, definition.span)
                    if not value then return nil, diagnostic end
                    members:insert({ name = definition.name, id = definition.id, span = definition.span })
                elseif Judge.Word:isclassof(declaration) then
                    -- §2.6: "all top-level names are visible through the module namespace", so a
                    -- top-level WORD is a value in it -- `R(t,0)`, which is what the name denotes
                    -- before it is applied. The initializer CONSTRUCTS it and the namespace owns it;
                    -- advancing and running it is the host entry point's business (§2.6), so the
                    -- word's own `advance_k`/`run` are demanded there and not here.
                    local constructed, diagnostic = construct_base(L_, C, definition.id,
                        declaration.word)
                    if not constructed then return nil, diagnostic end
                    C.state.values[definition.id] = constructed
                    members:insert({ name = definition.name, id = definition.id, span = definition.span })
                end
            end
        end

        local record, result
        local program = L_.program
        if program.namespace then
            result = rep(L_, program.namespace_type)
            if not result then
                return nil, Report.bug(Report.NoLowering('representation'), L_.definitions[1].span)
            end
            local value, diagnostic = lower_initializer(L_, C, program.namespace, result)
            if not value then return nil, diagnostic end
            record = value
            -- §2.6: the module value is `{ export, state }` and "the returned value must own what the
            -- namespace does not reach". For a WRITTEN terminal the export IS the terminal's value, so
            -- the module owns it -- and that is what `unload` destroys, which is the half this phase did
            -- not have: a written terminal holding a resource leaked it at unload in silence.
            --
            -- The `state` member is the other half, and it is needed only when the terminal did NOT take
            -- everything: a prelude the terminal moved into its value is owned there and must not be
            -- owned twice, and one it left behind is still the module's. Building that member turns the
            -- module value into a PAIR, which is a mechanism this phase does not have -- so it is
            -- reported, and only when something is actually left over.
            -- "What the namespace does NOT REACH" is §2.6's own phrase and it is computable: the
            -- terminal's value reaches a definition when it names it -- including through the
            -- declarations it names, because `{ let x = move h }` reaches `h` -- so the members it
            -- reaches are owned by the terminal, and the ones it does not are still the module's.
            local reached = {}
            local function mark(initializer, depth)
                if depth > 16 then return end
                if Judge.Reference:isclassof(initializer) then
                    if reached[initializer.definition] then return end
                    reached[initializer.definition] = true
                    local declaration = L_.declarations[initializer.definition]
                    if declaration and Judge.Value:isclassof(declaration) then
                        mark(declaration.value, depth + 1)
                    end
                elseif Judge.Aggregate:isclassof(initializer) then
                    for _, member in ipairs(initializer.members) do mark(member.value, depth + 1) end
                elseif Judge.Move:isclassof(initializer) then
                    mark(initializer.place, depth + 1)
                end
            end
            mark(program.namespace, 0)

            -- And "owns something" is a question about the VALUE's representation, not about a word's
            -- TYPE: a word's interface result is what its `run` RETURNS, so a word whose packet is empty
            -- -- `made`, in the program this was written for -- looked like a `Handle` and was counted
            -- as a resource. A word owns what its packet owns.
            local function owns_member(id)
                local declaration = L_.declarations[id]
                if declaration and Judge.Word:isclassof(declaration) then
                    for _, packet_id in ipairs(declaration.word:members(0)) do
                        local interface = L_.types[packet_id]
                        if interface and destroys(L_, interface.result) then return true end
                    end
                    return false
                end
                return destroys(L_, L_.types[id].result)
            end

            local left = 0
            for _, member in ipairs(members) do
                if not reached[member.id] and C.state.values[member.id]
                        and not place(C, member.id).moved[''] and owns_member(member.id) then
                    left = left + 1
                end
            end
            if left > 0 then
                return nil, Report.missing(Report.ModuleState, program.namespace.span)
            end
            -- What the unloader needs: the module VALUE's type, by belt and by meaning.
            L_.namespace_type, L_.namespace_semantic = result, program.namespace_type
            L_.namespace_members = nil
        else
            -- §2.6: the namespace takes ownership of its members, so a non-Copy one is MOVED into
            -- it -- which is why `{ let handle = move buffer }` is the written form. Every `take`
            -- runs before any ref is computed, because a ref is relative to the consumer.
            local taken = L()
            for _, member in ipairs(members) do
                local value, diagnostic
                if is_cell(L_, member.id) then
                    -- §3.2: a celled member's storage IS its cell, and a word may already hold that
                    -- address (§S76's captures) -- so the namespace keeps the CELL rather than moving
                    -- the content out from under a live pointer. One indirection, shared, no second
                    -- allocation: the same rule a capture follows, because it is the same relationship.
                    local p
                    p, diagnostic = lower_place(L_, C, Judge.Reference(member.id, member.span))
                    if not p then return nil, diagnostic end
                    value = p.value
                else
                    value, diagnostic = take(L_, C, member.id, member.span)
                    if not value then return nil, diagnostic end
                end
                taken:insert({ name = member.name, value = value })
            end
            -- §2.6's unloader destroys what the namespace owns, so the namespace's own member list is
            -- the thing it needs -- and it is built here, which makes this the one owner of "what is in
            -- the namespace" as well. A WRITTEN terminal is a different case and gets no unloader yet:
            -- §2.6's `state` member ("whatever the namespace does not reach") is its other half, and
            -- neither half is worth doing alone.
            L_.namespace_members = members
            local fields, refs = L(), L()
            for _, member in ipairs(taken) do
                fields:insert(B.Field(member.name, member.value.type, false))
                refs:insert(ref(C, member.value))
            end
            result = B.Aggregate(fields)
            -- The namespace's belt type, recorded because a HOST ENTRY POINT needs it: the entry
            -- takes the module value and reads the word out of it, and the implicit namespace has no
            -- `Judge.Program.namespace_type` to read the type from -- only a written terminal does.
            L_.namespace_type = result
            record = pure(C, B.Construct(refs), result)
        end

        C.state.block.exit = B.Return(L{ref(C, record), ref(C, C.state.effect)})
        return freeze(C, L{result, B.Effect}, true)
    end

    -- §2.6: "`unload` takes the module value by value -- the host gives it up -- and destroys it in
    -- reverse successful-construction order. It is generated, and emitted only when the module owns
    -- something: a module owning nothing has no unload."
    --
    -- It is a FUNCTION rather than a continuation of the initializer for the reason the sentence
    -- gives: the initializer RETURNS the module value, so it cannot destroy what it returns. And
    -- `destroy_all` already implements the order -- §3.1 rule 2, reverse initialization -- so the body
    -- is the namespace's members bound from the module value and then the ordinary destruction pass.
    -- That is why there is no new belt operation here and no new rule: the module value is a packet
    -- like any other, and the unloader is a function that takes one.
    local function build_unload(L_, id)
        local C = open(L_, 'let_module_unload')
        C.state.effect = parameter(C, B.Effect, Semantic.Read)
        local module = parameter(C, L_.namespace_type, Semantic.Read)
        if L_.namespace_members then
            -- The IMPLICIT namespace: the module value IS the namespace, so its members are bound by
            -- index and destroyed in the order the initializer built them.
            for index, member in ipairs(L_.namespace_members) do
                C.state.values[member.id] = pure(C, B.LoadField(ref(C, module), index - 1),
                    field_type_of(L_, member.id))
            end
            destroy_all(L_, C)
        else
            -- A WRITTEN terminal: the module value is the terminal's value, and the module owns it --
            -- so `unload` destroys the VALUE and not a record of names. The root is synthetic because
            -- destruction is the one place that asks a PLACE for its state, and this value is a
            -- parameter rather than a binding.
            L_.synthetic = (L_.synthetic or 0) - 1
            destroy_value(L_, C, L_.synthetic, '', L_.namespace_semantic, module)
        end
        C.state.block.exit = B.Return(L{ref(C, C.state.effect)})
        -- `L{effect}` and nothing else: a function whose only result is the effect returns NOTHING in
        -- C, which is exactly the `void` §2.6 writes, and the emitter already prints it that way.
        return freeze(C, L{B.Effect}, true)
    end

    function Lower.run(unit, program, syntax, k_ok, k_diag)
        local L_ = lowerer(unit, program)
        -- §S23's roots, and there are two kinds of them. The module initializer is one. The other
        -- is one entry point per exported top-level word: a word the host invokes is demanded even
        -- when nothing inside the module applies it.
        local root = demand(L_, 'module', function(M) return lower_module(M, 0) end)
        if not root then return k_diag(unit, L_.diagnostic) end
        if not program.namespace then
            for _, definition in ipairs(L_.definitions) do
                if not definition.scope and Judge.Word:isclassof(definition.declaration) then
                    local entry = demand(L_, 'entry:' .. definition.id, function(M)
                        return lower_entry(M, definition.id, 0)
                    end)
                    if not entry then return k_diag(unit, L_.diagnostic) end
                end
            end
        end
        -- §2.6: the unloader is a THIRD root, and it exists only when the module OWNS something --
        -- which makes the demand a question about the namespace's members rather than about the
        -- module existing. "Owning" is §3.1's own question: a type that has a destructor.
        local owns = L_.namespace_semantic ~= nil and destroys(L_, L_.namespace_semantic)
        if not owns then
            for _, member in ipairs(L_.namespace_members or {}) do
                if destructor_of(L_, member.id) then owns = true break end
            end
        end
        if owns then
            local unload = demand(L_, 'unload', function(M, id) return build_unload(M, id) end)
            if not unload then return k_diag(unit, L_.diagnostic) end
        end

        local functions = L()
        for id = 1, L_.next_id do functions:insert(L_.functions[id]) end
        unit.ambient.belt = functions
        return k_ok(unit, functions)
    end

    return Lower
end

end)

-- let/op.lua
module('let.op', function(require, ...)
-- The one owner of what an opcode reads, and later of what it means.
--
-- DESIGN §11: *"the opcode semantics live in one registry"*. The emitter asks this for the refs an
-- instruction reads instead of listing operands itself -- which is exactly how the emitter and the
-- abstract evaluator would otherwise drift apart. Scalar semantics join it when the abstract
-- evaluator needs them shared with the concrete oracle.
--
-- `instruction.operation` is `Op = Pure(PureOp) | Ordered(OrderedOp)`, so the inner operation is
-- one level in. The **effect** is a ref like any other here: it is evidence of order, not a value,
-- and only the emitter decides that it has no C representation.
return function(V)
    local B = V.Belt
    local Op = {}

    -- The refs an instruction reads, in the order its opcode declares them.
    function Op.inputs(instruction)
        local op = instruction.operation.operation
        -- The literal family reads nothing: its value is in the opcode. `TextLiteral` is in it for
        -- the same reason as the rest -- the text is the constant, not a reference to one.
        if B.IntegerLiteral:isclassof(op) or B.FloatLiteral:isclassof(op)
            or B.BooleanLiteral:isclassof(op)
            or B.UnitLiteral:isclassof(op) or B.TextLiteral:isclassof(op) then
            return {}
        end
        if B.Construct:isclassof(op) then return op.fields end
        if B.Unary:isclassof(op) then return {op.operand} end
        if B.Convert:isclassof(op) then return {op.value} end
        if B.InjectSum:isclassof(op) then return {op.payload} end
        if B.Destroy:isclassof(op) then return {op.effect, op.value} end
        if B.Binary:isclassof(op) then return {op.left, op.right} end
        if B.CheckedBinary:isclassof(op) then return {op.effect, op.left, op.right} end
        if B.LoadField:isclassof(op) then return {op.record} end
        -- A cell's reads and writes: the storage op takes the effect and the whole record, the
        -- cell ops take the effect and the cell.
        if B.Allocate:isclassof(op) then return {op.effect, op.initial} end
        if B.Load:isclassof(op) then return {op.effect, op.cell} end
        if B.Store:isclassof(op) then return {op.effect, op.cell, op.value} end
        if B.FieldAddress:isclassof(op) then return {op.cell} end
        if B.StoreField:isclassof(op) then return {op.record, op.value} end
        -- A move consumes the effect; the value it transfers is the same ref the consumer holds.
        if B.Move:isclassof(op) then return {op.effect, op.value} end
        -- A host call reads its arguments, and an ORDERED one reads the effect first -- the same
        -- shape as `CallFunction`, because the effect is evidence of order and not of value.
        if B.PureHostCall:isclassof(op) then
            local refs = {}
            for _, ref in ipairs(op.arguments) do refs[#refs + 1] = ref end
            return refs
        end
        if B.HostCall:isclassof(op) then
            local refs = {op.effect}
            for _, ref in ipairs(op.arguments) do refs[#refs + 1] = ref end
            return refs
        end
        if B.CallFunction:isclassof(op) then
            local refs = {op.effect}
            for _, ref in ipairs(op.arguments) do refs[#refs + 1] = ref end
            return refs
        end
        error('no input rule for ' .. tostring(getmetatable(op) and getmetatable(op).kind), 0)
    end

    -- Whether an opcode has C work of its own. A `Move` does not: it is an ownership transition,
    -- and its runtime representation is nothing -- the value is already in hand and the source is
    -- simply not destroyed. Everything else is either a value the output can see or an effect
    -- whose scheduled work is that statement.
    function Op.emits(op)
        return not B.Move:isclassof(op)
    end

    return Op
end

end)

-- let/known.lua
module('let.known', function(require, ...)
-- Belt.Function -> Judge.Answer* (DEMAND §3, §4, §6).
--
-- The abstract evaluator's domain is `Known(Atom)` or `Runtime(Belt.Type)`, and it evaluates the
-- **belt**, never the source: the belt has already resolved stages, preludes, ownership, words and
-- destinations, so re-interpreting source would rebuild all of that and drift from it.
--
-- Two decisions per producer, and both belong to this phase (DESIGN §12.4):
--
--   * `Judge.Answer` -- `Known(Atom)` or `Runtime(Belt.Type)` -- one per producer, in producer
--     order, **joined by ⊔ at a merge**. A block's parameter is answered by the edges that reach
--     it, which is why the phase walks the block graph and not one block.
--   * `Judge.Fate` -- `Immediate` / `Materialized` / `Dropped` -- one per producer: whether a C
--     variable is written for it at all. §12.5 *consumes* this, and that is the whole reason it
--     is decided here rather than there: the walk that decides liveness exists once, in this
--     phase, and the emitter reads the answer instead of guessing it again.
--
-- An ordered operation is never `Known`, because its result list includes `Effect`. That is what
-- makes "pure folds, ordered schedules" structural rather than a convention.
return function(V)
    local B, J, L, S = V.Belt, V.Judge, V.List, V.Semantic

    local Known = {}

    -- §12.4's opcode semantics, shared with nothing yet because the concrete interpreter is still
    -- the legacy oracle. Folding is an OPTIMISATION, so the rule is soundness: fold only when the
    -- result is exactly representable, and leave everything else `Runtime`. That matters because
    -- §1.5's integer arithmetic WRAPS at 64 bits while a Lua number is a double -- so folding
    -- past 2^53 would produce a constant the program never computes.
    local EXACT = 9007199254740992
    local ARITHMETIC = {
        [S.Add] = function(a, b) return a + b end,
        [S.Subtract] = function(a, b) return a - b end,
        [S.Multiply] = function(a, b) return a * b end,
    }
    local COMPARISON = {
        [S.Equal] = function(a, b) return a == b end,
        [S.NotEqual] = function(a, b) return a ~= b end,
        [S.Less] = function(a, b) return a < b end,
        [S.LessEqual] = function(a, b) return a <= b end,
        [S.Greater] = function(a, b) return a > b end,
        [S.GreaterEqual] = function(a, b) return a >= b end,
    }

    -- Both operands must be Int atoms whose values are already exact, or there is nothing to do.
    local function integers(left, right)
        if not left or not right then return nil end
        if not J.Known:isclassof(left) or not J.Known:isclassof(right) then return nil end
        if not J.Int:isclassof(left.atom) or not J.Int:isclassof(right.atom) then return nil end
        return left.atom.value, right.atom.value
    end

    local function atom_of_literal(op)
        if B.IntegerLiteral:isclassof(op) then return J.Int(S.integer_value(op.spelling)) end
        if B.BooleanLiteral:isclassof(op) then return J.Bool(op.value) end
        if B.UnitLiteral:isclassof(op) then return J.Unit end
        -- A Text literal is a value the folder knows, and a module-lifetime one at that (§11.3), so
        -- a `Text`-typed constant folds and inlines like any other.
        if B.TextLiteral:isclassof(op) then return J.Text(op.value) end
        return nil
    end

    -- At consumer position `p`, `Ref(distance, output)` denotes producer `p - 1 - distance`, and the
    -- answer list is indexed by producer + 1.
    local function answer_of(instruction, answers, position)
        local op = instruction.operation
        if B.Pure:isclassof(op) then
            local atom = atom_of_literal(op.operation)
            if atom then return J.Known(atom) end
            -- §1.5: arithmetic wraps, so a folded result must still be exact; comparisons are
            -- exact for any two representable values, so they always fold when both are known.
            if B.Binary:isclassof(op.operation) then
                local a, b = integers(answers[position - op.operation.left.distance],
                    answers[position - op.operation.right.distance])
                if a then
                    local compare = COMPARISON[op.operation.operator]
                    if compare then return J.Known(J.Bool(compare(a, b))) end
                    local arithmetic = ARITHMETIC[op.operation.operator]
                    if arithmetic then
                        local value = arithmetic(a, b)
                        if math.abs(value) <= EXACT then return J.Known(J.Int(value)) end
                    end
                end
                return J.Runtime(instruction.results[1])
            end
            -- What can fold, and honestly what does not. §11.2 makes a conversion a DICTIONARY WORD,
            -- so `ToCString "x"` passes its argument through a packet: inside the word's `run` the
            -- operand is a `LoadField` of a parameter and therefore `Runtime`, which is why this
            -- folds nothing today. It is still the right rule -- it fires whenever a conversion's
            -- operand IS known, which is what an inlining pass would produce -- and `ToCString` is
            -- the same pointer while `TextSize` of a literal is a length the compiler already holds.
            -- The numeric ones cannot fold here at all, because an `Atom` has no Float.
            if B.Convert:isclassof(op.operation) then
                local operand = answers[position - op.operation.value.distance]
                if operand and J.Known:isclassof(operand) and J.Text:isclassof(operand.atom) then
                    if op.operation.kind == S.ToCString then return operand end
                    if op.operation.kind == S.TextSize then
                        return J.Known(J.Int(#operand.atom.value))
                    end
                end
                return J.Runtime(instruction.results[1])
            end
            if B.Unary:isclassof(op.operation) then
                local operand = answers[position - op.operation.operand.distance]
                if operand and J.Known:isclassof(operand) then
                    -- §1.5: `not` is the Bool-to-Bool unary, so its operand is a Bool atom, while
                    -- `Negate` and `BitNot` are the Int ones. Both fold here, and they fold in
                    -- one place because the rule that types them lives in one place too.
                    if op.operation.operator == S.Not and J.Bool:isclassof(operand.atom) then
                        return J.Known(J.Bool(not operand.atom.value))
                    end
                    if op.operation.operator == S.Negate and J.Int:isclassof(operand.atom)
                        and math.abs(operand.atom.value) <= EXACT then
                        return J.Known(J.Int(-operand.atom.value))
                    end
                end
                return J.Runtime(instruction.results[1])
            end
            if B.Construct:isclassof(op.operation) then
                local fields = L()
                for _, ref in ipairs(op.operation.fields) do
                    local field = answers[position - ref.distance]
                    if not field or not J.Known:isclassof(field) then
                        return J.Runtime(instruction.results[1])
                    end
                    fields:insert(field.atom)
                end
                return J.Known(J.Bundle(fields))
            end
        end
        return J.Runtime(instruction.results[1])
    end

    -- Where an exit can go. A `Return`, a `TailCall` and a `Trap` go nowhere: they end the walk,
    -- which is what makes "reachable" the same question as "can this ever run".
    local function successors(exit)
        if B.Jump:isclassof(exit) then return { exit.edge.target } end
        if B.Branch:isclassof(exit) then return { exit.yes.target, exit.no.target } end
        return {}
    end

    -- The reachable blocks, in reverse postorder.
    --
    -- Reachability is DESIGN §12.3's demand one level below instances: a block no edge reaches is
    -- not part of the program, so it is neither answered here nor emitted by §12.5. `Lower` must
    -- still CREATE such a block -- a split's join is built before either arm, because an `Edge`
    -- names its target by id -- and only the graph says whether anything arrives.
    --
    -- Reverse postorder because a block is answered FROM the edges into it, and this is an order
    -- in which a block's predecessors have been answered already. A backedge is the one edge that
    -- violates it, and it is skipped rather than guessed.
    local function walk(belt)
        local reachable, post = { [1] = true }, {}
        local stack = { { id = 1, at = 0 } }
        while #stack > 0 do
            local frame = stack[#stack]
            local targets = successors(belt.blocks[frame.id].exit)
            if frame.at < #targets then
                frame.at = frame.at + 1
                local target = targets[frame.at]
                if not reachable[target] then
                    reachable[target] = true
                    stack[#stack + 1] = { id = target, at = 0 }
                end
            else
                post[#post + 1] = frame.id
                stack[#stack] = nil
            end
        end
        local order = L()
        for i = #post, 1, -1 do order:insert(post[i]) end
        return reachable, order
    end

    -- The edge of `exit` that reaches `target`, or nil. `Edge.arguments[i]` answers the target's
    -- parameter `i`, one for one, because that is what an edge IS (§11.7).
    local function edge_into(exit, target)
        if B.Jump:isclassof(exit) then
            if exit.edge.target == target then return exit.edge end
        elseif B.Branch:isclassof(exit) then
            if exit.yes.target == target then return exit.yes end
            if exit.no.target == target then return exit.no end
        end
        return nil
    end

    -- §12.4's join, at one block parameter. With no assignment every edge into a merge passes the
    -- SAME value (§S28), so `⊔` is idempotent and a single pass in reverse postorder reaches the
    -- fixpoint. An edge whose source is not answered yet is skipped rather than guessed: a
    -- backedge cannot teach the header anything the header did not already know.
    local function parameter_answer(belt, answers, id, index)
        local merged
        for source = 1, #belt.blocks do
            local list = answers[source]
            if list then
                local block = belt.blocks[source]
                local edge = edge_into(block.exit, id)
                if edge and #edge.arguments >= index then
                    local ref = edge.arguments[index]
                    local exit_at = #block.parameters + #block.instructions
                    local answer = list[exit_at - ref.distance]
                    if answer then
                        merged = merged
                            and merged:join(answer, belt.blocks[id].parameters[index].type)
                            or answer
                    end
                end
            end
        end
        return merged
    end

    -- §12.5 consumes a `Judge.Fate`, so the decision belongs to the phase that already walks the
    -- block. A parameter is always materialized -- it is a C variable or a function parameter. A
    -- folded producer is a constant and gets no variable. An ordered opcode with C work is written
    -- for its effect. A pure runtime value is written only if something reads it -- including the
    -- exit, because an edge's arguments are reads too. Everything else is dropped.
    local function fates_of(belt, block, answers)
        local count = #block.parameters + #block.instructions
        local used = {}
        local exit = block.exit
        if B.Return:isclassof(exit) then
            for _, ref in ipairs(exit.values) do used[count - 1 - ref.distance] = true end
        elseif B.Jump:isclassof(exit) then
            for _, ref in ipairs(exit.edge.arguments) do used[count - 1 - ref.distance] = true end
        elseif B.Branch:isclassof(exit) then
            used[count - 1 - exit.condition.distance] = true
            for _, edge in ipairs{ exit.yes, exit.no } do
                for _, ref in ipairs(edge.arguments) do used[count - 1 - ref.distance] = true end
            end
        elseif B.TailCall:isclassof(exit) then
            used[count - 1 - exit.effect.distance] = true
            for _, ref in ipairs(exit.arguments) do used[count - 1 - ref.distance] = true end
        elseif B.Trap:isclassof(exit) then
            used[count - 1 - exit.effect.distance] = true
        end
        for position = count - 1, #block.parameters, -1 do
            local instruction = block.instructions[position - #block.parameters + 1]
            local ordered = B.Ordered:isclassof(instruction.operation)
            if (ordered and V.Op.emits(instruction.operation.operation)) or used[position] then
                for _, ref in ipairs(V.Op.inputs(instruction)) do
                    used[position - 1 - ref.distance] = true
                end
            end
        end
        local fates = L()
        for position = 0, count - 1 do
            if position < #block.parameters then
                fates:insert(J.Materialized)
            else
                local instruction = block.instructions[position - #block.parameters + 1]
                local answer = answers[position + 1]
                local ordered = B.Ordered:isclassof(instruction.operation)
                -- `ordered` is tested FIRST and alone, because an ordered opcode must not reach
                -- the `used` branch: a `Move`'s effect is consumed downstream, which would
                -- otherwise make a move look demanded and emit a variable for nothing.
                if ordered then
                    fates:insert(V.Op.emits(instruction.operation.operation)
                        and J.Materialized or J.Dropped)
                elseif J.Known:isclassof(answer) and not J.Bundle:isclassof(answer.atom) then
                    -- A SCALAR known value is spelled where it is used, and a `Bundle` is not: it is a
                    -- compound constant -- a record or a tuple whose members are all known -- and
                    -- spelling it at EVERY use duplicates the whole literal. §12.1's runtime index
                    -- dispatches over the tuple, so its record appears once per test, once per arm and
                    -- once per edge; a tuple of N members costs N^2 text. A compound value is written
                    -- ONCE and named, which is what the emitted C should look like anyway.
                    fates:insert(J.Immediate)
                elseif used[position] then
                    fates:insert(J.Materialized)
                else
                    fates:insert(J.Dropped)
                end
            end
        end
        return fates
    end

    function Known.run(region, belt, k_ok, k_diag)
        local _, order = walk(belt)
        local answers, fates = {}, {}
        for _, id in ipairs(order) do
            local block = belt.blocks[id]
            local list = L()
            for index, parameter in ipairs(block.parameters) do
                local merged = id == 1 and J.Runtime(parameter.type)
                    or parameter_answer(belt, answers, id, index)
                list:insert(merged or J.Runtime(parameter.type))
            end
            local position = #block.parameters
            for _, instruction in ipairs(block.instructions) do
                list:insert(answer_of(instruction, list, position))
                position = position + 1
            end
            answers[id] = list
            fates[id] = fates_of(belt, block, list)
        end
        region.out.answers = answers
        region.out.fates = fates
        return k_ok(region, { answers = answers, fates = fates, order = order })
    end

    return Known
end

end)

-- let/emit.lua
module('let.emit', function(require, ...)
-- Belt.Function* x Judge.Answer* -> C.Unit (DESIGN §12.5).
--
-- The belt is already the semantic program, so emission chooses representations only. The choices
-- here are the design's, not the emitter's:
--
--   * **Effects have no C representation.** An effect token is ordering evidence for the frontend
--     and the belt's statement order already carries that order, so dropping it removes the effect
--     parameter from every signature, the effect field from every result, and the effect argument
--     from every call. That is why `let_module_init` takes `(void)`.
--   * **A `Known` value gets no variable**: every use is the constant. A `Runtime` value that is
--     used gets a declared local. A producer nothing uses is not written at all -- so the belt's
--     `Fate` is computed here, from liveness, not prescribed.
--   * **An ordered instruction is always written**, because its effect is observable even when its
--     result is not (spec §12.2). That is what makes "pure folds, ordered schedules" hold in the
--     output and not just in the belt.
--   * **An include is demanded by a representation**: `stdbool.h` appears only if a `bool` is.
--   * **A record is one `struct` per shape**, so two residuals with the same members are one type.
return function(V)
    local C, B, J, L, S = V.C, V.Belt, V.Judge, V.List, V.Semantic

    local Emit = {}

    -- One emitter per lowering run: the structs, deduplicated by shape, and the headers used.
    local function emitter()
        return { structs = {}, by_shape = {}, includes = {}, next_struct = 0, hosts = {} }
    end

    -- An unnamed member is a positional element (§3.3: it has no declaration qualifier, because it
    -- has no declaration at all). The representation still needs a name for it, and this is the one
    -- place that invents one -- so the struct and every access to it agree by construction.
    local function field_name(field, index) return field.name or ('f' .. index) end

    local function ctype(E, type_)
        if type_ == B.Int then E.includes.stdint = true; return C.I64 end
        if type_ == B.Bool then E.includes.stdbool = true; return C.Bool end
        if type_ == B.Unit then E.includes.stdint = true; return C.U8 end
        if type_ == B.Effect then return nil end
        -- §11.3: Text is a module-lifetime literal, so its representation is a C string -- a
        -- pointer to static storage -- and never a borrowed view, because a view is a separately
        -- declared HOST type (§3.6) and not the core's `Text`. It is `const char *` and not
        -- `uint8_t *`: the literal is a `char *`, and spelling it as bytes is a signedness mismatch
        -- the compiler warns about, which is a representation disagreeing with itself.
        if type_ == B.Text or type_ == B.CString then return C.CString end
        if type_ == B.U8 then E.includes.stdint = true; return C.U8 end
        if type_ == B.U32 then E.includes.stdint = true; return C.U32 end
        if type_ == B.Float then return C.F64 end
        if type_ == B.Float32 then return C.F32 end
        if type_ == B.CPointer then return C.Pointer(C.Void) end
        -- A host type is spelled by its own name, because the definition is the host's. §S43's rule
        -- applies in reverse here: the compiler cannot derive a C struct it has never seen, so the
        -- declaration states the name and the host provides the type.
        if B.Named:isclassof(type_) then return C.Named(type_.name) end
        -- A cell is a POINTER to storage. That is the whole representation of §3.2's
        -- address-taken binding, and it is why assignment is a store rather than a rebinding: the
        -- cell value is the same object on every path, and only what it points at changes.
        if B.Cell:isclassof(type_) then return C.Pointer(ctype(E, type_.contents)) end
        -- §3.5's sum: a tag and ONE payload, so the payload is a union of the alternatives and the
        -- tag says which one is there. Two declarations are needed because C has no anonymous union
        -- member in this vocabulary -- `union let_uN` for the payload, `struct let_sumN` to carry it
        -- with the tag -- and they are deduplicated by shape like a record is, so two sums with the
        -- same alternatives are one type.
        --
        -- The union's fields are `f0`, `f1`, ... because §11.7's `Sum` has alternatives and no
        -- fields: an alternative has no name to be spelled with, which is the same reason a
        -- positional record member is `f<index>`.
        if B.Sum:isclassof(type_) then
            if #type_.alternatives == 0 then return nil end
            E.includes.stdint = true
            local parts = {}
            for _, alternative in ipairs(type_.alternatives) do
                parts[#parts + 1] = tostring(alternative)
            end
            local key = 'sum:' .. table.concat(parts, '|')
            local name = E.by_shape[key]
            if not name then
                E.next_struct = E.next_struct + 1
                name = 'let_s' .. E.next_struct
                E.by_shape[key] = name
                local union_name = 'let_u' .. E.next_struct
                local members, carried = L(), L()
                for index, alternative in ipairs(type_.alternatives) do
                    local mapped = ctype(E, alternative)
                    if not mapped then return nil end
                    members:insert(C.Parameter(mapped, 'f' .. (index - 1)))
                    carried:insert(C.Parameter(mapped, 'f' .. (index - 1)))
                end
                E.structs[#E.structs + 1] = C.Union(union_name, members)
                -- The tag is an `int64_t` rather than the `uint8_t` it could be, because §1.5's
                -- comparisons take Int and there is no `U8 -> Int` conversion word; a narrower tag
                -- would need one invented to compare against. One choice, stated once.
                E.structs[#E.structs + 1] = C.Struct(name, L{
                    C.Parameter(C.I64, 'tag'), C.Parameter(C.Named('union ' .. union_name), 'payload')})
            end
            return C.Named('struct ' .. name)
        end
        if B.Aggregate:isclassof(type_) then
            -- An empty record carries no information, and **an empty struct is not ISO C** -- so
            -- it is the unit byte. That is what makes a word with no state a value with no fields,
            -- rather than a GNU extension that happens to compile.
            if #type_.fields == 0 then E.includes.stdint = true; return C.U8 end
            local parts = {}
            for _, field in ipairs(type_.fields) do
                parts[#parts + 1] = (field.name or '') .. ':' .. tostring(field.type)
            end
            local key = table.concat(parts, '|')
            local name = E.by_shape[key]
            if not name then
                -- A counter, not `#E.structs`: the struct is appended *after* its members are
                -- built, so during that recursion the count has not grown and two shapes would
                -- be given the same name.
                E.next_struct = E.next_struct + 1
                name = 'let_s' .. E.next_struct
                E.by_shape[key] = name
                local members = L()
                for index, field in ipairs(type_.fields) do
                    members:insert(C.Parameter(ctype(E, field.type), field_name(field, index - 1)))
                end
                E.structs[#E.structs + 1] = C.Struct(name, members)
            end
            return C.Named('struct ' .. name)
        end
        return nil
    end

    -- A producer is named by its block and its position in it. The ENTRY block has no label, so it
    -- has no brand: its parameters are the function's own parameters and its instructions are the
    -- function's own locals. That is why an instance with one block still reads `p1`, `v2` -- one
    -- block is not a special case, it is the case with nothing to disambiguate from.
    local function brand_of(id) return id == 1 and '' or ('b' .. id .. '_') end

    local function entity(brand, block, position)
        if position < #block.parameters then return brand .. 'p' .. position end
        return brand .. 'v' .. position
    end

    local function type_at(block, position, output)
        if position < #block.parameters then return block.parameters[position + 1].type end
        return block.instructions[position - #block.parameters + 1].results[output + 1]
    end

    -- A known value's C expression. It takes the belt type because a record's atom is a Bundle of
    -- its members' atoms, so the mapping is recursive -- and it needs each member's type to spell
    -- the designated initializer.
    local record_expr
    local function expr_of(E, type_, atom)
        if J.Int:isclassof(atom) then
            return C.Integer(math.floor(atom.value / 4294967296) % 4294967296, atom.value % 4294967296)
        end
        -- §12.5: "an include is demanded by a REPRESENTATION". A folded constant is a use of one
        -- -- a known `true` is still spelled `true` in C -- so the include is demanded here too.
        -- Demanding it only where `ctype` runs misses every constant the folder produced, and the
        -- output then fails to compile on `true` with nothing to point at.
        if J.Bool:isclassof(atom) then
            E.includes.stdbool = true
            return C.Boolean(atom.value)
        end
        if J.Unit:isclassof(atom) then
            E.includes.stdint = true
            return C.Integer(0, 0)
        end
        if J.Text:isclassof(atom) then return C.String(atom.value) end
        if J.Bundle:isclassof(atom) then return record_expr(E, type_, atom) end
        return nil
    end

    record_expr = function(E, type_, atom)
        -- An empty record is the unit byte, so its value is zero rather than a compound literal
        -- with no members.
        if #type_.fields == 0 then return C.Integer(0, 0) end
        local designators = L()
        for i, field in ipairs(type_.fields) do
            designators:insert(C.Designator(field_name(field, i - 1),
                expr_of(E, field.type, atom.fields[i])))
        end
        return C.Init(ctype(E, type_), designators)
    end

    -- The C expression for a ref. At consumer position `p`, `Ref(distance, output)` denotes producer
    -- `p - 1 - distance` -- the same rule the belt uses, applied once more.
    local function value_expr(E, block, answers, consumer, ref, brand)
        local at = consumer - 1 - ref.distance
        local answer = answers[at + 1]
        if J.Known:isclassof(answer) then
            -- One call: `expr_of` recurses into a Bundle itself, so a record is not a special
            -- case here, and a constant needs no variable.
            return expr_of(E, type_at(block, at, ref.output), answer.atom)
        end
        -- A cell produced by `Allocate` IS its storage's address, because `body_of` declares the
        -- storage with the CONTENTS type and the cell is a pointer to it. Only that producer: a cell
        -- that arrived as a PARAMETER is already a pointer, and taking its address again is `&&`.
        if at >= #block.parameters then
            local producer = block.instructions[at - #block.parameters + 1]
            if B.Allocate:isclassof(producer.operation.operation) then
                return C.Unary('&', C.Name(entity(brand, block, at)))
            end
        end
        return C.Name(entity(brand, block, at))
    end

    -- A 64-bit constant. `C.Integer` takes the two halves because the output has to be valid C
    -- without a suffix guess, so an operator's literal goes through the same spelling as an atom's.
    local function int_expr(value)
        return C.Integer(math.floor(value / 4294967296) % 4294967296, value % 4294967296)
    end

    local function cast_to(E, name, expr)
        E.includes.stdint = true
        return C.Cast(C.Named(name), expr)
    end

    -- §1.5's integer semantics written INLINE in C. There is no helper function, and that is not
    -- style: a helper would be a second implementation of a Let operator, in C, that could drift
    -- from the one `Known` folds. So wrapping is a cast through `uint64_t`, shifts mask their count
    -- with `& 63`, and the two TRAPPING forms use `(abort(), 0)` -- a comma expression, which is
    -- what lets a void call stand where a value is wanted.
    local function binary_expr(E, operator, left, right)
        if operator == S.Add then return cast_to(E, 'int64_t', C.Binary('+', cast_to(E, 'uint64_t', left), cast_to(E, 'uint64_t', right))) end
        if operator == S.Subtract then return cast_to(E, 'int64_t', C.Binary('-', cast_to(E, 'uint64_t', left), cast_to(E, 'uint64_t', right))) end
        if operator == S.Multiply then return cast_to(E, 'int64_t', C.Binary('*', cast_to(E, 'uint64_t', left), cast_to(E, 'uint64_t', right))) end
        if operator == S.BitAnd then return C.Binary('&', left, right) end
        if operator == S.BitOr then return C.Binary('|', left, right) end
        if operator == S.BitXor then return C.Binary('^', left, right) end
        if operator == S.ShiftLeft then
            return cast_to(E, 'int64_t', C.Binary('<<', cast_to(E, 'uint64_t', left),
                C.Binary('&', cast_to(E, 'uint64_t', right), int_expr(63))))
        end
        if operator == S.ShiftRight then
            -- Arithmetic shift, which Let specifies for signed Int; a shift count is reduced modulo
            -- 64, so no shift is undefined and none traps.
            return C.Binary('>>', left, C.Binary('&', right, int_expr(63)))
        end
        if operator == S.Equal then return C.Binary('==', left, right) end
        if operator == S.NotEqual then return C.Binary('!=', left, right) end
        if operator == S.Less then return C.Binary('<', left, right) end
        if operator == S.LessEqual then return C.Binary('<=', left, right) end
        if operator == S.Greater then return C.Binary('>', left, right) end
        if operator == S.GreaterEqual then return C.Binary('>=', left, right) end
        if operator == S.Divide or operator == S.Remainder then
            E.includes.stdlib = true
            local zero = C.Binary('==', right, int_expr(0))
            local minus_one = C.Binary('==', right, int_expr(-1))
            local trap = C.Comma(L{C.Call(C.Name('abort'), L{}), int_expr(0)})
            if operator == S.Divide then
                -- §3.6: `INT_MIN / -1` wraps rather than trapping, so the wrapped quotient is
                -- computed the same way any other wrapping arithmetic is.
                local wrapped = cast_to(E, 'int64_t', C.Binary('-', cast_to(E, 'uint64_t', int_expr(0)), cast_to(E, 'uint64_t', left)))
                return C.Conditional(zero, trap, C.Conditional(minus_one, wrapped, C.Binary('/', left, right)))
            end
            return C.Conditional(zero, trap, C.Conditional(minus_one, int_expr(0), C.Binary('%', left, right)))
        end
        error('no C rule for the operator ' .. tostring(operator), 0)
    end

    -- The expression an instruction computes, from its opcode alone (V.Op owns what it reads).
    local function instruction_expr(E, block, answers, position, instruction, brand)
        local op = instruction.operation.operation
        local type_ = instruction.results[1]
        if B.TextLiteral:isclassof(op) then return C.String(op.value) end
        if B.FloatLiteral:isclassof(op) then return C.Float(S.float_value(op.spelling)) end
        -- §3.5's construction: the tag says which alternative, and only that one is written -- so
        -- the payload is a designated initializer for the union's field at that tag.
        if B.InjectSum:isclassof(op) then
            return C.Init(ctype(E, type_), L{
                C.Designator('tag', C.Integer(0, op.index)),
                C.Designator('payload', C.Init(C.Named('union ' .. ('let_u' .. tostring(ctype(E, type_)):match('%d+'))),
                    L{C.Designator('f' .. op.index,
                        value_expr(E, block, answers, position, op.payload, brand))}))})
        end
        -- §11.7's `Convert`, one C spelling per crossing. The numeric ones are casts because there
        -- are no implicit conversions in the language, so an explicit one is exactly a cast. `ToText`
        -- is absent for the reason the dictionary says: it needs a length the source does not have.
        if B.Convert:isclassof(op) then
            local value = value_expr(E, block, answers, position, op.value, brand)
            local kind = op.kind
            if kind == S.ToInt then return C.Cast(C.I64, value) end
            if kind == S.ToFloat then return C.Cast(C.F64, value) end
            if kind == S.ToU8 then return C.Cast(C.U8, value) end
            if kind == S.ToU32 then return C.Cast(C.U32, value) end
            if kind == S.ToF32 then return C.Cast(C.F32, value) end
            -- A `Text` is already a C string in this representation, so crossing to `CString` is the
            -- same pointer -- and saying so as a cast is what keeps the two types distinct in the
            -- language while they coincide here.
            if kind == S.ToCString then return C.Cast(C.CString, value) end
            if kind == S.TextSize then
                E.includes.string = true
                return C.Cast(C.I64, C.Call(C.Name('strlen'), L{value}))
            end
            if kind == S.IsNull then return C.Unary('!', value) end
            error('no C rule for the conversion ' .. tostring(getmetatable(kind) and getmetatable(kind).kind), 0)
        end
        if B.Construct:isclassof(op) then
            if #op.fields == 0 then return C.Integer(0, 0) end
            local fields = L()
            for _, ref in ipairs(op.fields) do
                fields:insert(value_expr(E, block, answers, position, ref, brand))
            end
            return C.Compound(ctype(E, type_), fields)
        end
        if B.LoadField:isclassof(op) then
            local record_type = type_at(block, position - 1 - op.record.distance, op.record.output)
            -- §3.5/§S59: a sum's field `0` is its TAG and field `1+K` is alternative `K`'s payload,
            -- so both are known offsets -- which makes this the one place that knows where either
            -- lives, and keeps every read of a sum a pure `LoadField`.
            local name
            if B.Sum:isclassof(record_type) then
                if op.field == 0 then
                    name = 'tag'
                else
                    return C.Field(C.Field(value_expr(E, block, answers, position, op.record, brand),
                        'payload'), 'f' .. (op.field - 1))
                end
            else
                name = field_name(record_type.fields[op.field + 1], op.field)
            end
            return C.Field(value_expr(E, block, answers, position, op.record, brand), name)
        end
        -- §12.4's host ops. The symbol is the callee, and the prototype is DERIVED from the Let
        -- types rather than declared by the host (§3.6): the declaration in source is the whole
        -- contract, so the C side of it is generated. A prototype is recorded once per symbol, at
        -- the first call, because that is where its argument and result types are known.
        if B.PureHostCall:isclassof(op) or B.HostCall:isclassof(op) then
            local arguments = L()
            local types = L()
            for _, ref in ipairs(op.arguments) do
                arguments:insert(value_expr(E, block, answers, position, ref, brand))
                types:insert(ctype(E, type_at(block, position - 1 - ref.distance, ref.output)))
            end
            E.hosts[op.symbol] = { parameters = types, result = ctype(E, type_) }
            return C.Call(C.Name(op.symbol), arguments)
        end
        if B.CallFunction:isclassof(op) then
            local arguments = L()
            for _, ref in ipairs(op.arguments) do
                arguments:insert(value_expr(E, block, answers, position, ref, brand))
            end
            -- The effect argument is dropped: order is statement order.
            return C.Call(C.Name(E.callees[op.target]), arguments)
        end
        -- §3.4's storage. A compound literal is what gives the cell's storage a name at its
        -- declaration; C11 gives it the enclosing block's lifetime, which is the function.
        -- §3.4's storage. The declaration IS the storage -- `body_of` declares it with the
        -- CONTENTS type -- and `value_expr` takes its address wherever the cell is named, so the
        -- expression here is simply the initial value.
        if B.Allocate:isclassof(op) then
            return value_expr(E, block, answers, position, op.initial, brand)
        end
        if B.Load:isclassof(op) then
            return C.Unary('*', value_expr(E, block, answers, position, op.cell, brand))
        end
        -- §3.1's second rule, at the point it happens: destruction is a call to the word the type's
        -- declaration named, with the value as its argument.
        if B.Destroy:isclassof(op) then
            -- §3.6/S41: a host type's DESTRUCTOR is declared in source exactly like a host word, so its
            -- prototype is DERIVED the same way -- and it was the one host symbol that never got one.
            -- The emitted unit therefore called `release` before any declaration of it, so it did not
            -- compile on its own: the host had to pre-declare what the source had already declared.
            -- That is the whole of "the declaration, not the implementation, is what the compiler holds
            -- a host to" -- the compiler had the declaration and did not use it.
            local destroyed = ctype(E, type_at(block, position - 1 - op.value.distance, op.value.output))
            E.hosts[op.destructor] = { parameters = L{destroyed}, result = nil }
            return C.Call(C.Name(op.destructor), L{value_expr(E, block, answers, position, op.value, brand)})
        end
        if B.Store:isclassof(op) then
            return C.Assign(C.Unary('*', value_expr(E, block, answers, position, op.cell, brand)),
                value_expr(E, block, answers, position, op.value, brand))
        end
        -- §S68: the address of a field, for a path that has to reach through storage. This is the
        -- only place that knows a cell's C expression is a POINTER, which is why the base needs a
        -- dereference and the field needs an address -- the two spellings `StoreField` and `Load`
        -- then consume.
        if B.FieldAddress:isclassof(op) then
            local cell_type = type_at(block, position - 1 - op.cell.distance, op.cell.output)
            local contents = cell_type.contents
            return C.Unary('&', C.Field(C.Unary('*',
                value_expr(E, block, answers, position, op.cell, brand)),
                field_name(contents.fields[op.field + 1], op.field)))
        end
        if B.StoreField:isclassof(op) then
            local record_type = type_at(block, position - 1 - op.record.distance, op.record.output)
            local contents = record_type.contents
            return C.Assign(
                C.Field(C.Unary('*', value_expr(E, block, answers, position, op.record, brand)),
                    field_name(contents.fields[op.field + 1], op.field)),
                value_expr(E, block, answers, position, op.value, brand))
        end
        if B.Unary:isclassof(op) then
            local operand = value_expr(E, block, answers, position, op.operand, brand)
            if op.operator == S.Not then return C.Unary('!', operand) end
            if op.operator == S.BitNot then return C.Unary('~', operand) end
            -- Unary minus wraps like every other Int operation.
            return cast_to(E, 'int64_t',
                C.Binary('-', cast_to(E, 'uint64_t', int_expr(0)), cast_to(E, 'uint64_t', operand)))
        end
        if B.Binary:isclassof(op) or B.CheckedBinary:isclassof(op) then
            return binary_expr(E, op.operator,
                value_expr(E, block, answers, position, op.left, brand),
                value_expr(E, block, answers, position, op.right, brand))
        end
        error('no emission rule for ' .. tostring(getmetatable(op) and getmetatable(op).kind), 0)
    end



    -- The signature: the result is the first non-effect result and the parameters are the packet
    -- minus the effect. A function with NO non-effect result prints as `void`, which is how §2.6's
    -- `unload` gets the signature the document writes without the emitter knowing about unload.
    local function signature_of(E, belt)
        local block = belt.blocks[1]
        local result, returned
        for i, type_ in ipairs(belt.signature.results) do
            if type_ ~= B.Effect then result, returned = ctype(E, type_), i break end
        end
        local parameters = L()
        for i, parameter in ipairs(block.parameters) do
            if parameter.type ~= B.Effect then
                parameters:insert(C.Parameter(ctype(E, parameter.type), entity('', block, i - 1)))
            end
        end
        -- §11.7: linkage is a property of the INSTANCE, not something the emitter infers from the
        -- name. `let_module_init` was the only exported function, so comparing the name worked; the
        -- moment a top-level word gets a host entry point (§2.6), a name comparison is a string
        -- standing in for a closed set -- and the second exported instance is what makes that a bug.
        return { result = result, returned = returned, parameters = parameters,
                 exported = belt.exported }
    end

    -- One edge: write the target's parameters from this edge's arguments, then go.
    --
    -- Those assignments ARE §S28's identity phi written out. The target's parameter IS the edge's
    -- argument, so a value that crosses a join is one plain C assignment -- and the agreement the
    -- join also requires is about PLACES, which have no representation and so write nothing.
    local function edge_statements(E, belt, block, answers, brand, exit_at, edge)
        local statements = L()
        local target = belt.blocks[edge.target]
        for index, ref in ipairs(edge.arguments) do
            local parameter = target.parameters[index]
            local type_ = parameter and ctype(E, parameter.type)
            if type_ then
                statements:insert(C.Assign(
                    C.Name(entity(brand_of(edge.target), target, index - 1)),
                    value_expr(E, block, answers, exit_at, ref, brand)))
            end
        end
        statements:insert(C.Goto('b' .. edge.target))
        return C.Block(statements)
    end

    -- The exit. A `Return` returns, a `Jump` goes, and a `Branch` does both once per edge.
    local function exit_of(E, belt, block, answers, brand, exit_at, signature)
        local exit = block.exit
        if B.Return:isclassof(exit) then
            local value = signature.returned
                and value_expr(E, block, answers, exit_at, exit.values[signature.returned], brand)
            return C.Return(value)
        end
        if B.Jump:isclassof(exit) then
            return edge_statements(E, belt, block, answers, brand, exit_at, exit.edge)
        end
        if B.Trap:isclassof(exit) then
            -- §1.5 traps where C would be undefined, and the one caller is §12.1's runtime index: an
            -- index that names no member. `abort` is the only library the emitted C needs.
            E.includes.stdlib = true
            return C.Evaluate(C.Call(C.Name('abort'), L{}))
        end
        if B.Branch:isclassof(exit) then
            return C.If(value_expr(E, block, answers, exit_at, exit.condition, brand),
                edge_statements(E, belt, block, answers, brand, exit_at, exit.yes),
                edge_statements(E, belt, block, answers, brand, exit_at, exit.no))
        end
        error('no emission rule for the exit of ' .. belt.name, 0)
    end

    -- Every reachable block, in the order `Known` walked them -- which starts at the entry.
    --
    -- An unreachable block is not emitted: reachability is §12.3's demand one level below
    -- instances (§S30). `Lower` still builds such a block, because a split's join exists before
    -- either arm -- and only the graph says whether anything arrives.
    local function body_of(E, belt, known, signature)
        local statements = L()

        -- A non-entry block's parameters are locals of the FUNCTION, declared before the first
        -- label: C forbids a `goto` that jumps into the scope of a variably modified object, and
        -- declaring them once is what lets an edge ASSIGN a parameter rather than declare it.
        for _, id in ipairs(known.order) do
            if id ~= 1 then
                local block = belt.blocks[id]
                for index, parameter in ipairs(block.parameters) do
                    local type_ = ctype(E, parameter.type)
                    if type_ then
                        statements:insert(C.Declare(type_,
                            entity(brand_of(id), block, index - 1), nil))
                    end
                end
            end
        end

        for _, id in ipairs(known.order) do
            local block = belt.blocks[id]
            local brand = brand_of(id)
            local answers, fates = known.answers[id], known.fates[id]
            local exit_at = #block.parameters + #block.instructions
            if id ~= 1 then statements:insert(C.Label('b' .. id)) end

            for position = #block.parameters, exit_at - 1 do
                -- §12.5: the fate is consumed, not recomputed. `Materialized` is the ONLY fate
                -- that writes C: `Immediate` needs no variable because every use is the constant,
                -- and `Dropped` is the belt talking about something the machine does not do.
                if J.Materialized:isclassof(fates[position + 1]) then
                    local instruction = block.instructions[position - #block.parameters + 1]
                    local type_ = instruction.results[1]
                    local op = instruction.operation.operation
                    -- §3.4's stores are STATEMENTS. C has no assignment expression in this
                    -- vocabulary, and a store writes rather than produces -- so its effect result
                    -- becomes the statement instead of wrapping one.
                    -- An `Allocate` declares its STORAGE: the belt type is `Cell(T)` but the C
                    -- object is a `T`, and the cell value is that object's address.
                    if B.Allocate:isclassof(op) then
                        statements:insert(C.Declare(ctype(E, type_.contents), entity(brand, block, position),
                            instruction_expr(E, block, answers, position, instruction, brand)))
                    elseif B.Store:isclassof(op) or B.StoreField:isclassof(op) then
                        statements:insert(
                            instruction_expr(E, block, answers, position, instruction, brand))
                    elseif type_ == B.Effect then
                        statements:insert(C.Evaluate(
                            instruction_expr(E, block, answers, position, instruction, brand)))
                    else
                        statements:insert(C.Declare(ctype(E, type_), entity(brand, block, position),
                            instruction_expr(E, block, answers, position, instruction, brand)))
                    end
                end
            end

            statements:insert(exit_of(E, belt, block, answers, brand, exit_at, signature))
        end
        return C.Block(statements)
    end

    -- The belt's instances are a list, and a call names one by index. The mapping lives here
    -- because a target is an emitter concern: the belt orders instances, the emitter spells them.
    function Emit.run(unit, belts, known, k_ok, k_diag)
        local E = emitter()
        E.callees = {}
        for index, belt in ipairs(belts) do E.callees[index] = belt.name end

        -- Signatures first, because a signature is what registers a struct a declaration names.
        local signatures = {}
        for index, belt in ipairs(belts) do signatures[index] = signature_of(E, belt) end

        -- Prototypes, because demand order is not dependency order: the root is emitted first and
        -- calls what it demanded, so a definition can precede its callee.
        local prototypes = L()
        for index, belt in ipairs(belts) do
            local signature = signatures[index]
            prototypes:insert(C.Function(belt.name, false, signature.exported,
                signature.result or C.Void, signature.parameters, nil))
        end

        local definitions = L()
        for index, belt in ipairs(belts) do
            local signature = signatures[index]
            definitions:insert(C.Function(belt.name, false, signature.exported,
                signature.result or C.Void, signature.parameters,
                body_of(E, belt, known[index], signature)))
        end

        -- Structs LAST, and this is not a style choice. A signature names the packet and the
        -- result, but a BODY can be the first place a record type appears -- a value carried
        -- across a split is a parameter of the target block, and no signature ever mentions it.
        -- Emitting the struct list before the bodies therefore leaves those structs undefined:
        -- the C still compiles for simple programs, and fails with "storage size isn't known" the
        -- moment control flow carries a record.
        local declarations = L()
        -- A host symbol is EXTERNAL: it is defined outside this translation unit, and the language
        -- promised nothing about who defines it (§3.6). `external` is what prints it without
        -- `static`, which is the same distinction that decides linkage for our own instances.
        for symbol, shape in pairs(E.hosts) do
            local parameters = L()
            for index, parameter in ipairs(shape.parameters) do
                parameters:insert(C.Parameter(parameter, 'a' .. index))
            end
            declarations:insert(C.Function(symbol, true, true, shape.result or C.Void, parameters, nil))
        end
        for _, struct in ipairs(E.structs) do declarations:insert(struct) end
        for _, prototype in ipairs(prototypes) do declarations:insert(prototype) end
        for _, definition in ipairs(definitions) do declarations:insert(definition) end

        local includes = L()
        if E.includes.stdint then includes:insert('stdint.h') end
        if E.includes.stdbool then includes:insert('stdbool.h') end
        -- A trapping division is the one place the emitted C needs a library: `abort` is the
        -- standard spelling of "leave through the host's trap hook" until the host vocabulary has
        -- one of its own. Nothing else asks for it, so nothing else includes it.
        if E.includes.stdlib then includes:insert('stdlib.h') end
        -- `TextSize` is the one conversion that is a library call rather than a cast, because a
        -- `Text` carries no length in this representation: the length is what the operation asks for.
        if E.includes.string then includes:insert('string.h') end

        local out = C.Unit(includes, declarations)
        unit.ambient.c = out
        return k_ok(unit, out)
    end

    return Emit
end

end)

-- let/print.lua
module('let.print', function(require, ...)
-- Render the C output vocabulary. This prints C; it decides no Let semantics.
return function(V)
local C=V.C
local function uint64_text(hi,lo) return ('0x%08x%08xULL'):format(hi,lo) end
-- Small magnitudes print in decimal so the emitted C stays readable; anything else keeps
-- the exact hexadecimal form, which also avoids ever writing INT64_MIN as a negated literal.
local function integer(hi,lo)
    if hi==0 and lo<2147483648 then return ('INT64_C(%d)'):format(lo) end
    if hi==4294967295 and lo>=2147483648 then return ('(-INT64_C(%d))'):format(4294967296-lo) end
    return '((int64_t)' .. uint64_text(hi,lo) .. ')'
end
local function quoted(text)
    local parts={'"'}
    for i=1,#text do
        local byte=text:byte(i)
        parts[#parts+1]=('\\%03o'):format(byte)
    end
    parts[#parts+1]='"'
    return table.concat(parts)
end
local function indent(level) return string.rep('    ',level) end

function C.Type:print() error('missing C type printer',0) end
function C.Void:print() return 'void' end
function C.Bool:print() return 'bool' end
function C.I64:print() return 'int64_t' end
function C.U64:print() return 'uint64_t' end
function C.F64:print() return 'double' end
function C.U8:print() return 'uint8_t' end
function C.U32:print() return 'uint32_t' end
function C.F32:print() return 'float' end
function C.Size:print() return 'size_t' end
function C.Pointer:print() return self.pointee:print() .. '*' end
function C.Named:print() return self.name end

function C.Expr:print() error('missing C expression printer',0) end
function C.Integer:print() return integer(self.hi,self.lo) end
function C.Float:print()
    if self.value~=self.value then return 'NAN' end
    if self.value==math.huge then return 'INFINITY' end
    if self.value==-math.huge then return '(-INFINITY)' end
    return string.format('%a',self.value)
end
function C.CString:print() return 'const char *' end
function C.Boolean:print() return self.value and 'true' or 'false' end
function C.String:print() return quoted(self.value) end
function C.Name:print() return self.name end
function C.Unary:print() return '(' .. self.operator .. self.operand:print() .. ')' end
function C.Binary:print() return '(' .. self.left:print() .. ' ' .. self.operator .. ' ' .. self.right:print() .. ')' end
function C.Cast:print() return '((' .. self.type:print() .. ')' .. self.value:print() .. ')' end
function C.Comma:print()
    local parts = {} for _, value in ipairs(self.values) do parts[#parts + 1] = value:print() end
    return '(' .. table.concat(parts, ', ') .. ')'
end
function C.Conditional:print()
    return '(' .. self.condition:print() .. ' ? ' .. self.yes:print() .. ' : ' .. self.no:print() .. ')'
end
function C.Call:print()
    local parts={} for _,argument in ipairs(self.arguments) do parts[#parts+1]=argument:print() end
    return self.callee:print() .. '(' .. table.concat(parts,', ') .. ')'
end
function C.Field:print() return '(' .. self.base:print() .. ').' .. self.name end
function C.Index:print() return '(' .. self.base:print() .. ')[' .. self.index:print() .. ']' end
function C.Compound:print()
    local parts={} for _,field in ipairs(self.fields) do parts[#parts+1]=field:print() end
    return '((' .. self.type:print() .. '){' .. table.concat(parts,', ') .. '})'
end
-- A designated initializer names each member it sets. The compiler uses it for a sum, so only
-- the tag and the active alternative are written and the rest is left to C's zero-fill.
function C.Init:print()
    local parts={} for _,field in ipairs(self.fields) do parts[#parts+1]='.' .. field.name .. ' = ' .. field.value:print() end
    return '((' .. self.type:print() .. '){' .. table.concat(parts,', ') .. '})'
end

-- Renders one statement. `lines` accumulates output; `level` is the indent depth.
local function statement(node,level,lines)
    local pad=indent(level)
    if C.Declare:isclassof(node) then
        local text=node.type:print() .. ' ' .. node.name
        if node.initial then text=text .. ' = ' .. node.initial:print() end
        lines[#lines+1]=pad .. text .. ';'
    elseif C.Assign:isclassof(node) then
        lines[#lines+1]=pad .. node.place:print() .. ' = ' .. node.value:print() .. ';'
    elseif C.Evaluate:isclassof(node) then
        lines[#lines+1]=pad .. node.value:print() .. ';'
    elseif C.Block:isclassof(node) then
        lines[#lines+1]=pad .. '{'
        for _,child in ipairs(node.statements) do statement(child,level+1,lines) end
        lines[#lines+1]=pad .. '}'
    elseif C.If:isclassof(node) then
        lines[#lines+1]=pad .. 'if (' .. node.condition:print() .. ')'
        statement(node.yes,level,lines)
        if node.no then lines[#lines+1]=pad .. 'else'; statement(node.no,level,lines) end
    elseif C.While:isclassof(node) then
        lines[#lines+1]=pad .. 'while (' .. node.condition:print() .. ')'
        statement(node.body,level,lines)
    elseif C.Break:isclassof(node) then
        lines[#lines+1]=pad .. 'break;'
    elseif C.Switch:isclassof(node) then
        -- C's own construct for a select on an integer, so a lowering that needs one writes one
        -- rather than a function. A case with no value is the default arm.
        lines[#lines+1]=pad .. 'switch (' .. node.value:print() .. ') {'
        for _,case in ipairs(node.cases) do
            lines[#lines+1]=indent(level+1) .. (case.value and ('case ' .. case.value:print() .. ':') or 'default:')
            for _,child in ipairs(case.body) do statement(child,level+2,lines) end
        end
        lines[#lines+1]=pad .. '}'
    elseif C.Label:isclassof(node) then
        lines[#lines+1]=node.name .. ':;'
    elseif C.Goto:isclassof(node) then
        lines[#lines+1]=pad .. 'goto ' .. node.name .. ';'
    elseif C.Return:isclassof(node) then
        lines[#lines+1]=node.value and (pad .. 'return ' .. node.value:print() .. ';') or (pad .. 'return;')
    else error('missing C statement printer',0) end
end

-- An empty list must print as (void): a bare () is an unprototyped declaration in C,
-- which conflicts with a later definition that passes promoted arguments.
local function parameters(list)
    if #list==0 then return 'void' end
    local parts={} for _,parameter in ipairs(list) do parts[#parts+1]=parameter.type:print() .. ' ' .. parameter.name end
    return table.concat(parts,', ')
end

local function declaration(node,lines)
    -- A union is a declaration like a struct, and §3.5's sum needs one: the payload is a union of
    -- the alternatives because only one of them has ever been written.
    if C.Struct:isclassof(node) or C.Union:isclassof(node) then
        lines[#lines+1]=(C.Union:isclassof(node) and 'union ' or 'struct ') .. node.name .. ' {'
        for _,field in ipairs(node.fields) do lines[#lines+1]='    ' .. field.type:print() .. ' ' .. field.name .. ';' end
        lines[#lines+1]='};'
    elseif C.Function:isclassof(node) then
        -- `extern` is a host-provided symbol, `exported` is ours but reachable from outside, and
        -- anything else is `static` -- **including a prototype**. A forward declaration and its
        -- definition must agree on linkage, and demand order is not dependency order, so the
        -- emitter needs prototypes for its own static functions.
        local prefix
        if node.external then prefix='extern '
        elseif node.exported then prefix=''
        else prefix='static ' end
        local head=prefix .. node.result:print() .. ' ' .. node.name .. '(' .. parameters(node.parameters) .. ')'
        if not node.body then lines[#lines+1]=head .. ';'; return end
        lines[#lines+1]=head .. ' {'
        statement(node.body,1,lines)
        lines[#lines+1]='}'
    elseif C.Global:isclassof(node) then
        lines[#lines+1]='static ' .. node.type:print() .. ' ' .. node.name .. ';'
    elseif C.Raw:isclassof(node) then
        lines[#lines+1]=node.code
    else error('missing C declaration printer',0) end
end

-- A null body is a forward declaration; `external` marks a host-provided symbol.
function C.Unit:print()
    local lines={}
    -- An include is a name: `<x>` for a system header, and a QUOTED one when the spelling starts
    -- with a quote, which is what a local header is. The distinction is C's, not ours, so the
    -- spelling carries it rather than a second field.
    for _,include in ipairs(self.includes) do
        if include:sub(1, 1) == '"' then
            lines[#lines+1]='#include ' .. include
        else
            lines[#lines+1]='#include <' .. include .. '>'
        end
    end
    if #lines>0 then lines[#lines+1]='' end
    for _,node in ipairs(self.declarations) do declaration(node,lines); lines[#lines+1]='' end
    return table.concat(lines,'\n')
end
V.print=function(unit) return unit:print() end
end

end)

-- let/cli.lua
module('let.cli', function(require, ...)
-- The command line: one file in, one C translation unit out, diagnostics on stderr.
--
-- The generated unit is a MODULE and not a program. §2.6 makes the host a separate thing that supplies
-- `main`, calls `let_module_init`, and -- only when the module owns something -- calls
-- `let_module_unload` and gives the value up. So this writes the unit and says nothing about linking,
-- because linking is the host's business and every attempt to guess it would be a lie about the ABI.
--
-- The exit codes are §13's three kinds, because a script that cannot tell "your program is wrong" from
-- "the compiler is wrong" cannot report either: 0 ok, 1 Reject, 2 Missing or Bug.
return function(V)
    local Context = V.Context
    local compile = require('let.compile')(V)

    local function report(diagnostic)
        if not diagnostic then
            io.stderr:write('letc: the compiler stopped without a diagnostic\n')
            return 2
        end
        local span = diagnostic.span
        local where = ''
        if span then
            where = ('%s:%d:%d: '):format(tostring(span.file), tonumber(span.line) or 0,
                tonumber(span.column) or 0)
        end
        local kind = 'error'
        local code = 1
        if diagnostic:is_missing() then
            kind = 'unimplemented'
            code = 2
        elseif diagnostic:is_bug() then
            kind = 'internal'
            code = 2
        end
        -- `why` is a Report value, so its own spelling carries the vocabulary's name. A message a
        -- person reads should not: `MismatchedType`, not `Report.MismatchedType`.
        local why = tostring(diagnostic.why):gsub('^Report%.', '')
        -- A SYNTAX error carries the parser's own message, and that message already says where --
        -- `file:line:column: expected ...` -- so the constructor around it would say the position
        -- twice and the vocabulary once too often.
        if V.Report.Syntax:isclassof(diagnostic.why) then
            io.stderr:write(diagnostic.why.detail .. '\n')
            return code
        end
        io.stderr:write(('%s%s: %s\n'):format(where, kind, why))
        return code
    end

    return function(argv)
        local input, output
        local index = 1
        while argv[index] do
            local argument = argv[index]
            if argument == '-h' or argument == '--help' then
                io.stderr:write('usage: letc input.let [-o output.c]\n')
                return 0
            elseif argument == '-o' then
                index = index + 1
                output = argv[index]
                if not output then
                    io.stderr:write('letc: -o wants a path\n')
                    return 2
                end
            elseif argument:sub(1, 1) ~= '-' then
                input = input or argument
            else
                io.stderr:write('letc: unknown option ' .. argument .. '\n')
                return 2
            end
            index = index + 1
        end
        if not input then
            io.stderr:write('usage: letc input.let [-o output.c]\n')
            return 2
        end
        -- `-o -` writes to stdout, which is what a build system wants when it pipes.
        if not output then output = (input:gsub('%.let$', '')) .. '.c' end

        local file = io.open(input, 'rb')
        if not file then
            io.stderr:write('letc: cannot read ' .. input .. '\n')
            return 2
        end
        local text = file:read('*a')
        file:close()

        -- One `Compiler` for the whole run, because it owns `modules`: two files that import the same
        -- third one must share it, and a second load could disagree about the same bytes (§S39).
        local compiler = Context.compiler(V, {})
        local source, diagnostic
        local ok = compile.translation_unit(compiler, text, input,
            function(C, emitted) source = emitted; return true end,
            function(C, d) diagnostic = d; return false end)
        if not ok then return report(diagnostic) end

        if output == '-' then
            io.write(source)
            return 0
        end
        local out = io.open(output, 'wb')
        if not out then
            io.stderr:write('letc: cannot write ' .. output .. '\n')
            return 2
        end
        out:write(source)
        out:close()
        return 0
    end
end

end)

-- let/compile.lua
module('let.compile', function(require, ...)
-- The whole pipeline, in ONE place: text -> `C.Unit`.
--
-- It lived in `test/native.lua`, assembled by hand, which made the TEST the only thing that knew how
-- the phases fit together -- so nothing but a test could compile a file, and a pipeline written twice
-- is a pipeline that can disagree with itself about which phases ran or in what order. §12's order is
-- Resolve, Contract, Lower, Known, Emit; `Known` runs once per DEMANDED INSTANCE because an instance
-- is one belt function plus the answers of its entry packet (§12.4), and `Emit` consumes those
-- answers instead of recomputing them.
return function(V)
    local Context = V.Context

    -- `compiler` is the root context the caller owns: it holds `modules`, so two files that import the
    -- same third one share it, and a `Unit` is one source file under it (§6).
    local compile = {}

    -- `run` is the phases and their exits; the two below are the two USES of it, so nothing else has to
    -- know the order `Known` and `Emit` are driven in.
    function compile.run(compiler, text, name, k_ok, k_diag)
        local unit = compiler:child{ source = name }
        -- §13: a SYNTAX error is the PROGRAM's fault, so it is a `Reject` like any other. The lexer
        -- and the parser SIGNAL one by raising, because a malformed token stream has no judgment to
        -- return -- so this is where that becomes a diagnostic. Without it a typo escaped to the
        -- launcher and came out as "the compiler is broken" (exit 2), which is the one confusion
        -- §13's three kinds exist to prevent.
        local parsed, syntax = pcall(function() return V.parse(V.Lexer(text, name), name, text) end)
        if not parsed then
            -- The span is the unit's START and the position is inside the detail, because a token
            -- stream has no judgment to hang one on: the parser says `file:line:column: ...` in its
            -- message, and the CLI prints that message for a `Syntax` Reject rather than a span.
            return k_diag(unit, V.Report.reject(V.Report.Syntax(tostring(syntax)),
                V.Source.Span(name, 1, 1)))
        end

        local out, diagnostic
        local function ok(C, value) out = value; return true end
        local function bad(C, d) diagnostic = d; return false end

        if not V.Resolve.run(unit, syntax, ok, bad) then return k_diag(unit, diagnostic) end
        local resolved = out
        if not V.Contract.run(unit, resolved, ok, bad) then return k_diag(unit, diagnostic) end
        local program = out
        if not V.Lower.run(unit, program, syntax, ok, bad) then return k_diag(unit, diagnostic) end
        local belts = out

        local answers = {}
        for index, belt in ipairs(belts) do
            local region = unit:child{ instance = belt.name }:region()
            if not V.Known.run(region, belt, ok, bad) then return k_diag(unit, diagnostic) end
            answers[index] = out
        end
        if not V.Emit.run(unit, belts, answers, ok, bad) then return k_diag(unit, diagnostic) end
        return k_ok(unit, out, belts)
    end

    -- Generate, and then RENDER: the emitter produces a `C.Unit` because a host may still add to it
    -- (its own `main`, its own declarations), and rendering is what turns that into text.
    function compile.translation_unit(compiler, text, name, k_ok, k_diag)
        return compile.run(compiler, text, name, function(unit, c_unit)
            return k_ok(unit, V.print(c_unit), c_unit)
        end, k_diag)
    end

    function compile.source(compiler, path, span, k_ok, k_diag)
        local file = io.open(path, 'rb')
        if not file then return k_diag(nil, V.Report.reject(V.Report.MissingModule, span)) end
        local text = file:read('*a')
        file:close()
        return compile.translation_unit(compiler, text, path, k_ok, k_diag)
    end

    return compile
end

end)

local V = require('let')
-- Run as a script rather than required: compile what the command line names. The test is whether
-- this chunk IS the running script, so loading it into another program is not mistaken for it.
local source, script = debug.getinfo(1, 'S').short_src, arg and arg[0]
if script and source == script then
    os.exit(require('let.cli')(V)(arg))
else
    return V
end
